// Generated by scripts/build.js from src/openings/*.js (format: scripts/openings.js) and src/opening-stats.json.
const OPENINGS=[{"id":"italian","name":"Italian Game","eco":"C50–C54","side":"w","group":"open","summary":"Bishop to c4, aimed at f7: quick development, then a slow build-up with c3 and d3 (or a sharp d4).","idea":["White develops the king's knight to attack e5 and puts the bishop on c4, its most aggressive square, where it eyes f7, the square next to Black's king that only the king defends. Black answers in kind with ...Bc5, and both sides race to finish developing and castle.","The modern main line is a slow manoeuvring game, the Giuoco Pianissimo (\"very quiet game\"): White plays c3 and d3, keeps the centre closed, tucks the king away, and brings the queen's knight round via d2 and f1 to g3, eyeing f5 and h5. Later White can still break with d4 or start a queenside expansion with a4 and b4. Black mirrors the set-up, keeps the bishop on the a7–g1 diagonal, and looks for ...d5 at the right moment."],"moves":[["e4","Stakes a claim to the centre (d5 and f5) and opens lines for the queen and the king's bishop."],["e5","Black claims an equal share of the centre and frees the bishop on f8 and the queen."],["Nf3","Develops with a threat: the knight attacks the e5 pawn, so Black must react."],["Nc6","The natural defence: the knight guards e5 and itself controls d4."],["Bc4","The Italian bishop. It aims at f7, the weakest square in Black's camp, and stops ...d5 for now."],["Bc5","The Giuoco Piano: Black copies White, putting the bishop on its own active diagonal, aimed at f2."],["c3","Prepares d4 to build a big centre, and gives the bishop on c4 a retreat square on c2 later."],["Nf6","Develops and hits e4, so White can no longer play d4 without thinking about that pawn."],["d3","The quiet approach: White protects e4 and keeps the centre closed, choosing a long manoeuvring game over an early fight."],["d6","Black supports e5 and opens the diagonal for the light-squared bishop. Both sides now finish development."],["O-O","King to safety; the rook comes towards the centre, where it will support a later d4."],["O-O","Black castles too. The position is symmetrical, but White has an extra tempo."],["Re1","Puts the rook behind the e-pawn, protecting it, and frees f1 for the knight's trip Nb1–d2–f1–g3."],["a6","Makes room for the bishop: after a later b4–b5 or Na3–b5 there is a7 to retreat to, out of reach."],["a4","Gains space on the queenside and stops ...b5, which would harass the bishop on c4."],["Ba7","The bishop steps back before it can be hit by b4 or d4, but keeps its eye on f2 down the same diagonal."],["h3","A useful waiting move: it takes g4 from Black's pieces (no ...Ng4 or ...Bg4 pin), so the knight on f3 stays put."],["h6","Black does the same, stopping Bg5 pinning the knight."],["Nbd2","The queen's knight starts its journey. It cannot go to c3 because the pawn is there, so it heads for f1 and g3."],["Re8","Black puts the rook on the e-file too, behind e5, ready for ...d5 or for when the centre opens."],["Nf1","Next stop g3, where the knight eyes f5 and h5 near Black's king. White's whole army is now regrouped."],["Be6","Black offers to trade off the Italian bishop. If White takes on e6, the f-pawn or rook recaptures and Black's light squares are safe."]],"vars":[{"ref":"two-knights","at":5,"name":"Two Knights Defence","summary":"Black skips ...Bc5 and counterattacks e4 at once: 3...Nf6."},{"ref":"evans-gambit","at":6,"name":"Evans Gambit","summary":"White gives a pawn with 4.b4 to deflect the bishop and grab the centre with tempo."},{"name":"Giuoco Piano: the 5.d4 main line","summary":"The old, direct way: White builds a big centre at once and Black must hit it immediately.","idea":["Instead of the slow d3, White carries out the threat of c3 and plays d4 at once. Black has to break up the centre before it rolls forward: the standard answer is to take on d4, check on b4, and strike back with ...d5. The result is an open position with an isolated pawn for White, and quite equal if Black knows the moves."],"at":8,"moves":[["d4","The point of c3: White takes the centre with two pawns and attacks the bishop on c5."],["exd4","Black must take, otherwise d5 or dxe5 drives the knights away."],["cxd4","White recaptures and has the ideal centre with pawns on e4 and d4."],["Bb4+","The bishop gets out of the way with check, so White must spend a move dealing with it."],["Bd2","The calm reply: White offers to trade bishops and keeps the centre intact."],["Bxd2+","Black trades, which takes the sting out of a later d5 and e5."],["Nbxd2","White recaptures with the knight, which now supports e4."],["d5","The key break: Black hits the centre before White can play e5 and push Black around."],["exd5","White takes; after the recapture the pawn on d4 is isolated."],["Nxd5","Black's knight lands on a fine central square, blockading the isolated pawn."],["Qb3","White piles up against d5 and f7, and the knight on c6 can be pushed with d5."],["Nce7","The knight steps back to support its partner on d5. Black will castle with an equal game; White has active pieces, Black has the better structure."],["O-O","White castles and will put the rooks on c1 and e1. The fight is about the isolated pawn: is it a strength (outposts on e5, c5) or a weakness?"],["O-O","Black is safe and solid. The plan is to blockade d5 and trade pieces, which helps the side against the isolated pawn."]],"vars":[{"name":"The Møller Attack","summary":"White gives up the e4 pawn for a fierce attack: a gambit for players who like adventure.","idea":["Instead of trading bishops, White gives the e4 pawn and races to open the e-file against Black's king, which is still in the centre. Black must know the defence; with it, the position is fine for Black, but over the board the attack is dangerous."],"at":12,"moves":[["Nc3","Blocks the check with a piece and lets e4 go."],["Nxe4","Black accepts and the knight is very active in the centre."],["O-O","White castles and lets Black take the knight on c3: getting the king safe and the rook to e1 matters more than the pawns."],["Bxc3","Black takes, gaining a second pawn on the next move or saving the bishop from being trapped."],["d5","The point: instead of recapturing, White hits the knight on c6 and opens lines while Black's king is in the centre."],["Bf6","The bishop gets back to defend the king's side."],["Re1","The rook lines up against the pinned knight on e4 and Black's king behind it."],["Ne7","The knight steps aside and guards d5 and g6, so that Black can castle soon."],["Rxe4","White wins the piece back. Material is equal again, but Black still needs one move to castle."],["d6","Black stops d6 and opens the bishop on c8. Now castling is next."],["Bg5","White trades off the defender of Black's king's side."],["Bxg5","Black takes the bishop."],["Nxg5","The knight comes into the attack, eyeing h7 and f7."],["O-O","Black finally castles. After 14.Nxh7 Kxh7 15.Qh5+ Kg8 16.Rh4 f5 Black survives with accurate play; the opening has done its job for both sides."]],"vars":[],"played":[4,4,4,4,4,3,3,3,3,3,1,1,1,0]}],"played":[508,508,143,143,48,43,43,43,43,43,39,4,4,4]},{"name":"Hungarian Defence","summary":"A modest, solid reply: Black avoids all of White's attacking tries.","idea":["Black declines the fight over f7 and c5 and develops the bishop on e7, where it guards the king's side. It is solid but passive: White gets an easy space advantage with d4. A good choice against an opponent who loves sharp gambits."],"at":5,"moves":[["Be7","A safe square: the bishop covers g5 and f6, and there is no target for White on c5."],["d4","White takes the centre at once, since Black has not yet attacked e4."],["d6","Black holds e5. Taking on d4 would give White a free hand in the centre."],["d5","White gains more space and pushes the knight away from the centre."],["Nb8","The knight goes back to re-route via d7. Black has a cramped but sound position, like a Philidor."]],"vars":[],"played":[58,30,13,4,4]}],"played":[94897,31689,29752,26231,7835,3446,1640,1597,1082,1170,714,292,170,47,35,27,150,84,137,130,15,15]},{"id":"two-knights","name":"Two Knights Defence","eco":"C55–C59","side":"b","group":"open","summary":"Black hits e4 with 3...Nf6 instead of ...Bc5, ready to give a pawn for fast development if White goes for f7.","idea":["Instead of copying White with ...Bc5, Black develops the king's knight and counterattacks the e4 pawn at once. It is a more combative reply to the Italian bishop: it invites 4.Ng5, the most direct attack on f7, and Black must be ready to give up a pawn. In return Black gets a lead in development and targets in White's camp.","In the main line, 4.Ng5 d5 5.exd5 Na5, Black chases the Italian bishop and lets the d-pawn go. White ends up a pawn ahead, but the knight is pushed back to an awkward square, the bishop retreats to the modest e2, and Black's pawn on e4 cramps White's kingside. White's task is to untangle, castle and hold on to the extra pawn; Black aims for quick piece play, open lines for the two bishops and pressure on the kingside. The natural 5...Nxd5 is a mistake in practice, because it allows the Fried Liver sacrifice on f7.","White does not have to play Ng5. 4.d4 opens the centre for gambit play (the Modern and Max Lange lines), and 4.d3 is the modern quiet choice: White protects e4, avoids all of Black's tactics and steers the game into a slow Italian-style manoeuvring fight."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre and frees the bishop on f8."],["Nf3","Develops with a threat to the e5 pawn."],["Nc6","Defends e5 and also controls d4."],["Bc4","The Italian bishop aims at f7, the square only Black's king defends."],["Nf6","The Two Knights: instead of ...Bc5, Black counterattacks e4 straight away and dares White to go after f7."],["Ng5","The most direct reply: knight and bishop both hit f7, threatening Nxf7, which would fork the queen and the rook on h8."],["d5","The only good defence. The pawn blocks the bishop's diagonal to f7 and opens lines for Black's pieces."],["exd5","White takes, and the pawn on d5 now shields f7 from the bishop for the moment."],["Na5","The main line. Black does not recapture, which would allow Nxf7; instead the knight attacks the bishop on c4 and Black plays for development rather than the pawn."],["Bb5+","White keeps the bishop with a check, so that the d5 pawn stays protected by the queen and does not need the bishop."],["c6","Black blocks the check, and the c-pawn attacks both the bishop on b5 and the pawn on d5."],["dxc6","White accepts: after the recapture Black is a pawn down for good."],["bxc6","Black recaptures with tempo on the bishop and opens the b-file for the rook. Black is a pawn down and the queenside pawns are split (a7 and c6 are both isolated), a fair price for the time gained."],["Be2","The bishop retreats to safety on e2, where it covers the kingside. 8.Qf3 is the main alternative."],["h6","Black kicks the knight from g5 before getting on with development."],["Nf3","The main retreat, guarding the kingside. 9.Nh3 is Steinitz's alternative."],["e4","Black gains space with tempo and harasses the knight again: White's pieces keep moving while Black's come out."],["Ne5","The knight takes up a central post, the best square available."],["Bd6","Develops with an attack on the knight on e5, and from d6 the bishop also points at White's kingside down the b8–h2 diagonal."],["d4","White supports the knight and claims the centre. 11.f4, defending it with the f-pawn, is the other main line."],["exd3","Black takes en passant: this removes the knight's pawn support and opens lines while White is still not castled."],["Nxd3","The knight recaptures, but on d3 it blocks the d-file and the bishop on c1, so White needs time to untangle."],["Qc7","Queen and bishop line up against h2, which stops White developing smoothly. Black castles next and has active pieces for the pawn."]],"vars":[{"name":"Fried Liver Attack","summary":"The natural recapture allows White to sacrifice a knight on f7 and drag Black's king into the open.","idea":["After 5...Nxd5 White can play the famous sacrifice 6.Nxf7, giving a knight for a pawn to pull the king out to e6, where the queen, bishop and knight attack it. Black can survive with exact play, and some engines say the defence holds, but in practice the attack is very hard to meet over the board. This is the main reason Black plays 5...Na5."],"at":9,"moves":[["Nxd5","The natural move: it regains the pawn, but it leaves the d5 knight and the king on the same line as White's pieces."],["Nxf7","The Fried Liver: White gives a knight to drag the king out and fork the queen and the rook on h8."],["Kxf7","Black must take, otherwise the knight simply wins material."],["Qf3+","A double attack: the queen checks the king and hits the knight on d5."],["Ke6","The only way to keep the knight: the king itself guards it, but now stands in the middle of the board."],["Nc3","White adds a third attacker to d5. The knight there is pinned against the king by the bishop on c4."],["Nb4","Black brings a second defender to d5, and also threatens ...Nxc2+, forking the king and the rook on a1."],["Qe4","The queen guards c2, keeps hitting d5, and stands on the e-file where d4 will open lines against the king."],["c6","Black adds a pawn to the defence of d5."],["a3","White drives the knight from b4, so that it no longer defends d5 or threatens c2."],["Na6","The knight steps back and heads for c7, where it will guard d5 again. White has given a knight for a pawn and continues with d4, opening the centre against the king; Black must defend very accurately."]],"vars":[],"played":[7,3,3,3,3,3,3,0,0,0,0]},{"name":"6.d3: the quieter retreat","summary":"White keeps the extra pawn by protecting the bishop with the d-pawn instead of checking on b5.","idea":["With 6.d3 White gives the bishop on c4 a defender and keeps the d5 pawn. Black still gets active play: the knight on g5 is driven back, ...e4 hits the f3 knight, and Black takes the bishop pair. Black is a pawn down but develops quickly and has open lines for the bishops."],"at":10,"moves":[["d3","Protects the bishop, so it can stay on c4 and keep guarding the extra pawn on d5."],["h6","Black kicks the knight before it can join an attack."],["Nf3","The knight goes back to its natural square."],["e4","Black gains space with tempo, hitting the knight again."],["Qe2","White attacks the e4 pawn and pins it against Black's king on the e-file."],["Nxc4","Black takes the bishop and gets the bishop pair."],["dxc4","White recaptures; the doubled c-pawns hold d5 and b5 but are a long-term weakness."],["Bc5","Black develops actively, aims at f2 and gets ready to castle. The pinned e4 pawn is protected by the knight, and Black has fair play for the pawn."]],"vars":[],"played":[9,6,6,5,1,1,1,0]},{"name":"4.d4: open centre","summary":"White opens the centre at once and gives the e4 pawn for a lead in development.","idea":["With 4.d4 exd4 5.O-O White castles and leaves e4 to its fate, planning Re1 to pin and win back material on the e-file. After 5...Nxe4 the position becomes very open: Black hits back in the centre with ...d5 and has to take care over the e-file. 5...Bc5 instead leads to the wild Max Lange Attack."],"at":6,"moves":[["d4","White opens the centre before Black is castled and before ...d5 can be prepared."],["exd4","Black takes the pawn: White's centre is gone and e4 is now hanging."],["O-O","White castles and ignores e4: the rook will come to e1 with a pin on the e-file."],["Nxe4","Black grabs the pawn. The knight is active, but stands on the open e-file in front of the king."],["Re1","The rook pins the knight against Black's king, since the e-pawn is gone."],["d5","Black defends the knight with a pawn and counterattacks the bishop on c4."],["Bxd5","White uses the pin: the bishop takes the pawn, and the queen recaptures."],["Qxd5","The queen recaptures and now also defends the knight on e4."],["Nc3","Develops with gain of time: the knight hits the queen and adds a second attacker to the pinned knight on e4."],["Qa5","The queen keeps watch over the e5 square and eyes the knight on c3 and the rook on e1 behind it. 8...Qh5 is the other main move."],["Nxe4","White wins the pinned knight back. Black keeps an extra pawn on d4 but must deal with the open e-file."],["Be6","Black blocks the e-file: otherwise the knight on e4 could move with a discovered check from the rook."],["Neg5","White attacks the pinned bishop on e6 with knight and rook."],["O-O-O","Black castles long, gets the king away from the e-file and brings a rook to d8 behind the d4 pawn. After 11.Nxe6 fxe6 12.Rxe6 Bd6 material is level and Black's active pieces make up for the loose pawn structure."]],"vars":[{"name":"Max Lange Attack","summary":"Black defends the d4 pawn with the bishop and White replies 6.e5, leading to one of the sharpest lines in the open games.","idea":["After 5...Bc5 6.e5 d5 7.exf6 dxc4 8.Re1+ both sides have taken a piece and the game is pure tactics: White has a pawn on f6 tearing at the kingside and the e-file against the king, while Black has two strong passed pawns on c4 and d4 and quick development. Black usually castles queenside. Both sides must know the theory well."],"at":9,"moves":[["Bc5","Black keeps the extra d4 pawn by protecting it with the bishop."],["e5","White kicks the knight from f6, gaining time to open lines against the king."],["d5","The counterattack: Black ignores the threat to the knight and hits the bishop on c4."],["exf6","White takes the knight. The pawn on f6 now threatens fxg7."],["dxc4","Black takes the bishop back; material is level apart from Black's extra pawn, and the c4 and d4 pawns cramp White's queenside."],["Re1+","The rook checks on the open e-file, so Black cannot simply castle."],["Be6","Black blocks the check with the bishop."],["Ng5","White attacks the pinned bishop on e6."],["Qd5","The queen defends the bishop on e6 and keeps an eye on g5."],["Nc3","Develops with a hit on the queen. If 10...dxc3 then 11.Qxd5, since the d-file is now open."],["Qf5","The queen keeps guarding e6. White continues 11.Nce4, and the game becomes a fierce tactical battle where Black often castles queenside."]],"vars":[],"played":[6,8,8,8,8,1,1,0,0,0,0]}],"played":[169,168,51,42,41,41,40,40,40,12,12,12,7,7]},{"name":"4.d3: the modern quiet line","summary":"White protects e4 and avoids all the tactics, aiming for a slow, Spanish-style game.","idea":["Modern players often prefer 4.d3, which keeps the e4 pawn safe and leaves Black nothing to attack. After 4...Bc5 the game transposes to the Giuoco Pianissimo; with 4...Be7 Black chooses a Ruy Lopez set-up instead, chasing the Italian bishop with ...Na5 and gaining space on the queenside with ...a6, ...b5 and ...c5."],"at":6,"moves":[["d3","White protects e4 and keeps the centre closed, so Black's quick counterattacks have no target."],["Be7","A modest, flexible square: the bishop guards the kingside and Black keeps ...d5 or ...d6 in reserve. 4...Bc5 would transpose to the Italian."],["O-O","White castles before deciding on a plan in the centre."],["O-O","Black castles too."],["Re1","The rook supports e4 and leaves f1 free for the queen's knight on its way to g3."],["d6","Black holds e5 solidly and opens the diagonal for the bishop on c8."],["c3","Prepares d4 later, and gives the bishop a retreat square on c2."],["Na5","The knight hits the Italian bishop, so that White must spend time to keep it."],["Bb5","White avoids the exchange; the bishop will go back via a4 to c2."],["a6","Black drives the bishop back, gaining queenside space with tempo."],["Ba4","The bishop retreats, still eyeing the queenside."],["b5","Black gains more space with tempo on the bishop."],["Bc2","On c2 the bishop is safe from the knight and waits on the b1–h7 diagonal for the moment d3–d4 opens it."],["c5","The c-pawn is free because the knight went to a5. The structure now looks like a Closed Ruy Lopez, with a long manoeuvring game ahead."]],"vars":[],"played":[3546,911,700,655,316,317,28,21,21,20,20,17,17,89]}],"played":[94897,31689,29752,26231,7835,4161,432,424,424,377,368,308,308,308,23,23,6,4,4,2,2,2,2,0]},{"id":"evans-gambit","name":"Evans Gambit","eco":"C51–C52","side":"w","group":"open","summary":"White gives the b-pawn with 4.b4 to deflect the bishop and build a big centre with gain of time.","idea":["White offers the b-pawn to drive Black's bishop away from c5. After 4...Bxb4 5.c3 the bishop is attacked again, and d4 follows, building the ideal pawn centre with gain of time. Captain Evans' gambit was the great attacking weapon of the 19th century and was revived by Kasparov in the 1990s.","For the pawn White gets a lead in development, open lines on the b- and d-files, and well-known attacking ideas: Qb3 against f7, Ba3 to stop Black castling, and e5 to drive away the king's knight. Black has two approaches: hold the centre with ...d6 and give the pawn back for a safe game, as in Lasker's Defence, which often leads to a queenless middlegame, or grab more with ...exd4 and survive an attack.","The gambit is a practical weapon: Black must know precise defences, and in many lines one slip is punished at once. Typical themes are the pin on the c3 pawn from a bishop on a5 once White plays d4, the weak f7 square, and the open b-file."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre."],["Nf3","Develops with a threat to the e5 pawn."],["Nc6","Defends e5 and controls d4."],["Bc4","The Italian bishop, aimed at f7."],["Bc5","Black mirrors White, aiming the bishop at f2."],["b4","The Evans Gambit: White offers a pawn to deflect the bishop and win time for c3 and d4."],["Bxb4","Black accepts. Declining with 4...Bb6 is possible but gives White a free space gain."],["c3","Hits the bishop again and prepares d4, building a centre with tempo."],["Ba5","The main retreat. From a5 the bishop will pin the c3 pawn once White plays d4, so that the pawn cannot recapture on d4 while the king is on e1."],["d4","White strikes in the centre at once, before Black can consolidate."],["d6","Black holds e5 instead of taking, aiming to return the pawn for a safe position."],["O-O","White castles, so the c3 pawn is no longer pinned and the rook can join the play."],["Bb6","Lasker's idea: the bishop drops back to b6, where it presses on d4 and is no longer loose on a5. Black is happy to trade queens."],["dxe5","White opens the d-file to get the pawn back."],["dxe5","Black recaptures and offers the queen exchange on d8."],["Qxd8+","White trades queens; this is the main way to win back the gambit pawn."],["Nxd8","The knight recaptures, so that the king keeps the right to castle; the knight on d8 also guards f7."],["Nxe5","White wins the pawn back, so material is level."],["Be6","Black offers to trade off the dangerous bishop on c4. White has the more active pieces, Black has the sounder pawns: White's a- and c-pawns are isolated, so Black is quite comfortable in this endgame."]],"vars":[{"name":"6...exd4: taking the centre","summary":"Black grabs the d4 pawn too and has to survive a dangerous lead in development.","idea":["Taking on d4 keeps Black's extra pawn but opens lines while Black's king is still in the centre. In the modern 7...Nge7 line Black strikes back with ...d5 to block the Italian bishop. The greedy 7...dxc3, the Compromised Defence, wins a third pawn but lets White develop every piece with tempo."],"at":11,"moves":[["exd4","Black takes a second pawn. The c3 pawn cannot recapture at once because it is pinned by the bishop on a5."],["O-O","White castles, which breaks the pin on c3, so cxd4 is now a threat."],["Nge7","The knight goes to e7 to support ...d5, which will block the bishop on c4 and give some pawns back for safety."],["cxd4","White takes back and has two centre pawns against none."],["d5","The key break: Black hits e4 and the bishop on c4, and after the recapture a knight on d5 will block the bishop's diagonal to f7."],["exd5","White takes, opening the e-file towards Black's uncastled king."],["Nxd5","The knight recaptures and stands well in the centre. Black is still a pawn up; White's typical next move is 10.Ba3, which stops Black castling because the bishop covers f8."]],"vars":[{"name":"Compromised Defence","summary":"Black wins a third pawn, but White gets a huge lead in development.","idea":["The name says it all: Black takes three pawns but compromises the position, falling far behind in development. White hits f7, drives the queen around with e5, recovers one pawn and gets every piece into play; Black must hang on and hope the extra material tells in the end."],"at":13,"moves":[["dxc3","Black takes a third pawn, giving White even more open lines."],["Qb3","The queen lines up behind the bishop against f7, and also hits the pawn on c3 and b7."],["Qf6","The queen guards f7, the main target."],["e5","White gains time by kicking the queen away from f6."],["Qg6","The queen keeps watching f7 from g6."],["Nxc3","White wins one pawn back and develops the knight at the same time."],["Nge7","Black develops and prepares to castle."],["Ba3","The bishop comes out on the a3–f8 diagonal, pressing on the knight on e7 and making it hard for Black to untangle."],["O-O","Black gets the king to safety. White is two pawns down but has all the pieces in play; after 12.Rad1 the compensation is more than enough in practice."]],"vars":[],"played":[0,0,0,0,0,0,0,0,0]}],"played":[4,3,1,1,1,1,1]},{"name":"5...Be7: the safe retreat","summary":"The bishop retreats to e7, out of reach of c3, d4 and queen checks: a modern, solid defence.","idea":["On e7 the bishop is safe from tempo-gaining attacks and guards Black's kingside. Black answers d4 by chasing the Italian bishop with ...Na5. The game Kasparov–Anand, Riga 1995 shows White's attacking plan: the queen swings to the kingside, the e-pawn drives Black's knight around, and the bishop comes to h6."],"at":9,"moves":[["Be7","The bishop goes back to a quiet square where c3, d4 and Qa4+ cannot gain time against it."],["d4","White takes the centre as planned."],["Na5","Black attacks the Italian bishop at once, the piece that makes White's attack dangerous."],["Be2","White keeps the bishop and the pawn centre. 7.Nxe5 Nxc4 8.Nxc4 is the other main line."],["exd4","Black takes, keeping the extra pawn for now."],["Qxd4","The queen recaptures in the centre, eyeing g7 and a7 from d4."],["Nf6","Black develops and hits e4."],["e5","White gains space and time, driving the knight from f6."],["Nc6","The knight comes back into play with tempo on the queen."],["Qh4","The queen moves to the kingside, where the attack will take place."],["Nd5","The other knight lands on a fine central square."],["Qg3","The queen hits g7 down the g-file."],["g6","Black guards g7, but the dark squares around the king are weakened."],["O-O","White castles with a big lead in development. Kasparov–Anand went 12...Nb6 13.c4 d6 14.Rd1 Nd7 15.Bh6, with a famous attack."]],"vars":[],"played":[20,20,19,8,2,2,1,1,1,1,1,1,0,0]},{"name":"Evans Gambit Declined","summary":"Black refuses the pawn and keeps the bishop on its good diagonal.","idea":["By declining, Black avoids all the theory, but the b4 pawn gives White free queenside space. White can push the a-pawn to harass the bishop and use the extra space to post a knight on d5."],"at":7,"moves":[["Bb6","The bishop steps back but stays on the a7–g1 diagonal, aimed at f2."],["a4","White uses the b4 pawn to gain space and threatens a5, chasing the bishop."],["a6","Black gives the bishop a retreat on a7."],["Nc3","Develops; the knight is heading for d5, where it eyes the bishop on b6."],["Nf6","Black develops and attacks e4."],["Nd5","The knight jumps in, attacking the bishop and the knight on f6."],["Nxd5","Black removes the strong knight."],["exd5","The pawn recaptures and hits the knight on c6, which must go to d4 or e7. White has extra queenside space."]],"vars":[],"played":[10,7,7,4,3,1,1,1]}],"played":[94897,31689,29752,26231,7835,3446,64,52,52,28,23,17,0,0,0,0,0,0,0,0]},{"id":"ruy-lopez","name":"Ruy Lopez","eco":"C60–C99","side":"w","group":"open","summary":"The Spanish: 3.Bb5 puts lasting pressure on the defender of e5, leading to rich, strategic middlegames.","idea":["White develops the bishop to b5, attacking the knight on c6, the piece that defends e5. There is no immediate threat, since Bxc6 followed by Nxe5 can be met by ...Qd4, hitting the knight and e4. But the pressure on e5 lasts for many moves and makes Black's life awkward. After 3...a6 4.Ba4 the bishop keeps its eye on c6 and later drops back to b3 and c2, where it aims at Black's kingside.","In the Closed main line both sides build slowly. White plays c3, h3 and d4 to set up a pawn centre, then brings the queen's knight round via d2 and f1 to g3 (the Spanish manoeuvre), aiming for play on the kingside, a well-timed d5 to gain space, or pressure with a4 on the queenside. Black gains space on the queenside with ...b5, ...c5 and ...Na5, holds e5 with ...d6, and looks for counterplay on the c-file or with the breaks ...d5 and ...f5.","The Ruy Lopez is the richest of the open games. Black can choose the Berlin Defence and its queenless middlegame, the dynamic Open Variation with 5...Nxe4, or the Marshall Attack gambit; White can simplify with the Exchange Variation, giving up the bishop for a better pawn structure."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre."],["Nf3","Develops with a threat to the e5 pawn."],["Nc6","Defends e5 and controls d4."],["Bb5","The Spanish bishop attacks the knight that defends e5. It is not a threat yet, but the pressure lasts through the whole opening."],["a6","The Morphy Defence: Black asks the bishop at once. 4.Bxc6 dxc6 5.Nxe5 would not win a pawn, because ...Qd4 forks the knight and e4."],["Ba4","The bishop keeps the pressure on c6 and can later retreat to b3, aiming at f7."],["Nf6","Black develops and attacks e4."],["O-O","White castles and leaves e4 hanging: after 5...Nxe4 6.d4 the centre opens and White wins the pawn back (the Open Variation)."],["Be7","The Closed Ruy Lopez: Black prepares to castle, and the bishop shields the e-file in front of the king."],["Re1","The rook protects e4, and now Bxc6 followed by Nxe5 is a real threat, because e4 no longer hangs."],["b5","Black meets the threat by driving the bishop off the a4–e8 diagonal, gaining queenside space."],["Bb3","The bishop settles on the a2–g8 diagonal, aimed at f7."],["d6","Black supports e5 and opens the diagonal for the bishop on c8."],["c3","Makes a retreat square on c2 for the bishop and prepares d4."],["O-O","Black castles; both sides have finished the first phase of development."],["h3","A key prophylactic move: it stops ...Bg4, which would pin the knight on f3 and add pressure on d4 once White plays it."],["Na5","The Chigorin Variation: the knight hits the bishop on b3 and frees the c-pawn to advance."],["Bc2","The bishop retreats to c2, where it is safe, supports e4 and stays on the b1–h7 diagonal towards Black's king."],["c5","Black gains queenside space and gets ready to put pressure on d4."],["d4","White finally builds the full pawn centre."],["Qc7","The queen protects c5 and steps onto the c-file, which will open after ...cxd4."],["Nbd2","The Spanish manoeuvre begins: the knight will go via f1 to g3 or e3, towards the kingside and the f5 square."],["cxd4","Black opens the c-file. After 13.cxd4 Nc6 the knight comes back to press on d4: Black has queenside play, White has chances on the kingside."]],"vars":[{"name":"Berlin Defence","summary":"Black hits e4 at once and heads for a queenless middlegame that is famously hard to crack.","idea":["Made famous by Kramnik against Kasparov in 2000, the Berlin aims for a solid queenless middlegame. White has a healthy kingside pawn majority (four against three) and the e5 pawn cramps Black; Black has the bishop pair and doubled c-pawns, and the king has lost the right to castle, but without queens it is safe enough. White tries to make the kingside majority count; Black builds a fortress and hopes the bishops will tell later."],"at":5,"moves":[["Nf6","The Berlin: Black ignores the pressure on c6 and hits e4 straight away."],["O-O","White castles and lets the pawn go, planning to win it back in the centre."],["Nxe4","Black takes; with d4 and Re1 coming, the knight will not stay long."],["d4","White opens lines in the centre before Black can castle. 5.Re1 is also played."],["Nd6","The knight retreats with tempo, attacking the bishop on b5."],["Bxc6","White gives up the bishop instead of retreating; after dxe5 the knight on d6 will be hit again."],["dxc6","Black recaptures towards the centre and opens the diagonal for the bishop on c8."],["dxe5","The pawn attacks the knight and gains space."],["Nf5","The knight's best square, where it controls d4 and e7 and is hard to dislodge."],["Qxd8+","White trades queens, and Black's king loses the right to castle."],["Kxd8","Black recaptures with the king. Without queens, its place in the centre is not a big problem."],["Nc3","White develops, watches e4 and d5, and plans h3, Rd1 and a kingside pawn advance."],["Ke8","The king steps off the d-file, where a white rook will soon arrive. Black follows with ...h6 or ...h5, ...Be6 and ...Rd8. 9...Bd7 is the main alternative."]],"vars":[{"name":"Anti-Berlin: 4.d3","summary":"White simply protects e4 and avoids the endgame, keeping the queens on for a slow middlegame.","idea":["Many top players avoid the Berlin endgame with 4.d3. The game turns into a slow manoeuvring battle that looks like the Giuoco Pianissimo, but with White's bishop on b5 (and later a4 and c2). White prepares c3, Re1, Nbd2–f1–g3 and perhaps d4; Black develops actively with ...Bc5 and ...d6."],"at":6,"moves":[["d3","White protects e4 and keeps the queens on."],["Bc5","The most active square for the bishop, aimed at f2."],["c3","Prepares d4 and gives the bishop a retreat route via a4 to c2."],["O-O","Black castles and keeps the pieces flexible."],["O-O","White castles too."],["d6","Black secures e5 and opens the bishop on c8."],["h3","Takes g4 away from Black's bishop and knight, so the knight on f3 cannot be pinned."],["a6","Black asks the bishop to make up its mind."],["Ba4","The bishop keeps out of the way and will drop back to c2, while White prepares Re1 and Nbd2–f1. A long manoeuvring game lies ahead."]],"vars":[],"played":[1486,1200,391,305,266,128,60,19,17]}],"played":[3424,1862,1832,843,839,316,316,316,316,308,308,122,61]},{"name":"Open Variation","summary":"Black takes the e4 pawn and gets free, active piece play in exchange for a slightly loose position.","idea":["In the Open Ruy Lopez Black grabs e4 and gives it back on their own terms, getting quick development and a knight on e4 supported by ...d5. White wins the pawn back with d4 and dxe5, and the e5 pawn gives White space on the kingside. Black has active pieces and queenside space; White aims at the knight on e4 and the c5 and d5 squares. Korchnoi and Anand made it a top-level weapon."],"at":9,"moves":[["Nxe4","The Open Variation: Black takes the pawn and plays for free piece play."],["d4","White opens the centre while Black's king is still in the middle."],["b5","Black drives the bishop away first: once the d-pawn moves, the knight on c6 would otherwise be pinned against the king."],["Bb3","The bishop retreats to b3, where it hits d5 and f7."],["d5","Black supports the knight on e4 and claims a share of the centre."],["dxe5","White wins the pawn back. The pawn on e5 gains space and takes d6 and f6 from Black's pieces."],["Be6","The bishop protects d5, the pawn that holds the knight on e4."],["c3","Gives the bishop a retreat on c2 and takes the b4 and d4 squares from Black's knight."],["Bc5","The bishop takes its most active square, aimed at f2."],["Nbd2","White challenges the strong knight on e4."],["O-O","Black castles."],["Bc2","Now the knight on e4 is attacked twice. Black usually defends it with 11...Bf5, or plays 11...Nxf2, the Dilworth Attack, a famous sacrifice on f2."]],"vars":[],"played":[758,724,581,581,582,567,567,237,95,73,72,68]},{"name":"Marshall Attack","summary":"Black castles first and then gambits the e5 pawn with ...d5 for a fierce attack on White's king.","idea":["Frank Marshall saved this gambit for Capablanca in 1918. Black gives a pawn to open lines and throws everything at White's kingside: the queen goes to h4 and h3, the bishop to d6 and g4, and the rooks join on the e-file. White is a pawn up and must defend accurately. The theory runs very deep and is a mainstay of elite chess, which is why many White players avoid it with 8.a4 or 8.h3."],"at":13,"moves":[["O-O","Black castles before playing ...d6, which keeps the option of ...d5."],["c3","The natural move, preparing d4. It allows the Marshall."],["d5","The Marshall Attack: Black gives the e5 pawn to open lines against White's king."],["exd5","White accepts."],["Nxd5","Black recaptures, leaving e5 to its fate."],["Nxe5","White takes and is a pawn up."],["Nxe5","Black trades knights."],["Rxe5","The rook recaptures; it is active but exposed in the centre."],["c6","Black supports the knight on d5 and prepares ...Bd6 with tempo on the rook."],["d4","White frees the bishop on c1 and takes control of e5 and c5."],["Bd6","With tempo on the rook; the bishop now aims at h2."],["Re1","The rook retreats to safety."],["Qh4","Queen and bishop hit h2 together."],["g3","White blocks the attack on h2, but the light squares around the king are weakened. After 14...Qh3 15.Be3 Bg4 16.Qd3 Rae8 17.Nd2 Black's pieces swarm round White's kingside, and White is a pawn up and must defend."]],"vars":[{"name":"Anti-Marshall: 8.a4","summary":"White sidesteps the gambit and puts pressure on b5 instead.","idea":["With 8.a4 White avoids the Marshall's mountain of theory and starts queenside play straight away. White follows up with d3, keeping e4 solid, so Black has no gambit. The result is a slow Spanish game where White's a-pawn pressure and the open a-file can matter later."],"at":14,"moves":[["a4","White avoids 8.c3 d5 and puts pressure on the b5 pawn."],["Bb7","Black develops the bishop to the long diagonal, where it eyes e4. 8...b4 is the main alternative."],["d3","White protects e4 and keeps the game slow; there is no gambit for Black now."],["d6","Black settles for a solid Spanish structure, with a long manoeuvring game ahead."]],"vars":[],"played":[653,303,295,266]}],"played":[1312,309,183,164,162,152,151,151,121,33,33,31,35,35]},{"name":"Breyer Variation","summary":"The knight goes back to b8 to re-route via d7: one of the most solid and respected Closed Ruy Lopez lines.","idea":["Black's knight returns to b8 and comes back via d7, where it supports e5 and leaves the c-pawn and the long diagonal free. Black sets up a sturdy position with ...Bb7, ...Re8, ...Bf8 and ...g6, then aims for ...c5 or ...d5. White completes the Spanish manoeuvre with the knight to g3 and looks for kingside play or a space gain with d5."],"at":17,"moves":[["Nb8","The Breyer: the knight goes back to re-route via d7, freeing the c-pawn and the long diagonal for the bishop."],["d4","White builds the pawn centre."],["Nbd7","The knight supports e5 from d7."],["Nbd2","The Spanish manoeuvre begins: the knight heads for f1 and g3."],["Bb7","The bishop takes the long diagonal and presses on e4."],["Bc2","The bishop goes to c2, where it defends e4 against the pressure from b7 and is safe from ...c5–c4."],["Re8","The rook supports e5 and frees f8 for the bishop."],["Nf1","The knight continues towards g3."],["Bf8","The bishop drops back to f8; after ...g6 it will go to g7, guarding the king and pressing on the centre."],["Ng3","From g3 the knight eyes f5 and h5."],["g6","Black takes f5 and h5 from the knights and prepares ...Bg7. A classic Spanish middlegame follows: White aims at the kingside, Black at the queenside and centre with ...c5 or ...d5."]],"vars":[],"played":[369,363,364,268,236,224,209,191,188,185,157]},{"name":"Exchange Variation","summary":"White gives up the bishop to double Black's pawns, aiming for an endgame with the better structure.","idea":["Fischer's favourite way to play the Ruy Lopez. After the exchange on c6 and d4, White has a healthy four-against-three pawn majority on the kingside, which can create a passed pawn, while Black's queenside majority is crippled by the doubled c-pawns. Black has the bishop pair and free development in return, and must use them before the endgame arrives."],"at":6,"moves":[["Bxc6","White gives up the bishop pair to damage Black's pawn structure."],["dxc6","Recapturing towards the centre opens lines for the queen and the bishop on c8."],["O-O","White castles first; 5.Nxe5 at once would run into ...Qd4, hitting the knight and e4."],["f6","Black protects e5 with the f-pawn, the most solid reply."],["d4","White opens the centre to trade queens and reach the endgame."],["exd4","Black takes."],["Nxd4","The knight recaptures in the centre."],["c5","The pawn drives the knight away and opens the d-file between the queens."],["Nb3","The knight retreats, keeping an eye on c5."],["Qxd1","Black trades queens."],["Rxd1","White has the structure it wanted: four pawns against three on the kingside, while Black's queenside majority is crippled."],["Bg4","Develops with tempo on the rook on d1."],["f3","White blocks and takes g4 and e4 under control."],["Be6","The bishop drops back, eyeing the knight on b3. Black's two bishops make up for the structure, and the endgame is roughly level."]],"vars":[{"name":"5...Bg4 with ...h5","summary":"Black pins the knight and dares White to take the bishop, which would open the h-file.","idea":["Instead of defending e5 with ...f6, Black pins the knight and answers h3 with ...h5, a famous trick: if White takes the bishop, the h-pawn recaptures and the h-file opens straight at White's king. White usually declines and plays d3, and Black gets active, aggressive play, often with queenside castling."],"at":9,"moves":[["Bg4","Black pins the knight against the queen, so it cannot take on e5."],["h3","White asks the bishop at once."],["h5","The point: if 7.hxg4 hxg4, the h-file opens for Black's rook and the knight on f3 is attacked, with a dangerous attack."],["d3","White declines the offer and protects e4."],["Qf6","The queen guards e5 and adds pressure on f3; Black can castle long and keep the kingside attack in reserve."]],"vars":[],"played":[86,86,70,30,30]}],"played":[373,369,285,46,45,35,33,27,15,14,14,3,3,2]}],"played":[94897,31689,29752,26231,14408,10144,9765,7831,6377,3811,2506,2484,2482,1201,1121,1091,1119,226,226,213,211,144,64,29]},{"id":"scotch","name":"Scotch Game","eco":"C44–C45","side":"w","group":"open","summary":"White opens the centre at once with 3.d4, trading the e5 pawn for free piece play.","idea":["With 3.d4 White challenges e5 immediately and, after 3...exd4 4.Nxd4, gets an open position with a pawn on e4 against no black centre pawn. There is little strategic complexity to learn: the game is about development, open lines and piece activity. Kasparov revived the Scotch in the 1990s as a way to avoid the huge theory of the Ruy Lopez.","In the main line, 4...Nf6 5.Nxc6 bxc6 6.e5, White doubles Black's c-pawns and drives the knight from f6. The pawn on e5 gives White space but is also a target: Black aims at it with ...Qe7, ...g6 and ...Bg7, or breaks with ...d6 or ...f6. White plays c4 to keep the knight out of d5, and develops with b3, Bb2 and g3. Black's doubled pawns are a weakness in the endgame, but they also control important central squares.","Black's other main try, 4...Bc5, attacks the knight and leads to active piece play, with Black often castling queenside."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre."],["Nf3","Develops with a threat to the e5 pawn."],["Nc6","Defends e5 and controls d4."],["d4","The Scotch: White opens the centre at once and challenges e5."],["exd4","Practically forced: Black cannot hold e5 comfortably, so takes."],["Nxd4","The knight recaptures in the centre. White has a pawn on e4 against no black centre pawn."],["Nf6","Black develops with an attack on e4."],["Nxc6","The Mieses Variation: White trades on c6 to double Black's pawns before pushing e5."],["bxc6","Black recaptures towards the centre and opens the b-file for the rook."],["e5","White gains space and drives the knight from f6."],["Qe7","The queen pins the e5 pawn against White's king, so exf6 is illegal, and attacks it at the same time."],["Qe2","White defends e5 and breaks the pin."],["Nd5","The knight takes the best central square."],["c4","White gains space and kicks the knight."],["Ba6","The bishop pins the c-pawn against the queen on e2, so the knight on d5 is not really attacked."],["b3","White gives the c4 pawn the support of another pawn, so the pin no longer ties the queen down."],["g6","Black prepares ...Bg7 to attack the e5 pawn, White's main asset and main target."]],"vars":[{"name":"Classical: 4...Bc5","summary":"Black develops the bishop with an attack on the d4 knight and aims for quick, active play.","idea":["With 4...Bc5 Black develops with tempo and eyes f2. After 5.Nxc6 Qf6 Black regains the piece with a threat and gets active pieces, open lines and often queenside castling. White aims for a stable position with the better pawn structure and tries to trade the active bishop on c5."],"at":7,"moves":[["Bc5","The bishop develops with an attack on the knight on d4."],["Nxc6","White removes the knight before Black adds pressure on d4. 5.Be3 and 5.Nb3 are also main lines."],["Qf6","Before recapturing, Black threatens ...Qxf2 mate."],["Qd2","The queen guards f2 along the second rank."],["dxc6","Black recaptures with the d-pawn, opening the d-file and the diagonal of the bishop on c8."],["Nc3","White develops and guards e4."],["Be6","Black develops and prepares to castle queenside."],["Na4","The knight goes after the bishop on c5 to win the bishop pair."],["Rd8","Black hits the queen on d2 down the open d-file."],["Bd3","White blocks the d-file and develops."],["Bd4","The bishop avoids the exchange and sits on a strong central square."],["O-O","White castles and will drive the bishop away with c3. Black has active pieces in return for the doubled pawns."]],"vars":[],"played":[354,54,42,4,4,3,1,1,0,0,0,0]},{"name":"Scotch Four Knights","summary":"White defends e4 with the knight; Black pins it and strikes with ...d5.","idea":["Instead of 5.Nxc6, White defends e4 with the knight. Black pins it with ...Bb4, and after the trade on c6 hits back in the centre with ...d5. The result is a symmetrical-looking, open position where White has a lead in development and pressure on the pinned knight on f6, and Black has a strong pawn on d5."],"at":8,"moves":[["Nc3","White defends e4 with the knight."],["Bb4","Pins the knight against the king, so e4 is no longer really defended and ...Nxe4 is threatened."],["Nxc6","White trades on c6 first, before defending e4 with the bishop."],["bxc6","Black recaptures towards the centre, ready for ...d5."],["Bd3","The bishop protects e4."],["d5","Black strikes in the centre at once."],["exd5","White takes and opens the position."],["cxd5","Black recaptures and has a strong pawn on d5."],["O-O","White castles."],["O-O","Black castles too."],["Bg5","The bishop pins the knight on f6 against the queen."],["c6","Black gives d5 a second pawn as support, ruling out tricks on that square. White often continues 11.Qf3, adding pressure on f6; the game is balanced."]],"vars":[],"played":[125,999,998,992,990,613,494,167,164,159,255,188]},{"name":"Scotch Gambit","summary":"White leaves the d4 pawn for the moment and develops quickly.","idea":["With 4.Bc4 White delays recapturing on d4 and develops the bishop. After 4...Nf6 5.e5 d5 the game becomes sharp and tactical: White pins the knight with Bb5 and wins the pawn back, while Black puts a knight on e4. If White plays 5.O-O instead, the game transposes to the Two Knights Defence with 4.d4."],"at":6,"moves":[["Bc4","The Scotch Gambit: White develops fast and leaves the d4 pawn for later."],["Nf6","Black develops and attacks e4."],["e5","White kicks the knight away from f6."],["d5","Black counterattacks the bishop on c4."],["Bb5","The bishop pins the knight on c6 against the king."],["Ne4","The knight takes up a strong central post."],["Nxd4","White wins back the gambit pawn."],["Bd7","Black breaks the pin and protects c6. The knight on e4 is strong and the game is balanced."]],"vars":[],"played":[248,177,292,205,204,123,121,72]},{"name":"Göring Gambit","summary":"White offers a pawn for fast development; Black can give it back at once with ...d5.","idea":["With 4.c3 White offers a pawn: after 4...dxc3 5.Nxc3 White has a big lead in development. The calm answer is 4...d5, returning the pawn at once and opening the centre. White ends up with an isolated d-pawn, and Black gets easy development and pressure on d4."],"at":6,"moves":[["c3","The Göring Gambit: White offers a pawn for development."],["d5","The safest answer: Black opens the centre at once instead of grabbing. 4...dxc3 5.Nxc3 gives White a lot of time."],["exd5","White takes."],["Qxd5","The queen recaptures centrally; Nc3 cannot hit it because the pawn is still on c3."],["cxd4","White regains the pawn, but is left with an isolated d-pawn."],["Bg4","Pins the knight against the queen, adding pressure on d4."],["Be2","White breaks the pin. Black continues with ...Bb4+ and ...Nf6 or ...O-O-O, with easy development and play against d4."]],"vars":[],"played":[31,10,9,9,9,12,11]}],"played":[94897,31689,29752,26231,1674,1673,1412,807,682,681,371,363,363,363,133,84,53,41]},{"id":"four-knights","name":"Four Knights Game","eco":"C46–C49","side":"w","group":"open","summary":"All four knights come out first: a solid, classical opening where White usually follows with 4.Bb5.","idea":["Both sides develop their knights before anything else, and the centre stays solid. Because White defends e4 with a piece, Black's ...Nf6 creates no real tactics, and both sides simply get on with development. It is one of the oldest and safest ways to open the game.","In the Spanish Four Knights, 4.Bb5, White puts pressure on c6, the knight that defends e5. In the symmetrical main line Black copies with ...Bb4 and trades on c3, so White gets the bishop pair and doubled c-pawns, but also a solid centre after d4. Black frees the position with the Metger unpin, ...Qe7 followed by ...Nd8–e6 to drive the bishop from g5, and then plays on the better pawn structure; White wants to open the centre for the two bishops.","Black's most ambitious reply to 4.Bb5 is Rubinstein's 4...Nd4, which leads either to a level endgame or to sharp gambit play. White can also choose 4.d4, the Scotch Four Knights, for a more open game."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre."],["Nf3","Develops with a threat to the e5 pawn."],["Nc6","Defends e5 and controls d4."],["Nc3","The Four Knights: White develops the other knight and defends e4 with a piece."],["Nf6","Black does the same, developing and hitting e4. All four knights are now out."],["Bb5","The Spanish Four Knights: the bishop puts pressure on the knight on c6, the defender of e5."],["Bb4","The Symmetrical Variation: Black copies and pins the knight on c3 against the king."],["O-O","White castles, which also breaks the pin on c3."],["O-O","Black castles too."],["d3","White protects e4 and opens the diagonal for the bishop on c1, which is heading for g5."],["d6","Black does the same."],["Bg5","The bishop pins the knight on f6 against the queen."],["Bxc3","Black gives up the bishop to double White's pawns, and removes the knight that could jump to d5 to exploit the pin."],["bxc3","White recaptures towards the centre; the c3 pawn will support d4, and the b-file is open for a rook."],["Qe7","The start of the Metger unpin: the queen clears d8 for the knight, which will come to e6 and drive the bishop from g5."],["Re1","The rook supports e4 and prepares d4."],["Nd8","The knight heads for e6."],["d4","White builds a centre, supported by the c3 pawn and the rook."],["Ne6","The knight hits the bishop on g5 and eyes d4 and f4. White usually keeps the bishop pair with 11.Bc1, and Black follows with ...c5; the game is roughly level."]],"vars":[{"name":"Rubinstein Variation","summary":"Black counterattacks the bishop and the f3 knight, ready to give up the e5 pawn.","idea":["Rubinstein's 4...Nd4 is Black's sharpest answer to the Spanish Four Knights. If White trades with 5.Nxd4, the game quickly reaches a level, nearly symmetrical endgame, a reliable drawing line for Black. If White keeps the bishop with 5.Ba4, Black gambits the e5 pawn for development and an attack on f2."],"at":7,"moves":[["Nd4","The knight attacks the bishop on b5 and the knight on f3, and Black is ready to give the e5 pawn."],["Nxd4","The simplest reply."],["exd4","Black recaptures, and the pawn now attacks the knight on c3."],["e5","White counterattacks the knight on f6."],["dxc3","Black takes the knight."],["exf6","White takes the other knight."],["Qxf6","The queen recaptures, and now ...cxd2+ is threatened."],["dxc3","White removes the pawn and opens the diagonal for the bishop on c1."],["Qe5+","The check forces the queens off."],["Qe2","White blocks and offers the trade."],["Qxe2+","Black trades queens."],["Bxe2","The endgame is very level: this line is a reliable way for Black to reach equality."]],"vars":[{"name":"5.Ba4: the sharp line","summary":"White keeps the bishop and takes the e5 pawn; Black gets a dangerous initiative.","idea":["After 5.Ba4 Bc5 6.Nxe5 O-O Black is a pawn down but has a strong knight on d4, a bishop aimed at f2 and quick development. White must give back time to deal with the threats, and the game is very sharp and full of tactics."],"at":8,"moves":[["Ba4","White keeps the bishop and invites complications."],["Bc5","Black develops and leaves the e5 pawn to be taken."],["Nxe5","White accepts the pawn."],["O-O","Black castles and ignores the pawn: the knight on d4 and the lead in development are the compensation."],["Nd3","The knight retreats with tempo on the bishop on c5."],["Bb6","The bishop stays on the a7–g1 diagonal, aimed at f2."],["e5","White kicks the knight from f6 and gains space."],["Ne8","The knight drops back; it will support ...d6 to break up the e5 pawn."],["Nd5","The knight jumps to the centre, eyeing the bishop on b6 and the c7 pawn."],["d6","Black strikes at e5 at once. After 10.Ne3 the game is very sharp: White is a pawn up, Black has active pieces and play against White's king."]],"vars":[],"played":[8,3,1,0,0,0,0,0,0,0]}],"played":[320,94,94,89,88,84,84,81,25,21,20,7]},{"name":"Scotch Four Knights","summary":"White opens the centre with 4.d4 instead of developing the bishop.","idea":["With 4.d4 White opens the centre, reaching the same position as the Scotch with 4...Nf6 5.Nc3. Black pins the knight with ...Bb4 and strikes back with ...d5, and the result is an open, nearly symmetrical position where White has the lead in development and pressure on f6, and Black has a strong pawn on d5."],"at":6,"moves":[["d4","White opens the centre at once."],["exd4","Black takes."],["Nxd4","The knight recaptures in the centre."],["Bb4","Pins the knight against the king, so e4 is no longer really defended and ...Nxe4 is threatened."],["Nxc6","White trades on c6 first, before defending e4 with the bishop."],["bxc6","Black recaptures towards the centre, ready for ...d5."],["Bd3","The bishop protects e4."],["d5","Black strikes in the centre at once."],["exd5","White takes and opens the position."],["cxd5","Black recaptures and has a strong pawn on d5."],["O-O","White castles."],["O-O","Black castles too."],["Bg5","The bishop pins the knight on f6 against the queen."],["c6","Black gives d5 a second pawn as support. The position is balanced."]],"vars":[],"played":[1058,985,964,999,998,992,990,613,494,167,164,159,255,188]},{"name":"Italian Four Knights and the fork trick","summary":"The bishop goes to c4, but Black can use the fork trick to free the game.","idea":["With 4.Bc4 White aims at f7, but the bishop on c4 is loose, and Black can exploit it with the fork trick: Black gives the knight on e4, then wins it back with ...d5, forking bishop and knight. Black gets a free, comfortable position, which is why 4.Bc4 is rarely seen at a high level."],"at":6,"moves":[["Bc4","The Italian Four Knights: the bishop aims at f7."],["Nxe4","The fork trick: Black gives the knight back at once to break up White's centre."],["Nxe4","White takes the knight."],["d5","The fork: the pawn hits both the bishop on c4 and the knight on e4, so Black wins the piece back."],["Bd3","The bishop retreats and protects the knight."],["dxe4","Black takes the knight."],["Bxe4","White recaptures, and material is level."],["Bd6","Black develops and defends e5, with free play and no problems."]],"vars":[],"played":[25,21,18,17,17,14,14,14]}],"played":[94897,31689,29752,26231,2149,2089,769,217,197,189,116,47,19,13,13,29,26,17,17,15]},{"id":"petrov","name":"Petrov Defence","eco":"C42–C43","side":"b","group":"open","summary":"Black answers 2.Nf3 by counterattacking e4 with 2...Nf6: one of the most solid defences in chess.","idea":["Petrov's Defence, also called the Russian Game, answers 2.Nf3 not by defending e5 but by attacking e4. After 3.Nxe5 d6 4.Nf3 Nxe4 material is level and the position is open and symmetrical. It is one of the most solid defences in chess and a favourite of top players who want a safe, sound game with Black.","In the Classical main line Black's knight on e4 is supported by ...d5, and White tries to undermine it with Bd3, c4 and Nc3, while Black develops quickly and keeps the pieces active. The pawn structure is usually symmetrical or close to it, so lasting weaknesses are rare: White aims for a small edge from the extra tempo and a little more space, Black for full equality and a position with no risk.","Modern White players often choose 5.Nc3 instead, accepting doubled pawns to castle queenside and attack with the kingside pawns, which brings real imbalance into the position."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre."],["Nf3","Develops with a threat to the e5 pawn."],["Nf6","The Petrov: instead of defending e5, Black counterattacks e4."],["Nxe5","White takes first."],["d6","Black kicks the knight before taking on e4. The immediate 3...Nxe4? runs into 4.Qe2, when 4...Nf6?? 5.Nc6+ wins the queen by discovered check."],["Nf3","The knight retreats to its natural square."],["Nxe4","Black wins the pawn back, and material is level."],["d4","White takes the centre and prepares Bd3 to challenge the knight on e4."],["d5","Black supports the knight with a pawn and claims a share of the centre."],["Bd3","The bishop develops with an attack on the knight."],["Nc6","Black develops and puts pressure on d4. 6...Bd6 is the main alternative."],["O-O","White castles."],["Be7","A solid square: the bishop prepares castling and guards the kingside."],["c4","White attacks d5, the pawn that holds the knight on e4."],["Nb4","The knight hits the bishop on d3, White's best attacking piece."],["Be2","White keeps the bishop, which still guards c4."],["O-O","Black castles."],["Nc3","White attacks the knight on e4 a second time."],["Bf5","The bishop gives the knight on e4 a second defender."],["a3","White drives the knight away from b4."],["Nxc3","Black trades knights first."],["bxc3","White recaptures, and the knight on b4 is now hit by two pawns."],["Nc6","The knight retreats to c6 and presses on d4. After 13.Re1 Re8 14.Bf4 the position is balanced: White has a little more space, Black a very solid structure."]],"vars":[{"name":"The 3...Nxe4? trap","summary":"Taking back on e4 at once is a classic mistake that costs Black a pawn, or the queen.","idea":["Black must not copy White with 3...Nxe4, because of 4.Qe2: the queen attacks the knight and lines up on the e-file against Black's king. Black can save the queen but not the pawn. This is why every Petrov begins with 3...d6."],"at":5,"moves":[["Nxe4","A famous mistake: Black takes back at once, without first kicking the knight."],["Qe2","The queen attacks the knight on e4 and lines up on the e-file against Black's king."],["Qe7","The only way to keep material level for now. 4...Nf6?? would lose the queen to 5.Nc6+, a discovered check that also attacks d8."],["Qxe4","White takes the knight."],["d6","Black attacks the knight on e5, which is pinned against White's queen on e4."],["d4","White defends the knight."],["dxe5","Black takes it."],["dxe5","White recaptures and is a clean pawn up."]],"vars":[],"played":[74,70,70,70,70,68,68,65]},{"name":"5.Nc3: the modern main line","summary":"White trades knights, accepts doubled pawns and castles queenside for an attack.","idea":["With 5.Nc3 White gives up the pawn structure for fast development: after the trade on c3 White plays Be3, Qd2 and O-O-O, and then pushes the kingside pawns if Black castles short. Black has an easy, solid position and must choose which side to put the king on. The doubled c-pawns hardly matter while the pieces are on."],"at":8,"moves":[["Nc3","White offers to trade knights, accepting doubled pawns for quick development and queenside castling."],["Nxc3","Black trades."],["dxc3","Recapturing with the d-pawn opens the d-file and the diagonal for the bishop on c1."],["Be7","A solid square; Black prepares to castle."],["Be3","Develops and prepares Qd2 and O-O-O."],["Nc6","Black develops."],["Qd2","The queen connects with the plan of castling long."],["Be6","Black develops the last minor piece."],["O-O-O","White castles queenside and is ready to push the kingside pawns if Black castles short."],["Qd7","Black connects the rooks and can castle either side: with ...O-O-O the game is calmer, with ...O-O a race of pawn storms begins."]],"vars":[],"played":[453,360,359,346,259,59,54,38,39,37]},{"name":"Steinitz Attack: 3.d4","summary":"White opens the centre instead of taking on e5.","idea":["With 3.d4 White strikes in the centre at once. Black takes on e4, supports the knight with ...d5, and challenges White's knight on e5 with ...Nd7. The result is a nearly symmetrical, open position in which Black has a solid centre and easy development."],"at":4,"moves":[["d4","White opens the centre instead of taking on e5."],["Nxe4","Black takes the e4 pawn."],["Bd3","White develops with an attack on the knight."],["d5","Black supports the knight with a pawn."],["Nxe5","White wins the pawn back and has a strong knight in the centre."],["Nd7","Black challenges the knight on e5 at once."],["Nxd7","White trades the knights."],["Bxd7","The bishop recaptures and is developed."],["O-O","White castles."],["Bd6","Black develops, aiming at h2, and prepares to castle."],["c4","White attacks d5, the pawn that supports the knight on e4."],["c6","Black supports d5 with another pawn. The structure is nearly symmetrical and Black has a solid, active position."]],"vars":[],"played":[775,746,590,487,463,405,116,116,95,78,11,5]}],"played":[94897,31689,29752,3201,2005,1925,1762,1761,815,796,794,137,134,129,31,31,31,24,20,18,15,15,15,15]},{"id":"philidor","name":"Philidor Defence","eco":"C41","side":"b","group":"open","summary":"Black defends e5 with 2...d6: a solid, compact set-up that keeps the strong point in the centre.","idea":["Philidor's Defence protects e5 with the d-pawn instead of the knight. Black gets a solid, compact position, but a cramped one: the bishop on f8 can only develop to e7, and White gets more space with d4. The modern way to play it is the Hanham (or \"Lion\") set-up: knights on f6 and d7, bishop on e7, pawn on c6, holding the strong point on e5 rather than giving it up.","White has more space and freer development and aims for a lasting edge: pressure on f7 with Bc4, a later d5 to gain space or dxe5 to open the d-file, and queenside play with a4. Black waits solidly, prepares ...b5 or ...exd4 followed by ...Re8 and ...Bf8 to press on e4, and looks for a well-timed ...d5. The middlegames are slow and strategic.","The move order matters. After 3...Nf6, 4.dxe5 is awkward for Black, so many players reach the Hanham via 1.e4 d6 2.d4 Nf6 3.Nc3 e5 4.Nf3 Nbd7, where 4.dxe5 dxe5 5.Qxd8+ Kxd8 is harmless. Giving up the centre with 3...exd4 is the simpler, older approach."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre."],["Nf3","Develops with a threat to the e5 pawn."],["d6","The Philidor: Black defends e5 with a pawn. It is solid, but it shuts in the bishop on f8, which will have to go to e7."],["d4","White challenges e5 at once and claims more space."],["Nf6","Black keeps the tension rather than taking, and hits e4, aiming for the Hanham set-up."],["Nc3","White protects e4."],["Nbd7","The Hanham: the knight supports e5 from d7, so Black keeps the strong point in the centre."],["Bc4","The bishop takes aim at f7."],["Be7","The bishop goes to its natural square, guarding g5 so that Ng5 ideas against f7 are ruled out, and Black is ready to castle."],["O-O","White castles."],["O-O","Black castles too."],["Re1","The rook supports e4 and stands ready on the e-file for when the centre opens."],["c6","Black frees c7 for the queen, takes d5 and b5 from White's pieces, and prepares ...b5 to chase the bishop."],["a4","White stops ...b5 and gains queenside space."],["a5","Black stops a4–a5 and secures b4 and c5 for the pieces. Typical plans are ...Qc7 and ...Re8, or ...exd4 followed by ...Nc5."]],"vars":[{"name":"Exchange: 3...exd4","summary":"Black gives up the centre at once to free the pieces.","idea":["The older way to play the Philidor: Black exchanges on d4 and develops freely, but White has a strong knight on d4 and more space. White can castle either side; with Bf4 or Be3, Qd2 and O-O-O the game looks like an Open Sicilian. Black aims for counterplay against e4 with ...Re8 and ...Bf8, or a freeing ...d5."],"at":5,"moves":[["exd4","The older approach: Black gives up the centre to free the pieces."],["Nxd4","White recaptures with a strong central knight and has more space."],["Nf6","Black develops and hits e4."],["Nc3","White protects e4."],["Be7","The bishop develops and Black prepares to castle."],["Bf4","The bishop takes an active square, eyeing the d6 pawn."],["O-O","Black castles."],["Qd2","White prepares to castle queenside and attack on the kingside. Black looks for ...Re8, ...Bf8 and ...d5 to free the game."]],"vars":[{"name":"Larsen Variation","summary":"Black fianchettoes the king's bishop, where it is far more active than on e7.","idea":["Bent Larsen's idea: after giving up the centre, Black puts the bishop on g7, where it presses on the knight on d4 and the long diagonal. The position resembles a Dragon Sicilian, and White often answers in the same way, with Be3, Qd2, O-O-O and a kingside pawn storm."],"at":7,"moves":[["g6","The Larsen: Black fianchettoes the bishop, which is much more active on g7 than on e7."],["Nc3","White develops and protects e4."],["Bg7","The bishop hits the knight on d4 along the long diagonal."],["Be3","The bishop protects the knight."],["Nf6","Black develops and hits e4."],["Qd2","White prepares long castling and Bh6 to trade off Black's best bishop."],["O-O","Black castles."],["O-O-O","White castles long; as in a Dragon, White plans f3, g4 and h4 against Black's king, while Black looks for play on the queenside and the long diagonal."]],"vars":[],"played":[5,4,4,3,2,4,0,0]}],"played":[204,180,172,169,210,69,64,62]},{"name":"4.dxe5: the problem with 3...Nf6","summary":"White opens the centre at once, and Black has to accept a slightly worse position.","idea":["This line shows why the move order matters. After 4.dxe5 Nxe4 5.Qd5 White hits the knight and f7, then gains time with Bg5 and the exchange on d6. Black is not lost, but White keeps a lasting lead in development, which is why many Philidor players start with 1...d6 instead."],"at":6,"moves":[["dxe5","The critical test of this move order: White opens the centre while Black's knight is on f6."],["Nxe4","Black takes back on e4. 4...dxe5? 5.Qxd8+ Kxd8 6.Nxe5 leaves Black a pawn down, since 6...Nxe4 runs into 7.Nxf7+."],["Qd5","A double attack on the knight on e4 and the f7 pawn."],["Nc5","The knight escapes. The f7 pawn is safe, because Qxf7+ would simply lose the queen to the king."],["Bg5","The bishop attacks the queen on d8."],["Be7","Black blocks with the bishop."],["exd6","White opens the position further."],["Qxd6","The queen recaptures; 7...Bxd6 would leave the queen on d8 to the bishop on g5. After 8.Nc3 White keeps a lasting lead in development."]],"vars":[],"played":[10,10,9,9,9,2,2,1]},{"name":"3.Bc4: the quiet approach","summary":"White develops the bishop towards f7 before playing d4.","idea":["White develops calmly and aims at f7. Black must be careful: the natural-looking ...Bg4 can walk into Légal's Mate. With ...Be7 Black covers g5 and gets ready to castle, and after d4 Black usually exchanges and develops freely, with a position like the 3...exd4 line."],"at":4,"moves":[["Bc4","White develops the bishop towards f7 before deciding on d4."],["Be7","The bishop covers g5, so Ng5 ideas against f7 are ruled out. Beware 3...Bg4?, when 4.Nc3 g6? 5.Nxe5! Bxd1 6.Bxf7+ Ke7 7.Nd5 is the famous Légal's Mate."],["d4","White challenges e5 and claims the centre."],["exd4","Black gives up the centre and develops freely."],["Nxd4","The knight recaptures in the centre."],["Nf6","Black develops and hits e4."],["Nc3","White protects e4."],["O-O","Black castles."],["O-O","White has more space and freer play; Black develops with ...Nc6 or ...Nbd7 and ...Re8, pressing on e4."]],"vars":[],"played":[20,17,3,3,4,4,4,21,21]}],"played":[94897,31689,29752,275,243,22,11,853,595,585,468,410,200,168,168,54]},{"id":"kings-gambit","name":"King's Gambit","eco":"C30–C39","side":"w","group":"open","summary":"White gives the f-pawn on move two to open the f-file and build a big centre: the most romantic opening of all.","idea":["With 2.f4 White offers a pawn to deflect Black's e-pawn from the centre. If Black takes, White hopes to play d4, dominate the centre with pawns and use the half-open f-file against f7, the square next to Black's king. The price is a loosened king: the e1–h4 diagonal is opened and ...Qh4+ is a recurring danger, which is why White's knight comes to f3 so quickly.","Black has two broad approaches after 2...exf4 3.Nf3. The classical one is to hang on to the extra pawn with ...g5, accepting a loosened kingside in return for keeping the f-file closed; White strikes at the pawn chain with h4, as in the Kieseritzky main line. The modern one is to strike in the centre with 3...d5, returning the pawn for free development, or to prepare ...g5 with 3...d6 so that the knight never gets to e5.","The middlegames are sharp and tactical. White's themes are the f-file, a knight on e5, the bishop on c4 or f4 and a lead in development. Black's are the extra pawn, the open e-file towards White's uncastled king and the dark squares around it. Declining with 2...Bc5 or countering with 2...d5 are respectable ways to avoid the main theory."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre. This pawn is what White's next move is aimed at."],["f4","The King's Gambit. White offers the f-pawn to lure the e-pawn away, so that d4 can follow and the f-file opens against f7."],["exf4","Black accepts. The pawn on f4 controls e3 and g3, and White will have to spend time winning it back."],["Nf3","The key developing move: it stops ...Qh4+, which would drive White's king to f1, and it prepares d4."],["g5","The classical way to keep the pawn: g5 protects f4 and threatens ...g4 to drive the knight away."],["h4","White undermines the chain at once. hxg5 is threatened, and ...h6 would lose the rook on h8 after hxg5 hxg5 Rxh8, so Black must push on."],["g4","Forced, but with gain of time: the knight on f3 is attacked and must find a new square."],["Ne5","The Kieseritzky Gambit. The knight jumps to a strong central square, where it attacks the g4 pawn and eyes f7."],["Nf6","The Berlin Defence to the Kieseritzky: rather than defend g4, Black counterattacks the e4 pawn and brings out the kingside pieces."],["d4","White supports the knight on e5 and opens the c1 bishop's diagonal towards f4, so the pawn there can be won back."],["d6","Black drives the knight from its outpost before it settles there."],["Nd3","The knight retreats to a square where it attacks f4, so Bxf4 will win the pawn back next move."],["Nxe4","Black grabs the centre pawn instead of guarding f4. The knight on e4 is very active, and Black will stay a pawn up."],["Bxf4","White wins back one pawn and develops the bishop to an active square. White's compensation is the open f-file and quick development."],["Qe7","A sharp move: the queen lines up on the e-file behind the knight, threatening a discovered check such as ...Nc3+, which would win White's queen."],["Qe2","White blocks the e-file in advance, so the discovered check is no longer a danger."],["Bg7","The bishop develops onto the long diagonal and hits the d4 pawn, which has no defender, so White must spend a move on c3. Black keeps the extra pawn; White hopes for activity against Black's loosened kingside."]],"vars":[{"name":"Modern Defence","summary":"Black returns the pawn at once and frees the game with a counter-strike in the centre.","idea":["Instead of clinging to the f4 pawn with ...g5, Black strikes in the centre with ...d5 and develops quickly. Material soon comes back to level, but Black's pieces get out fast and the pawn on f4 still cramps White. It is one of the most reliable replies to the King's Gambit, and it avoids the kingside weaknesses that ...g5 creates."],"at":5,"moves":[["d5","Black opens the centre at once, so that Black's pieces, not White's, are the first to come out."],["exd5","White takes, otherwise ...dxe4 removes White's centre pawn."],["Nf6","Black develops and attacks d5, planning to recapture there with the knight. The f4 pawn is still Black's."],["Bb5+","White develops with check, so that Black's natural ...Nxd5 has to wait."],["c6","Black blocks with a pawn, offering it to open lines for the pieces."],["dxc6","White takes a second pawn, but Black wins it back at once."],["bxc6","Black recaptures towards the centre. Material is level, and Black has the half-open b-file and easy development."],["Bc4","The bishop leaves b5, where it was attacked, for its best diagonal, aimed at f7."],["Nd5","The knight centralises and, crucially, protects the f4 pawn; it also blocks the bishop on c4."],["O-O","White castles, putting the rook on the f-file opposite the f4 pawn."],["Bd6","A second guard for f4. Black will castle next with a comfortable game."]],"vars":[],"played":[12,14,47,28,21,21,3,3,0,0,0]},{"name":"Fischer Defence","summary":"Bobby Fischer's answer: a modest pawn move that keeps the knight out of e5 before Black plays ...g5.","idea":["Fischer's idea is a move-order finesse. In the classical lines White gets Ne5 in after ...g5, h4 and ...g4; with ...d6 played first, e5 is covered, so after the same moves the knight has no good square. Black keeps the extra pawn and a solid structure, while White relies on the centre and quick development to make the pawn chain a target."],"at":5,"moves":[["d6","Covers e5, so the knight will have no central outpost when Black later plays ...g5 and ...g4."],["d4","White takes the centre with two pawns and opens the c1 bishop's diagonal towards f4."],["g5","Now Black protects f4: this is the plan the quiet ...d6 was preparing."],["h4","The standard attack on the chain: hxg5 is threatened, and ...h6 would run into hxg5 hxg5 Rxh8."],["g4","Black gains time on the knight, which cannot go to e5 because the d6 pawn covers it."],["Ng1","The modern main line. The knight goes home to return via e2, and meanwhile the g-pawn no longer guards f4, so Bxf4 is threatened."],["Bh6","Black protects f4 again with the bishop, which also eyes White's dark squares."],["Nc3","White develops and protects e4. The plan is Nge2 and then g3 to break up the f4 pawn."]],"vars":[],"played":[8,5,5,0,0,0,0,0]},{"name":"Classical Declined: 2...Bc5","summary":"Black declines with a developing move that stops White castling and sets a trap.","idea":["Black ignores the pawn and puts the bishop on the a7–g1 diagonal, where it stops White castling kingside. White cannot take on e5 straight away, because 3.fxe5? Qh4+ 4.g3 Qxe4+ forks king and rook, so White must develop first. Play is calmer than in the accepted lines: White often plays Na4 to trade off the strong bishop, or f5 to gain kingside space, while Black aims for ...Bg4 and ...Nd4."],"at":3,"moves":[["Bc5","The bishop takes the a7–g1 diagonal, stopping White from castling, and sets a trap: 3.fxe5? Qh4+ wins material."],["Nf3","White develops and covers h4, so now fxe5 is a real threat."],["d6","Black supports e5. If White takes, ...dxe5 opens lines for Black's pieces."],["Nc3","Natural development, protecting e4 and eyeing a4, from where the knight can trade off the bishop on c5."],["Nf6","Black develops and puts pressure on e4."],["Bc4","White's bishop takes its most active diagonal, aimed at f7, mirroring Black's bishop on c5."],["Nc6","Black completes the minor-piece development; the knight eyes d4."],["d3","White protects e4 and opens the c1 bishop. Typical plans are Na4 to win the bishop pair, or f5 and a kingside pawn storm."]],"vars":[],"played":[5,5,5,0,5,5,1,1]},{"name":"Falkbeer Countergambit","summary":"Black meets the gambit with a counter-gambit, striking in the centre before White's king is safe.","idea":["With 2...d5 Black answers a flank attack with a central counter, the classical recipe. After 3.exd5 Black can play 3...exf4, which leads to lines like the Modern Defence, or 3...e4, the Falkbeer proper, which gives up a pawn to cramp White's development. In the Falkbeer the fight is about Black's advanced e-pawn, and later the knight on e4, against White's extra d5 pawn and loose king."],"at":3,"moves":[["d5","The counter-gambit: Black ignores f4 and hits e4, opening the centre while White's king is still loose."],["exd5","White takes the pawn. Now Black chooses how to continue the counter-attack."],["e4","The Falkbeer proper: the pawn on e4 cramps White by taking d3 and f3 away from the pieces, in return for the pawn."],["d3","White hits the intruder at once, before Black can support it."],["Nf6","Black develops and defends e4, ready to recapture there with the knight."],["dxe4","White removes the e4 pawn and opens the d-file. For the moment White is two pawns up."],["Nxe4","The knight recaptures onto a superb central square, and White's kingside is airy."],["Nf3","White develops and covers h4 and e5, keeping Black's queen out."],["Bc5","The bishop takes aim at f2 and g1, stopping White from castling short."],["Qe2","A pin: the queen attacks the knight on e4, which cannot move without exposing Black's king on e8."],["Bf5","Black protects the pinned knight while developing. Castling will break the pin, and Black's active pieces are the compensation for the pawn."]],"vars":[],"played":[47,44,5,4,3,3,3,3,2,2,0]}],"played":[94897,31689,195,125,86,18,12,9,9,6,2,2,2,2,2,0,0,0]},{"id":"vienna","name":"Vienna Game","eco":"C25–C29","side":"w","group":"open","summary":"White develops the queen's knight first, keeping the f-pawn free for an early f4.","idea":["The Vienna is like a King's Gambit with the knight already developed. 2.Nc3 protects e4 and controls d5 and, unlike 2.Nf3, leaves the f-pawn free to advance. The main idea is the Vienna Gambit, 3.f4, attacking e5 to open the f-file and gain kingside space.","Black's best answer is the central counter 3...d5. After 4.fxe5 Nxe4 the black knight sits proudly on e4, while White has a space-gaining pawn on e5 and the half-open f-file. White aims to castle, play Bd3 and challenge the e4 knight, then attack on the kingside along the f-file. Black aims to keep the knight on e4 and challenge White's e5 pawn with ...f6 or ...f5 at the right moment.","White also has quieter or trickier set-ups: 3.Bc4 invites the wild Frankenstein-Dracula Variation, while 3.g3 is a positional system in which the bishop on g2 works along the long diagonal."],"moves":[["e4","Stakes a claim to the centre and opens lines for the queen and the king's bishop."],["e5","Black takes an equal share of the centre."],["Nc3","The Vienna: the knight protects e4 and controls d5, and leaves the f-pawn free for f4."],["Nf6","The most active reply: Black develops and prepares ...d5 to fight for the centre."],["f4","The Vienna Gambit. White attacks e5 to open the f-file and gain space; compared with the King's Gambit, the knight is already on c3."],["d5","The principled answer: Black strikes back in the centre instead of taking on f4."],["fxe5","White captures, and the pawn now on e5 attacks the knight on f6."],["Nxe4","The knight steps forward with a capture, landing on a superb central square protected by the d5 pawn."],["Nf3","White develops, protects e5 and takes h4 away from Black's queen, so ...Qh4+ is no longer possible."],["Be7","Black prepares to castle. On e7 the bishop is solid and covers g5, a square White's knight might use."],["d4","White builds a broad centre with pawns on d4 and e5 and opens the diagonal of the c1 bishop."],["O-O","Black castles into safety before the f-file opens."],["Bd3","The bishop hits the knight on e4, with Black's h7 pawn behind it on the same diagonal."],["f5","Black reinforces the knight with the f-pawn. If White takes en passant with exf6, the f-file opens for both sides and the game becomes very sharp."]],"vars":[{"name":"Frankenstein-Dracula Variation","summary":"A wild line in which White wins a rook while Black hunts for compensation against White's king.","idea":["With 3.Bc4 White develops towards f7 and invites 3...Nxe4. After 4.Qh5 Black must defend f7, and the brave 5...Nc6 leads to a famous line in which White's knight takes on c7 and a8, while Black traps it there and uses the time to attack. Players who do not want this can choose the calmer 5...Be7, or avoid it altogether with 3...Bc5 or 3...Nc6."],"at":4,"moves":[["Bc4","White develops towards f7 and allows ...Nxe4, hoping to punish Black's greed."],["Nxe4","Black takes, relying on a fork trick: if 4.Nxe4, then 4...d5 wins the piece back."],["Qh5","The point: the queen threatens mate on f7 and also attacks e5."],["Nd6","The knight retreats to cover f7 and attacks the bishop on c4 at the same time."],["Bb3","The bishop keeps its eye on f7 from a safer square."],["Nc6","The ambitious move: Black defends e5 with a developing move and invites the complications."],["Nb5","White hits the knight on d6, the defender of f7: Nxd6+ followed by Qxf7 mate is the threat."],["g6","Black gains time on the queen before dealing with the threat."],["Qf3","The queen keeps its eye on f7, now down the f-file, so Nxd6+ and Qxf7 mate is threatened again."],["f5","Black blocks the f-file with the f-pawn."],["Qd5","The queen switches to the a2–g8 diagonal, renewing the pressure on f7 and supporting Nxc7+."],["Qe7","Black covers f7 and frees d8 for the king."],["Nxc7+","White forks the king and the rook on a8."],["Kd8","The king steps aside. After 10.Nxa8 b6 the knight on a8 is trapped, and Black plans ...Bb7 with dangerous play against White's queen and uncastled king; the theory runs very deep."]],"vars":[],"played":[197,77,75,75,49,10,10,10,10,6,6,3,3,3]},{"name":"Mieses Variation: 3.g3","summary":"A positional choice: White fianchettoes the king's bishop and invites ...d5.","idea":["White puts the bishop on g2, where it presses down the long diagonal. If Black plays the natural ...d5, White exchanges on d5 and the bishop bears down on the centre and the queenside. The resulting positions are quiet and strategic: White hopes for slow pressure, with the half-open b-file after bxc3, while Black gets easy development and a fine share of the centre."],"at":4,"moves":[["g3","White prepares Bg2, aiming the bishop down the long diagonal at d5 and b7."],["d5","Black takes the centre at once."],["exd5","White exchanges, opening the long diagonal for the coming bishop."],["Nxd5","Black recaptures with the knight, which is well centralised."],["Bg2","The bishop joins the knight on c3 in attacking d5."],["Nxc3","Black exchanges the attacked knight."],["bxc3","White recaptures towards the centre and opens the b-file for a rook."],["Bd6","Black protects e5 in advance and prepares to castle."],["Nf3","White develops and attacks e5."],["O-O","Black castles. The game is balanced: White has the bishop on g2 and the b-file, Black has good development and the centre."],["O-O","White castles too. Typical plans are Rb1, d3 or d4, and pressure on b7."]],"vars":[],"played":[112,46,46,40,40,31,31,5,2,2,2]},{"name":"Vienna Gambit Accepted","summary":"Black takes the pawn, but White gains space with e5 and the f6 knight must retreat.","idea":["Taking the pawn allows White to push e5 and drive the f6 knight away, so Black falls behind in development and must fight to keep the f4 pawn. Black's main resource is a quick ...d6 to break up the e5 pawn. The positions resemble King's Gambit lines, with White playing for a big centre and quick development."],"at":5,"moves":[["exf4","Black accepts the gambit, but this lets White gain space with tempo."],["e5","The pawn attacks the knight and takes d6 and f6 away from Black's pieces."],["Ng8","The safest retreat, though Black is now behind in development."],["Nf3","White develops, defends e5 and stops ...Qh4+."],["d6","Black strikes at e5 at once, before White can support it with d4."],["d4","White supports e5 and frees the c1 bishop, which eyes the f4 pawn. White has a big lead in development."]],"vars":[],"played":[1,0,0,0,0,0]}],"played":[94897,31689,747,547,76,75,76,76,17,6,4,1,1,1]},{"id":"sicilian","name":"Sicilian Defence","eco":"B20–B99","side":"b","group":"semi-open","summary":"Black answers 1.e4 with 1...c5: an unbalanced fight where Black trades a wing pawn for White's d-pawn.","idea":["Black meets 1.e4 with a flank pawn. The c-pawn controls d4 just as ...e5 would, but it keeps the position asymmetrical from the first move. When White opens the centre with d4, Black takes with the c-pawn and is left with two central pawns (d- and e-) against one, plus a half-open c-file. White gets a lead in development, more space and the half-open d-file. That imbalance is the whole point: neither side can simply copy the other, and Black plays for a win, not for equality.","In the Open Sicilian the typical Black set-up is a \"small centre\" of pawns on d6 and e6 (or a bolder ...e5), with the pieces aimed at the queenside. Black's play comes on the c-file and with the pawn storm ...a6, ...b5, ...b4 to drive away the knight on c3 that guards e4. The exchange sacrifice ...Rxc3 and the freeing break ...d5 are standard weapons. White often castles queenside and throws the kingside pawns forward (f4, g4, f5), or breaks with e5 against the d6 pawn; piece sacrifices on d5, e6 and b5 are common, because Black's king often stays in the centre.","Black chooses the flavour with the second and fifth moves: the Najdorf (5...a6), the Dragon (5...g6), the Classical (5...Nc6, shown here against the Richter–Rauzer Attack) or the Sveshnikov (2...Nc6 and ...e5). Many White players avoid the theory altogether with \"anti-Sicilians\" such as the Alapin 2.c3, the Closed Sicilian 2.Nc3 or the Smith–Morra Gambit, so a Sicilian player needs an answer to those too."],"moves":[["e4","White takes the centre and opens lines for the queen and the king's bishop."],["c5","The Sicilian: Black fights for d4 from the side, keeping the position unbalanced instead of mirroring with 1...e5."],["Nf3","Develops and prepares d4, so that White can recapture on d4 with a piece."],["d6","Covers e5, so a later knight on f6 cannot be kicked by e5, and opens the diagonal for the bishop on c8."],["d4","The Open Sicilian: White opens the centre at once to use the lead in development."],["cxd4","The key trade: Black gives a wing pawn for a central one and gets the half-open c-file."],["Nxd4","White recaptures with a fine central knight. White has more space; Black has the extra central pawn."],["Nf6","Develops with an attack on e4, which forces White to defend it before doing anything else."],["Nc3","Guards e4. White gives up the c2–c4 clamp (the Maroczy Bind) for quick development."],["Nc6","The Classical Variation: the knight develops naturally and challenges the strong knight on d4."],["Bg5","The Richter–Rauzer Attack. The bishop eyes the knight on f6, rules out the Dragon set-up (...g6 would allow Bxf6, wrecking Black's pawns) and prepares Qd2 and long castling."],["e6","Black blunts the idea of Bxf6 by preparing ...Be7, and the pawn controls d5 so that White's knights cannot settle there."],["Qd2","Connects the queen with the rooks for queenside castling and supports the bishop on g5."],["a6","Takes b5 away from White's knights (Ndb5 hitting d6 was a real idea) and prepares the pawn storm ...b5."],["O-O-O","White castles long: the rook lands on d1 behind the queen, aiming at the d6 pawn, and the kingside pawns are free to advance."],["Bd7","Develops modestly so that after Nxc6 Black can recapture with the bishop and keep the pawns intact; it also supports ...b5."],["f4","Protects the bishop on g5 and prepares e5, which would hit both the knight on f6 and the d6 pawn."],["Be7","Black finishes kingside development; now Bxf6 can be met by a piece and the king can choose later where to go."],["Nf3","The knight steps back to avoid exchanges, which would ease Black's game, and supports e5. The queen and rook on the d-file now bear down on d6."],["b5","The counterattack: Black threatens ...b4, driving away the knight on c3, after which the e4 pawn falls to the knight on f6."],["Bxf6","White removes the knight that would take on e4 after ...b4, and damages Black's kingside pawns at the same time."],["gxf6","Black recaptures with the pawn: the pawn on f6 controls e5 and stops White's e5 break, and Black gets the bishop pair. Black's king will often stay in the centre or go long, and the game is a sharp race."]],"vars":[{"ref":"sicilian-najdorf","at":9,"name":"Sicilian Najdorf","summary":"5...a6: the most popular and most deeply analysed Sicilian."},{"ref":"sicilian-dragon","at":9,"name":"Sicilian Dragon","summary":"5...g6: Black fianchettoes the bishop on the long diagonal, aimed at White's queenside."},{"ref":"sicilian-sveshnikov","at":3,"name":"Sicilian Sveshnikov","summary":"2...Nc6 and ...e5: Black accepts a hole on d5 for activity and the bishop pair."},{"name":"Alapin Variation","summary":"White prepares d4 with c3, so that a pawn can recapture and White keeps a full centre.","idea":["White avoids the Open Sicilian by preparing d4 with the c-pawn, aiming to answer ...cxd4 with cxd4 and keep two pawns in the centre. The drawback is that c3 takes the natural square from the queen's knight, so Black can hit the centre at once: either with 2...Nf6, attacking e4 (which Nc3 can no longer defend), or with 2...d5, since the queen on d5 cannot be chased by Nc3. In the 2...Nf6 line White usually ends up with an isolated d-pawn and active pieces."],"at":2,"moves":[["c3","Prepares d4, so that after ...cxd4 the c-pawn can recapture and White keeps pawns on d4 and e4."],["Nf6","Black attacks e4 at once; White cannot defend it with Nc3 because the pawn stands on c3."],["e5","White gains space with tempo, kicking the knight."],["Nd5","The knight finds a fine central square; kicking it with c4 would cost White a tempo and take the pawn away from supporting d4."],["d4","White builds the centre that c3 was preparing."],["cxd4","Black trades the c-pawn before White can support d4 any further."],["Nf3","Develops first; White can recapture on d4 next move with the pawn."],["Nc6","Develops and adds pressure on d4 and e5."],["cxd4","White recaptures and has pawns on d4 and e5, but the e5 pawn is a target."],["d6","Black hits the e5 spearhead at once, to break up White's centre."],["Bc4","White develops with tempo, attacking the knight on d5."],["Nb6","The knight retreats and attacks the bishop in return."],["Bb5","The bishop pins the knight on c6 against Black's king, so it cannot capture on e5 or d4."],["dxe5","Black clears the centre. After 9.Nxe5 Bd7 the pin is broken; White has an isolated d-pawn and active pieces, Black a solid position."]],"vars":[{"name":"Alapin: 2...d5","summary":"Black strikes in the centre at once; the queen recaptures on d5 because Nc3 is not available.","idea":["Black uses the drawback of 2.c3: with the c3 square taken, White cannot gain a tempo on the queen with Nc3. Black develops naturally with ...Nf6, ...Bg4 and ...e6, and pressures d4. White usually plays h3 and c4 to gain time on the queen and the bishop, reaching an isolated-pawn or open position."],"at":3,"moves":[["d5","Black hits e4 straight away, before White has time to play d4."],["exd5","White takes; letting Black play ...dxe4 would leave White with nothing."],["Qxd5","The queen recaptures. Normally this costs a tempo after Nc3, but here c3 is occupied by a pawn."],["d4","White takes the centre, as c3 intended."],["Nf6","Develops and covers the queen; Black will put pressure on d4."],["Nf3","Develops and protects d4."],["Bg4","Pins the knight against the queen on d1, adding pressure on d4."],["Be2","Breaks the pin and prepares to castle."],["e6","Frees the bishop on f8 and keeps a solid pawn on e6."],["O-O","White castles; next come h3 and c4 to gain time against the bishop and the queen."],["Nc6","Black develops and piles up on d4. The game turns on whether White's d-pawn becomes an asset or a target."]],"vars":[],"played":[677,674,562,497,260,259,41,17,15,5,4]}],"played":[1786,887,883,882,257,244,175,79,144,146,234,129,112,62]},{"name":"Closed Sicilian","summary":"White keeps the centre closed, fianchettoes the king's bishop and plans a kingside attack with f4–f5.","idea":["White avoids the open centre and the theory that comes with it. The bishop goes to g2 and the pawns to d3 and e4, a kind of King's Indian set-up reversed. White's plan is a slow kingside build-up with f4–f5 or Be3, Qd2 and Bh6 to trade Black's bishop on g7. Black mirrors with ...g6 and ...Bg7 and plays on the queenside, where ...Rb8 and ...b5–b4 gain space."],"at":2,"moves":[["Nc3","Develops while keeping the option of a closed centre; d4 is not part of White's plan."],["Nc6","Develops and controls d4, a square White has given up on for now."],["g3","Prepares the fianchetto: the bishop on g2 will support e4 and aim at the long diagonal."],["g6","Black fianchettoes too, so that the bishop on g7 can control the d4 and e5 squares."],["Bg2","The bishop takes up its long diagonal, aimed at b7 and the queenside."],["Bg7","Black's bishop aims at White's queenside along the a1–h8 diagonal."],["d3","Supports e4 and opens the c1 bishop. White keeps the centre closed."],["d6","Black does the same, controlling e5 and opening the c8 bishop."],["Be3","Aims the bishop at the queenside and prepares Qd2 and Bh6, to trade off Black's strong bishop on g7."],["e6","Prepares ...Nge7, so that the knight does not block the g7 bishop, and controls d5 and f5."],["Qd2","Connects the queen with the bishop; Bh6 is now a threat to trade the defender of Black's king."],["Rb8","Prepares ...b5–b4, the standard queenside expansion, gaining space and harassing the knight on c3."],["Nge2","The knight goes to e2 so that the f-pawn is free to advance with f4, and it adds control of d4."],["Nd4","The knight takes the d4 outpost. If White takes it, ...cxd4 opens the c-file and hits the knight on c3."]],"vars":[{"name":"Grand Prix Attack","summary":"White plays f4 early and aims for a quick kingside attack with f5.","idea":["Instead of the slow fianchetto, White pushes the f-pawn at once and develops the bishop actively on b5 or c4. The plan is to castle, play d3, bring the queen to e1 and h4, and break with f5 against Black's king. Black should challenge White quickly, often with ...Nd4, to take the bishop pair and blunt the attack."],"at":4,"moves":[["f4","White grabs kingside space and prepares a quick f5 break."],["g6","Black fianchettoes so that the bishop on g7 hits b2 and controls e5."],["Nf3","Develops to the natural square, where the knight backs up the f4 pawn's control of e5 and can later join a kingside attack via g5."],["Bg7","The bishop takes the long diagonal, where it controls d4 and e5 and eyes White's queenside."],["Bb5","The bishop threatens to take on c6, doubling Black's pawns and removing a defender of d4 and e5."],["Nd4","Black sidesteps the threat with tempo: the knight hits the bishop on b5 and the knight on f3."],["O-O","White castles and lets Black take the bishop, counting on rapid development."],["Nxb5","Black takes the bishop, so Black has the bishop pair and White can no longer double Black's pawns with Bxc6."],["Nxb5","The knight recaptures and eyes d6 and c7. Black usually plays ...d6 and ...a6 next; White plans d3, Qe1 and f5."]],"vars":[],"played":[116,83,83,83,43,43,28,11,11]}],"played":[2420,1099,136,127,125,126,124,80,56,5,16,7,3,2]},{"name":"Smith–Morra Gambit","summary":"White gives a pawn for quick development and open lines against Black's king.","idea":["White sacrifices the d- and c-pawns for one Black pawn, ending up a pawn down but with both knights and bishops out quickly and open c- and d-files for the rooks. The plan is Bc4, O-O, Qe2 and Rd1, with tactics on d6 and e6 and the e5 break. Black has to develop carefully, keeping d6 and f7 safe; once Black has castled, the extra pawn should tell."],"at":2,"moves":[["d4","White offers to open the centre at once, before playing Nf3."],["cxd4","Black takes, as in the Open Sicilian, and now White must decide whether to regain the pawn or offer more."],["c3","The gambit: White offers a second pawn to recapture with a piece and open lines."],["dxc3","Black accepts the pawn; declining with 3...Nf6 or 3...d5 is also possible."],["Nxc3","White is a pawn down but has the knight on c3 and the c- and d-files half-open."],["Nc6","Develops and controls e5, slowing down White's e5 break, one of the gambit's main weapons."],["Nf3","Develops towards the centre, where the knight supports the e5 break and can jump to g5 against f7."],["d6","Covers e5 and opens the bishop on c8."],["Bc4","The bishop aims at f7 and e6, the sore spots in Black's position."],["e6","Blunts the bishop on c4 and prepares ...Be7."],["O-O","King to safety; the rook is ready for the centre."],["Nf6","Develops the knight to its best square, covering d5 and h7, so that Black can castle short next."],["Qe2","Clears d1 for the rook, which will press on d6 down the open d-file, and backs up a later e5."],["Be7","Black prepares to castle. After 9.Rd1 the rook bears down on d6; Black usually answers ...e5 or ...Qc7."]],"vars":[],"played":[206,206,85,31,31,23,21,8,8,1,1,0,0,0]}],"played":[94897,37714,32686,15341,10755,10547,9956,9927,9557,1823,1798,1406,1078,925,819,660,281,187,202,199,150,150]},{"id":"sicilian-najdorf","name":"Sicilian Najdorf","eco":"B90–B99","side":"b","group":"semi-open","summary":"5...a6: a flexible, ambitious Sicilian, the choice of Fischer and Kasparov.","idea":["The little pawn move 5...a6 takes the b5 square away from White's knights and bishop, so that Black can play ...e5 or ...b5 without being harassed. Black keeps every option open: the bold ...e5, gaining space and chasing the knight from d4 at the cost of a hole on d5 and a backward d6 pawn, or ...e6 with the solid Scheveningen pawn structure.","After ...e5 the whole game revolves around d5: White wants to plant a knight there and trade the pieces that defend it, while Black wants to keep it covered (with ...Be6 and the knight on f6) and eventually play ...d5 to free the position. Black's counterplay comes on the queenside: ...b5–b4 to dislodge the knight on c3, the c-file, and the typical exchange sacrifice ...Rxc3.","White's main tries are the English Attack (Be3, f3, Qd2, O-O-O and g4–g5), where both sides storm the other's king; the sharp 6.Bg5 with f4, aiming at e5; and quieter moves such as 6.Be2, fighting positionally for d5. In the attacking lines, speed matters more than material."],"moves":[["e4","White takes the centre and opens lines for the queen and the king's bishop."],["c5","The Sicilian: Black fights for d4 from the side and unbalances the game."],["Nf3","Develops towards the centre and prepares d4, so that the knight can recapture there."],["d6","Covers e5, so the knight coming to f6 cannot be kicked by e5, and frees the c8 bishop."],["d4","White opens the centre to make use of the lead in development."],["cxd4","Black trades a wing pawn for a central one and gets the half-open c-file."],["Nxd4","White recaptures with a strong central knight, eyeing b5, c6, e6 and f5."],["Nf6","Develops with an attack on e4, so White must defend it before anything else."],["Nc3","Guards e4 with a piece; White gives up the c2–c4 clamp in favour of quick development."],["a6","The Najdorf: Black takes b5 from White's pieces, preparing ...e5 or ...b5 without Bb5+ or Nb5 ideas."],["Be3","The English Attack: the bishop guards d4 and is ready for Qd2 and long castling."],["e5","Black gains space and kicks the knight. It leaves a hole on d5 and a backward pawn on d6, which Black covers with active pieces."],["Nb3","The knight retreats to b3, where it stays out of the way and keeps an eye on d4 and c5."],["Be6","The bishop covers d5, the key square, and prepares ...d5 one day."],["f3","Stops ...Ng4, which would hit the bishop on e3, and prepares the g4 pawn storm."],["Be7","Black develops the bishop where it guards the knight on f6, and gets ready to castle kingside."],["Qd2","Connects the queen with the bishop and prepares long castling."],["O-O","Black castles, accepting that White's pawns will come at the king."],["O-O-O","White castles queenside: the kings are on opposite wings and both sides will attack."],["Nbd7","The knight covers e5 and c5 and can go to b6 to jump into c4, supporting the queenside attack."],["g4","White starts the pawn storm: g5 will drive the knight from f6, the main defender of d5 and h7."],["b5","Black counterattacks, preparing ...b4 to kick the knight on c3."],["g5","Attacks the knight on f6, which defends d5 and h7; White wants to drive it away and plant a knight on d5."],["b4","Black ignores the threat and hits the knight on c3: a pure race. White usually plays 13.Ne2, and both sides keep throwing pawns forward."]],"vars":[{"name":"6.Bg5","summary":"The old main line: White pins down the f6 knight and prepares f4 and e5.","idea":["White develops the bishop to g5, aiming at the knight on f6, and follows with f4, Qf3 and O-O-O. The threat is e5 at the right moment, or g4–g5 to drive the knight away from d5 and e4. Black usually sets up with ...e6, ...Be7, ...Qc7 and ...Nbd7, then counterattacks with ...b5. The most daring reply is the Poisoned Pawn, where Black grabs the b2 pawn with the queen."],"at":10,"moves":[["Bg5","Develops with pressure on the knight on f6, which guards d5 and e4."],["e6","The solid answer: Black covers d5 and opens e7 for the bishop."],["f4","Prepares e5, which would hit the knight on f6, and gains kingside space."],["Be7","The bishop guards f6, so after e5 or Bxf6 Black has a piece ready to recapture."],["Qf3","The queen supports e4 and e5 and adds pressure on f6, clearing d1 for long castling."],["Qc7","The queen goes to its typical Sicilian square, on the c-file, supporting ...b5 and ...Nbd7."],["O-O-O","White castles long; the rook on d1 aims at d6."],["Nbd7","The knight supports f6 and covers e5, slowing down White's e5 break."],["g4","White threatens g5, driving the knight from f6."],["b5","Black counterattacks on the queenside, preparing ...b4 against the knight on c3."]],"vars":[{"name":"Poisoned Pawn","summary":"Black's queen grabs the b2 pawn, inviting White to attack the queen and the king.","idea":["Black hits b2 and the knight on d4 with the queen. White usually gives the b2 pawn for development, and the queen has to run back to a3. Black is a pawn up, but White has a big lead in development and attacks with f5 or e5. It is one of the most heavily analysed lines in chess: playable only with deep preparation."],"at":13,"moves":[["Qb6","The queen attacks b2 and the knight on d4 at the same time."],["Qd2","White sacrifices the b2 pawn to keep developing and castle long later."],["Qxb2","Black takes: a pawn up, but the queen is far from home."],["Rb1","The rook gains time by attacking the queen."],["Qa3","The queen hides on a3, where it still eyes the knight on c3. White now plays 10.f5 or 10.e5, sacrificing more to open lines."]],"vars":[],"played":[156,100,89,89,89]}],"played":[1339,802,620,142,137,119,119,112,91,46]},{"name":"Opočenský: 6.Be2","summary":"A calm, positional approach: White castles kingside and fights for d5.","idea":["White develops quietly and castles short. After ...e5 the knight goes to b3 and the battle is about d5: White can play Bg5 to trade Black's knight on f6, a4 to stop ...b5, and Nd5 when it works. Black aims for ...Be6, ...Nbd7, ...Rc8 and eventually ...d5, which frees the game."],"at":10,"moves":[["Be2","Develops modestly and prepares kingside castling."],["e5","Black takes space and chases the knight from the centre."],["Nb3","The knight retreats, keeping an eye on d4 and c5."],["Be7","Black develops the bishop to e7, where it guards f6 and lets Black castle quickly."],["O-O","King to safety. White will play a4, Be3 and f4 or Bg5."],["O-O","Black castles too; with both kings on the kingside, the fight is about d5 rather than a race."],["Be3","Develops and controls c5 and b6, taking squares away from Black's queenside pieces."],["Be6","The bishop guards d5 and eyes the knight on b3. Black is ready for ...Nbd7 and ...Rc8."]],"vars":[],"played":[910,759,680,614,271,259,62,63]},{"name":"Fischer–Sozin Attack","summary":"The bishop aims at e6 and f7, ready for sacrifices.","idea":["White puts the bishop on the a2–g8 diagonal, where it targets e6 and f7, and prepares f4–f5 or sacrifices on e6 and b5. Black closes the diagonal with ...e6 and expands with ...b5, gaining time on the bishop. The bishop goes back to b3 and stays there, ready for Nd5 or Nxe6 tactics."],"at":10,"moves":[["Bc4","The bishop aims at f7 and e6 and stops ...d5."],["e6","Blunts the bishop and keeps d5 under control."],["Bb3","Steps back before ...b5 can hit it, keeping the diagonal."],["b5","Black gains queenside space and prepares ...Bb7, aimed at e4."],["O-O","White castles; f4–f5 is an idea for later."],["Be7","Black develops and prepares to castle. 9.Qf3 is a typical follow-up, eyeing the long diagonal towards a8 in case White can play e5."]],"vars":[],"played":[297,287,102,43,9,16]}],"played":[94897,37714,32686,15341,10755,10547,9956,9927,9557,7219,1671,1172,816,493,293,184,405,117,119,104,110,119,109,30]},{"id":"sicilian-dragon","name":"Sicilian Dragon","eco":"B70–B79","side":"b","group":"semi-open","summary":"5...g6: the bishop goes to g7 and breathes fire down the long diagonal.","idea":["Black fianchettoes the king's bishop on g7, where it strikes along the a1–h8 diagonal at d4, c3 and b2. The pawns on d6 and g6 look like the constellation that gave the line its name. The structure is solid, and the \"Dragon bishop\" is Black's best piece: if White castles queenside, it points straight at White's king.","White's critical answer is the Yugoslav Attack: Be3, f3, Qd2 and O-O-O, then h4–h5 to open the h-file and Bh6 to trade off the Dragon bishop. If that bishop goes, and the h-file opens, Black's king is in grave danger. Black races on the queenside: ...Rc8, ...Ne5–c4 to attack the bishop and queen, ...b5, and the exchange sacrifice ...Rxc3 that wrecks White's king position.","The Yugoslav is one of the sharpest races in chess: tempo counts more than pawns. Calmer lines with Be2 and kingside castling are less dangerous, as the Dragon bishop then has less to bite on and Black gets easy play. Black can also play the \"Accelerated\" version, with ...g6 before ...d6, to keep ...d5 in one move as an option."],"moves":[["e4","White takes the centre and opens lines for the queen and the king's bishop."],["c5","The Sicilian: Black fights for d4 from the side and keeps the position unbalanced."],["Nf3","Develops towards the centre and prepares d4, so that a piece can recapture there."],["d6","Covers e5, so that the knight coming to f6 cannot be kicked by e5, and frees the c8 bishop."],["d4","White opens the centre at once to make use of the lead in development."],["cxd4","Black trades a wing pawn for a central one and gets the half-open c-file, the highway for Black's counterplay."],["Nxd4","White recaptures with a strong central knight. It will soon be a target for the Dragon bishop."],["Nf6","Develops with an attack on e4, so White has to spend the next move defending it."],["Nc3","Guards e4 with a piece, keeping the f-pawn free for f3 or f4 later."],["g6","The Dragon: the bishop will go to g7, on the long diagonal through d4, c3 and b2, while the g6 pawn shields Black's king."],["Be3","Protects the knight on d4 and prepares Qd2 and Bh6 to trade Black's key bishop."],["Bg7","The Dragon bishop takes its diagonal."],["f3","Stops ...Ng4, which would hit the bishop on e3, and supports a g4 pawn storm."],["O-O","Black castles kingside, behind the fianchetto."],["Qd2","Prepares Bh6 to trade the Dragon bishop and long castling."],["Nc6","Develops and challenges the knight on d4."],["Bc4","The bishop controls d5, stopping ...d5, and aims at f7."],["Bd7","Develops and clears c8 for the rook."],["O-O-O","White castles long: kings on opposite wings, attacks on both sides."],["Rc8","The rook takes the half-open c-file, aiming at c3 and c2, and lines up against the bishop on c4."],["Bb3","The bishop steps off the c-file before ...Ne5 can hit it with tempo."],["Ne5","Heads for c4, where it will hit the queen on d2 and the bishop on e3."],["h4","White starts the pawn storm: h5 and hxg6 will open the h-file against Black's king."],["h5","The Soltis Variation: Black stops h5 in its tracks. White now needs g4 to open lines, which takes time."]],"vars":[{"name":"Yugoslav: 9.O-O-O d5","summary":"White castles before Bc4, and Black breaks at once with ...d5.","idea":["Without the bishop on c4, Black can free the position with ...d5. Black gives up a pawn in some lines but opens the long diagonal and the b-file against White's king. The play is sharp but more strategic than the Bc4 lines: the Dragon bishop and the open files decide."],"at":16,"moves":[["O-O-O","White castles long first, keeping the bishop flexible."],["d5","The freeing break: with no bishop on c4 to stop it, Black opens the centre at once."],["exd5","White takes; Black will recapture with the knight and open the game."],["Nxd5","The knight recaptures and the long diagonal opens: now the knight on d4 is attacked twice, by the knight on c6 and the bishop on g7."],["Nxc6","White trades knights so that the bishop on e3 can go to d4."],["bxc6","Black takes towards the centre and gets the half-open b-file against White's king."],["Bd4","White offers to trade off the Dragon bishop, the main defender of Black's king and attacker of White's."],["e5","Black gains time on the bishop and builds a central pawn mass. After 13.Bc5 Black usually plays 13...Be6, playing for activity rather than material."]],"vars":[],"played":[194,169,110,110,110,110,108,62]},{"name":"Classical: 6.Be2","summary":"A quiet set-up with kingside castling: less dangerous, but solid.","idea":["White develops calmly and castles short. Without opposite-side castling, there is no race; instead, both sides manoeuvre. Black uses the c-file, ...Na5–c4 and the Dragon bishop, while White tries f4–f5 or a kingside advance."],"at":10,"moves":[["Be2","Develops modestly and prepares kingside castling, with no ambitions of a pawn storm."],["Bg7","The Dragon bishop takes the long diagonal, aimed at d4 and the queenside."],["O-O","White castles short, so the Dragon bishop does not point at White's king."],["O-O","Black castles too; with both kings on the same side, the play is about manoeuvring, not a race."],["Be3","Protects the knight on d4, which the bishop on g7 and the coming ...Nc6 both attack."],["Nc6","Develops and adds a second attacker on d4."],["Nb3","The knight steps back to avoid exchanges, which would free Black's game."],["Be6","Develops with an eye on the knight on b3 and on c4, where Black likes to put a knight via a5. White often plays 10.f4 next, aiming for f5."]],"vars":[],"played":[40,40,33,28,9,11,11,14]},{"name":"Accelerated Dragon: Maróczy Bind","summary":"Black plays ...g6 before ...d6; White clamps d5 with c4.","idea":["Black delays ...d6 so that ...d5 can come in one move. White's best try is the Maróczy Bind: pawns on c4 and e4 that clamp the d5 square, so Black cannot free the game easily. The play is slow: Black manoeuvres and looks for ...b5 or ...f5 breaks, while White tries to keep the clamp and use the extra space."],"at":3,"moves":[["Nc6","Develops and controls d4 and e5, keeping the choice between ...d6 and ...g6 set-ups."],["d4","White opens the centre, as in the Open Sicilian."],["cxd4","Black trades the wing pawn for White's d-pawn."],["Nxd4","White recaptures and the knight is attacked by the one on c6, but it is well protected by the queen."],["g6","The Accelerated Dragon: Black skips ...d6, so that after Nc3 the freeing ...d5 can come in one move."],["c4","The Maróczy Bind: the pawns on c4 and e4 clamp d5, so Black's freeing break is off the table."],["Bg7","The bishop takes the long diagonal and adds a second attacker on the knight on d4."],["Be3","Protects the knight on d4 a second time and gets ready for Nc3 and Be2."],["Nf6","Develops with an attack on e4; White cannot defend it with a pawn, as c4 has already been played."],["Nc3","Guards e4 and adds a third piece to the control of d5."],["O-O","Black tucks the king away behind the fianchetto before deciding on a plan."],["Be2","A modest square: the bishop protects the c4 pawn and lets White castle short with a safe king."],["d6","Black settles for a solid set-up and cramped but sound play; ...Bd7 and ...a5, or ...Nxd4 and ...Be6, often follow, with ...b5 or ...f5 breaks in mind."]],"vars":[],"played":[8381,3235,3235,3226,518,507,244,417,204,203,120,120,108]}],"played":[94897,37714,32686,15341,10755,10547,9956,9927,9557,587,497,352,337,197,186,186,69,54,42,29,24,23,4,4]},{"id":"sicilian-sveshnikov","name":"Sicilian Sveshnikov","eco":"B33","side":"b","group":"semi-open","summary":"Black plays ...e5 early, accepting a hole on d5 for activity, the bishop pair and fast development.","idea":["Black plays ...e5 early, gaining time on the knight on d4, at the cost of a hole on d5 and a backward d6 pawn. In return, Black gets fast development, space in the centre and, in the main line, the bishop pair after White trades the bishop for the knight on f6 to win control of d5.","After Bxf6 gxf6, Black's pawn structure looks ugly, but the f-pawns are a battering ram: ...f5 hits e4 and opens the long diagonal for the bishop on g7. Black aims for ...f5, ...f4 or ...e4, and active pieces on the kingside. White wants to plant a knight on d5 and keep it there, re-route the offside knight from a3 via c2 to e3, and attack the queenside with a4 and c3.","It is a dynamic, theoretical opening: White has the better structure, Black has the more active pieces. The game often hinges on whether the knight on d5 dominates or Black's pawns and bishops break through."],"moves":[["e4","White takes the centre and opens lines for the queen and the king's bishop."],["c5","The Sicilian: Black fights for d4 from the side and keeps the position unbalanced."],["Nf3","Develops towards the centre and prepares d4."],["Nc6","Develops and controls d4 and e5; the d-pawn stays at home, ready to go to d6 in one step later."],["d4","White opens the centre at once, the most testing reply."],["cxd4","Black trades a wing pawn for a central one and gets the half-open c-file."],["Nxd4","White recaptures; the knight is attacked by the one on c6 but protected by the queen."],["Nf6","Develops with an attack on e4, so White must defend it."],["Nc3","Guards e4 with a piece, and the knight will soon be eyeing d5."],["e5","The Sveshnikov: Black kicks the knight and takes space in the centre, at the cost of a hole on d5 and a backward d-pawn."],["Ndb5","The most active retreat: the knight threatens Nd6+, which would trade off Black's dark-squared bishop and leave the dark squares weak."],["d6","Stops Nd6+. The pawn on d6 is backward, and much of the game will be about it and the d5 square in front of it."],["Bg5","White aims to trade the knight on f6, the main defender of d5, so that a White knight can settle there."],["a6","Kicks the knight on b5 back towards the edge of the board."],["Na3","The knight retreats to a3, offside for now; it hopes to return via c4, or via c2 to e3."],["b5","Takes b5 and c4 from the a3 knight and prepares ...b4 to kick the knight on c3."],["Bxf6","White gives up the bishop to remove the knight on f6, the main defender of d5."],["gxf6","Black takes with the pawn: after the queen recapture, Nd5 would hit it. Black gets the bishop pair and the f-pawns."],["Nd5","The knight lands on d5, the outpost White has fought for."],["f5","Black hits e4 and opens the long diagonal for the bishop, which will go to g7."],["Bd3","Protects e4 and adds pressure on b5."],["Be6","Develops and challenges the knight on d5; ...Bxd5 and ...Bg7 are next."]],"vars":[{"name":"11.c3","summary":"The modern main line: White re-routes the a3 knight to e3 via c2.","idea":["Instead of Bd3, White plays c3 to free c2 for the knight, which then goes to e3, supporting the knight on d5. The pawn on c3 also covers b4 and prepares a4 against Black's queenside. Black takes on e4, develops with ...Bg7 and ...O-O, and plays for ...f5."],"at":20,"moves":[["c3","Frees c2 for the knight's trip Na3–c2–e3, which supports d5, and takes b4 away from Black's pawn."],["Bg7","The bishop takes the long diagonal; with the f-pawn gone from f6, it will press on e5 and the queenside."],["exf5","White takes the f5 pawn, so Black must spend a move recapturing."],["Bxf5","Black recaptures with the bishop, which is active on f5, on the open b1–h7 diagonal."],["Nc2","The offside knight comes back into play, heading for e3 to support d5 and hit f5."],["O-O","Black castles; the king is reasonably safe because White has no quick way to open the g-file."],["Nce3","The knight attacks the bishop on f5 and doubles White's control of d5."],["Be6","The bishop retreats to a square where it watches d5 and can trade itself for the knight there. Black will look for ...f5 again."]],"vars":[],"played":[38,37,37,37,36,30,23,22]},{"name":"9.Nd5","summary":"White keeps the bishop for a moment and plants the knight on d5 at once.","idea":["Instead of taking on f6 straight away, White puts the knight on d5. After ...Be7 and Bxf6 Bxf6, Black keeps a healthy pawn structure. The bishop on f6 often goes to g5, where it controls the c1–h6 diagonal and the e3 square that White's knight wants. White plays c3 and Nc2–e3 to keep d5 under control, and a4 to open the queenside."],"at":16,"moves":[["Nd5","The knight takes d5 at once, attacking the knight on f6 a second time."],["Be7","Black develops and prepares to recapture on f6 with the bishop, so the pawns stay intact."],["Bxf6","White trades the defender of d5."],["Bxf6","Black recaptures with the bishop; there is no doubled f-pawn this time."],["c3","Prepares Nc2–e3, adding a second knight to the control of d5, and covers b4."],["O-O","Black castles, now that the king's side is solid."],["Nc2","The knight starts back into play, heading for e3."],["Bg5","The bishop goes to g5, where it controls e3 and the c1–h6 diagonal. White usually plays 13.a4 next, to open lines on the queenside."]],"vars":[],"played":[522,485,474,473,310,75,72,20]},{"name":"Kalashnikov: 4...e5","summary":"Black plays ...e5 before ...Nf6, a close cousin of the Sveshnikov.","idea":["Black plays ...e5 at once, before ...Nf6. The ideas are the same: Black accepts the hole on d5 and the backward d-pawn for space and active play. The difference is that White's knight on b1 is not yet committed to c3, so White can choose c4, clamping d5 with a pawn, or N1c3 and Nd5."],"at":7,"moves":[["e5","Black kicks the knight at once, before developing the king's knight."],["Nb5","The knight jumps to b5, threatening Nd6+, which would force Black to give up the dark-squared bishop for the knight."],["d6","Stops Nd6+; the pawn on d6 is backward, but it supports e5 and covers c5."],["N1c3","White develops the queen's knight towards d5; 6.c4, clamping d5 with a pawn, is the other main move."],["a6","Kicks the knight on b5 away from the centre."],["Na3","The knight retreats to a3, with c4 and c2 in mind."],["b5","Black takes c4 away from the a3 knight and keeps it offside."],["Nd5","The knight takes the d5 outpost. Black usually continues ...Nge7, challenging it, and keeps the f-pawn free for ...f5."]],"vars":[],"played":[637,613,562,277,277,276,46,45]},{"name":"Rossolimo: 3.Bb5","summary":"White's most popular way to avoid the Sveshnikov altogether.","idea":["White develops the bishop to b5 instead of opening the centre, and is often happy to take on c6, doubling Black's pawns. White gives up the bishop pair for a better pawn structure and quick development, then plays d3, h3, Be3 and Qd2, sometimes with Bh6 to trade the bishop on g7. Black gets the bishop pair and a half-open d-file, and aims for ...e5 and ...b6, keeping the position closed until the bishops can come alive."],"at":4,"moves":[["Bb5","The bishop hits the knight on c6, threatening to take it and double Black's pawns."],["g6","Black fianchettoes, so the bishop on g7 can control the long diagonal and d4."],["Bxc6","White gives up the bishop pair to double Black's pawns."],["dxc6","Black recaptures towards the centre, opening the d-file for the queen and the diagonal for the c8 bishop."],["d3","Supports e4 and opens the c1 bishop. White keeps the centre closed, which suits the knights."],["Bg7","The bishop takes the long diagonal, where it controls d4 and e5 and eyes White's queenside."],["h3","Prepares Be3 without allowing ...Ng4, and stops ...Bg4 pinning the knight on f3."],["Nf6","Develops towards the centre, where the knight eyes e4 and d5."],["Nc3","Develops and guards e4. Be3 and Qd2 come next."],["O-O","Black castles; ...b6 and ...e5 or ...Nd7 are the usual next steps."]],"vars":[],"played":[4096,1568,573,306,270,222,165,99,89,35]}],"played":[94897,37714,32686,8381,3235,3235,3226,1660,1659,970,943,935,625,823,808,775,141,140,155,100,27,27]},{"id":"french","name":"French Defence","eco":"C00–C19","side":"b","group":"semi-open","summary":"1...e6 and 2...d5: a solid pawn chain, then counterplay with ...c5 and ...f6 against White's centre.","idea":["Black answers 1.e4 with the modest 1...e6, only to strike with ...d5 on the next move. The e6 pawn supports d5, so Black never has to give up the centre. The cost is the light-squared bishop on c8, which is shut in behind its own pawns: the \"French bishop\" is the opening's eternal problem piece.","The typical structure arises when White pushes e4–e5: a pawn chain d4–e5 for White against e6–d5 for Black. White has space on the kingside and attacks there, often with f4–f5, a knight on f3 or g5, and pieces aimed at h7. Black attacks the base of the chain: ...c5 hits d4, and ...f6 hits e5. The queen on b6, the knights on c6 and f5 (or e7) and the open c-file all join the pressure on d4.","If White does not push e5, the centre usually opens: Black gets free development and often an isolated or hanging pawn structure to fight over, as in the Tarrasch and Rubinstein lines. Either way, the French is a game of pawn levers and timing: whoever breaks first and best gets the initiative."],"moves":[["e4","Stakes a claim to the centre (d5 and f5) and opens lines for the queen and the king's bishop."],["e6","A quiet move with a sharp point: it prepares ...d5, so that Black can challenge e4 with a pawn that is already supported."],["d4","White takes the full centre with two pawns, which Black's first move allowed."],["d5","The point of 1...e6: Black attacks e4, and if White takes on d5 the e-pawn recaptures and Black keeps a pawn in the centre."],["Nc3","White defends e4 with a piece and keeps all options open. The centre stays tense."],["Nf6","The Classical French: a second attack on e4, asking White to decide what to do with the pawn."],["e5","The Steinitz Variation: White gains space and drives the knight off f6, the best defender of Black's kingside. The chain d4–e5 against e6–d5 is now fixed."],["Nfd7","The knight retreats to d7, where it hits e5 and supports the coming ...c5."],["f4","White props up e5 with another pawn, so that ...f6 or ...c5 cannot easily undermine it, and gains space for a kingside attack with f5 in mind."],["c5","Black strikes at the base of the chain on d4. This lever is the heart of every French."],["Nf3","The knight defends d4 and backs up e5 at the same time."],["Nc6","Black piles up on d4: the knight joins the c5 pawn, and ...Qb6 could add another attacker."],["Be3","Defends d4 again and prepares Qd2 and castling queenside."],["cxd4","Black releases the tension to open the c-file and free the c5 square for the bishop."],["Nxd4","White recaptures with the knight, which keeps the f4–e5 chain intact and puts the knight on a central square."],["Bc5","The bishop develops with pressure on d4. Trading pieces there would ease Black's cramped position."],["Qd2","The queen guards d4 along the d-file and clears the back rank for long castling."],["O-O","Black castles short. With White heading for the other wing, both sides will race to attack the enemy king."],["O-O-O","White castles long, puts the rook on the d-file and frees the kingside pawns to storm forward."],["a6","Prepares ...b5–b4 to drive the knight from c3 and open lines towards White's king. It also takes b5 from White's knights."],["h4","White's attack begins: the pawn heads for h5 and h6 to loosen Black's king, and the rook can swing into play via h3."],["Nxd4","Black trades on d4 to reduce White's attacking force and clear the way for the b-pawn."],["Bxd4","White recaptures with the bishop; now the two dark-squared bishops face each other on c5 and d4."],["b5","Black's queenside storm is under way: ...b4 will hit the knight on c3. The main line continues 13.Rh3 b4 14.Na4 Bxd4 15.Qxd4 f6, when Black also breaks at e5."]],"vars":[{"name":"Advance Variation","summary":"White fixes the chain at once and holds d4; Black piles up on it with ...c5, ...Nc6 and ...Qb6.","idea":["With 3.e5 White gains space immediately and sets up the chain d4–e5 before Black has developed. The whole battle is about d4, the base of the chain: White supports it with c3 and Nf3, Black attacks it with ...c5, ...Nc6, ...Qb6 and often a knight on f5. If d4 holds, White has a comfortable space edge and kingside chances; if it falls, the e5 pawn loses its support and Black takes over the centre."],"at":4,"moves":[["e5","White grabs space at once and fixes the pawn chain d4–e5 against e6–d5."],["c5","Black hits the base of the chain straight away, before White can support it with pieces."],["c3","Supports d4 with a pawn, so that ...cxd4 can be answered by cxd4 and the chain stays intact."],["Nc6","Adds a second attacker on d4."],["Nf3","Defends d4 and also covers e5."],["Qb6","The queen joins the attack on d4 and hits b2, which only the bishop on c1 now guards."],["Be2","A sound developing move: unlike Bd3, the bishop on e2 does not block the queen's defence of d4 along the d-file."],["cxd4","Black opens the c-file, which will be useful for the rooks, and keeps d4 under fire."],["cxd4","White recaptures and keeps the chain."],["Nh6","An odd-looking but standard route: the knight is bound for f5, where it attacks d4 again. If Bxh6, gxh6 gives Black the bishop pair and the g-file."],["Nc3","White develops, ready to meet ...Nf5 with Na4, gaining time against the queen on b6."],["Nf5","Now d4 is attacked by three pieces and White must defend it precisely, typically with 9.Na4 Qa5+ 10.Bd2, gaining time against the queen."]],"vars":[{"name":"Milner-Barry Gambit","summary":"White gives up the d4 pawn for speedy development and attacking chances.","idea":["White puts the bishop on its best diagonal, towards h7, even though it blocks the queen's defence of d4. After the exchange on d4 White castles and lets the pawn go, hoping to use the lead in development and the exposed black queen. Black must avoid a famous trap first, but with care can keep the pawn; the gambit is risky for both sides."],"at":10,"moves":[["Bd3","The bishop takes the b1–h7 diagonal, but it cuts the queen off from d4: White is ready to give up the d-pawn."],["cxd4","Black opens the c-file and increases the pressure on d4."],["cxd4","White recaptures, keeping the chain for now."],["Bd7","Careful: 7...Nxd4? 8.Nxd4 Qxd4?? 9.Bb5+ uncovers White's queen on d1 against Black's queen on d4. The bishop on d7 rules out that check."],["O-O","White castles and offers the d-pawn as a gambit."],["Nxd4","Black accepts. With the bishop on d7 blocking the b5–e8 diagonal, the check on b5 is no longer a worry."],["Nxd4","White trades knights to bring the black queen forward."],["Qxd4","Black is a pawn up, but the queen is exposed in the centre and the king is still on e8."],["Nc3","White develops and threatens Nb5, which would hit the queen and eye d6 and c7."],["a6","Black takes b5 from the knight. White continues with Qe2, Kh1 and f4, or with Re1, and has real compensation; 10...Qxe5 11.Re1 is a sharper way to grab a second pawn."]],"vars":[],"played":[143,115,5,5,16,16,2,2,2,1]}],"played":[1753,1691,1679,1377,1372,431,120,86,83,53,6,6]},{"name":"Winawer Variation","summary":"Black pins the knight and is ready to give up the dark-squared bishop to double White's pawns.","idea":["Black pins the knight on c3 and renews the threat to e4. After 4.e5 c5 5.a3 Black trades the bishop for the knight and gives White doubled c-pawns; in return White has the bishop pair and Black's dark squares, especially g7, lose their main defender. The game is sharp and unbalanced: White attacks on the kingside or uses the bishops, Black pressures the weak c3 and c2 pawns and plays on the queenside."],"at":5,"moves":[["Bb4","The bishop pins the knight on c3, so it no longer really defends e4."],["e5","White closes the centre and gains space, the main line against the Winawer."],["c5","Black hits d4 at once, the standard French lever."],["a3","White asks the bishop to decide: retreat or take on c3."],["Bxc3+","Black gives up the bishop to double White's pawns."],["bxc3","White has the bishop pair and an extra pawn in the centre, but the c-pawns are weak."],["Ne7","The knight goes to e7, out of reach of the e5 pawn, heading for f5 or c6."],["Qg4","With Black's dark-squared bishop gone, g7 is weak: the queen attacks it at once."],["Qc7","Black ignores the threat to g7 and counterattacks e5 and the c-file. This is the Poisoned Pawn Variation."],["Qxg7","White takes the pawn and threatens the rook on h8."],["Rg8","The rook steps to the open g-file with tempo on the queen."],["Qxh7","White wins a second pawn and will have a dangerous passed h-pawn."],["cxd4","Black opens the c-file: the queen on c7 now threatens ...Qxc3+, forking the king and the rook on a1."],["Ne2","The knight covers c3. Black will play ...Nbc6 and ...dxc3, and the position is a wild race between White's h-pawn and Black's central pawns."]],"vars":[],"played":[1343,984,721,633,552,552,260,174,80,43,43,43,43,39]},{"name":"Tarrasch Variation","summary":"White defends e4 with the knight on d2, avoiding the Winawer pin; Black hits back with ...c5.","idea":["With 3.Nd2 White protects e4 without allowing ...Bb4 pinning a knight on c3, and keeps the c-pawn free to support d4 with c3. The knight is less active on d2, so Black aims to open the game quickly with 3...c5. After 4.exd5 Black chooses between ...Qxd5, keeping a sound structure but losing a little time with the queen, and ...exd5, accepting an isolated pawn in return for quick, free development."],"at":4,"moves":[["Nd2","The knight defends e4 and cannot be pinned by ...Bb4, and the c-pawn stays free to go to c3."],["c5","Black strikes at d4 at once, aiming for an open game in which the knight on d2 is a little clumsy."],["exd5","White releases the tension in the centre."],["Qxd5","Black recaptures with the queen to avoid an isolated pawn. With the knight on d2 rather than c3, it cannot hit the queen at once."],["Ngf3","White develops and defends d4."],["cxd4","Black trades on d4 and will try to hold the extra pawn there for a while."],["Bc4","White develops with tempo, attacking the queen."],["Qd6","The queen steps back to a safe square and keeps guard over the d4 pawn."],["O-O","White castles; the d4 pawn will be rounded up soon."],["Nf6","Black develops and covers the king's side."],["Nb3","The knight attacks d4 a second time."],["Nc6","Black defends d4 again, but only for the moment."],["Nbxd4","White wins the pawn back. After 9...Nxd4 10.Nxd4 a6 Black has an extra central pawn (four against three on the kingside); White has the lead in development."]],"vars":[{"name":"The isolated pawn line: 4...exd5","summary":"Black accepts an isolated d-pawn in return for free and active pieces.","idea":["Instead of recapturing with the queen, Black takes with the e-pawn. The bishop on c8 is now free, and after White plays dxc5 and Black recaptures, Black has an isolated pawn on d5. White blockades it (a knight on d4 is ideal) and aims to trade pieces; Black uses the open lines and active pieces, and is happy if the d5 pawn can advance."],"at":7,"moves":[["exd5","Black recaptures with the pawn, freeing the light-squared bishop and keeping a pawn on d5."],["Ngf3","White develops and keeps pressure on c5."],["Nc6","Black develops and adds pressure to d4."],["Bb5","The bishop pins the knight on c6 against the king, getting ready to take on c5."],["Bd6","The bishop goes to its most active square, eyeing h2."],["dxc5","White takes, so that Black will have an isolated pawn on d5."],["Bxc5","Black recaptures. The d5 pawn is isolated, but Black's pieces are developing freely."],["O-O","White castles and starts eyeing the blockade square d4."],["Ne7","The knight goes to e7, where it supports the pinned knight on c6 and leaves the f-pawn free; Black can castle next."],["Nb3","The knight hits the bishop and takes control of d4, the square in front of the isolated pawn."],["Bd6","The bishop drops back to its best diagonal, aimed at h2. The game turns on d5: White blockades and presses it, Black uses the open lines."]],"vars":[],"played":[111,75,48,99,24,16,16,13,13,19,12]}],"played":[1877,1138,524,409,312,312,415,210,184,178,172,170,169]},{"name":"Exchange Variation","summary":"White trades on d5 for a symmetrical, open position; Black's problem bishop is freed at once.","idea":["By taking on d5 White makes the pawn structure symmetrical and opens the e-file. Black's light-squared bishop is no longer locked in, so the French's main problem disappears, and Black has an easy game. The fight is about piece activity: the e-file, the outposts on e4 and e5, and pins on the knights. It is solid and drawish if both sides play quietly, but it is far from dead if one side plays to castle on the other wing."],"at":4,"moves":[["exd5","White releases the tension at once, making the structure symmetrical."],["exd5","Black recaptures with the e-pawn, and the bishop on c8 has an open diagonal at last."],["Nf3","White develops towards the e5 square."],["Nf6","Black does the same, eyeing e4."],["Bd3","The bishop goes to its best diagonal, pointed at h7."],["Bd6","Black mirrors White, aiming the bishop at h2."],["O-O","White castles."],["O-O","Black castles too."],["Bg5","The bishop pins the knight on f6 against the queen."],["Bg4","Black pins back. With symmetry, the side who first puts a knight on the e4 or e5 outpost, or wins the e-file, gets the edge."]],"vars":[],"played":[660,655,491,226,267,182,96,94,51,39]},{"name":"Classical: 4.Bg5","summary":"White pins the knight on f6 instead of pushing at once; the old main line of the Classical French.","idea":["White pins the knight on f6 and only then pushes e5. After the trade of dark-squared bishops White has got rid of the \"bad\" bishop (the one hemmed in by the d4 and e5 pawns) for Black's good one, and supports e5 with f4. Black plays the usual ...c5 and ...Nc6 against d4 and keeps the queen on e7, where it covers the dark squares. The structure is like the Steinitz main line, with one pair of bishops gone."],"at":6,"moves":[["Bg5","Pins the knight on f6 against the queen, so it no longer really attacks e4."],["Be7","The Classical defence: the bishop breaks the pin. 4...Bb4 (the McCutcheon) and 4...dxe4 (the Burn) are sharper choices."],["e5","White kicks the knight and gains space."],["Nfd7","The knight drops back to d7, from where it hits e5 and supports ...c5."],["Bxe7","White trades the dark-squared bishops. 6.h4, the Alekhine–Chatard Attack, offers a pawn instead."],["Qxe7","The queen recaptures and takes over the dark squares that the bishop left behind."],["f4","White props up e5, as in the Steinitz."],["a6","Black takes b5 away from White's knight, which could otherwise jump in towards c7 and d6."],["Nf3","White develops and guards d4 and e5."],["c5","Black hits the base of the chain."],["Qd2","The queen defends d4 along the d-file and prepares long castling."],["Nc6","Black piles up on d4. White often takes 10.dxc5 to free d4 for a knight, with a position much like the Steinitz main line."]],"vars":[],"played":[777,106,105,99,43,43,37,26,16,16,8,9]}],"played":[94897,8906,8307,8384,3953,2142,1344,1329,1131,1131,1117,1057,1024,242,242,72,67,29,27,14,4,5,5,8]},{"id":"caro-kann","name":"Caro-Kann Defence","eco":"B10–B19","side":"b","group":"semi-open","summary":"1...c6 and 2...d5: Black supports d5 with the c-pawn and gets the light-squared bishop out before ...e6.","idea":["Black prepares ...d5 with 1...c6, so that the d5 pawn is backed by a pawn without blocking the bishop on c8. This is the Caro-Kann's big advantage over the French: the light-squared bishop usually comes out to f5 or g4 before Black plays ...e6. The price is slower development, as the c-pawn takes up the c6 square that the queen's knight would like.","In the main lines Black gives up the centre with ...dxe4 and gets a very sound pawn structure (pawns on c6 and e6, no weaknesses). White has more space and a small lead in development, and often castles long and pushes the h-pawn to gain kingside space. Black aims for ...c5 or ...e5 to free the position, and is happy to trade pieces: the Caro-Kann endgame is usually comfortable for Black.","In the Advance Variation the structure looks like a French, but Black's bishop is already outside the chain, so White plays actively to make that bishop a target. In the Exchange and Panov lines the game revolves around the d5 and d4 squares and, in the Panov, an isolated pawn."],"moves":[["e4","Stakes a claim to the centre (d5 and f5) and opens lines for the queen and the king's bishop."],["c6","Prepares ...d5 with pawn support, so that after exd5 Black can recapture with a pawn, and keeps the c8 bishop's diagonal open."],["d4","White takes the full centre."],["d5","Black challenges e4 at once."],["Nc3","White defends e4 with a piece and develops."],["dxe4","Black gives up the centre to free the game and develop the bishop with tempo."],["Nxe4","White recaptures, and the knight stands well in the centre."],["Bf5","The Classical Variation: the bishop develops with an attack on the knight, outside the pawn chain that ...e6 will build."],["Ng3","The knight hits the bishop and gains time."],["Bg6","The bishop stays on the b1–h7 diagonal."],["h4","White threatens h5, which would trap the bishop on g6, since the h7 pawn takes away its retreat."],["h6","Black makes room for the bishop on h7, so h5 can be met by ...Bh7."],["Nf3","White develops and eyes e5, where the knight would hit the bishop on g6."],["Nd7","Black covers e5, so the knight cannot jump there, and prepares ...Ngf6."],["h5","White gains space and fixes Black's h6 pawn; the h5 pawn will cramp Black's kingside for the rest of the game."],["Bh7","The bishop retreats but keeps its diagonal."],["Bd3","White offers to trade Black's best minor piece; afterwards Black's light squares are a little weaker."],["Bxd3","Black must trade, or White takes on h7 and wrecks the kingside."],["Qxd3","The queen recaptures and stands on a good central square, eyeing the light squares."],["e6","Black builds the solid c6–e6 structure and opens the f8 bishop."],["Bd2","White develops the last minor piece and prepares long castling."],["Ngf6","Black develops the other knight; Nxf6+ could now be met by ...Nxf6 without spoiling the structure."],["O-O-O","White castles long and puts the rook on d1 behind the d4 pawn."],["Be7","Black prepares to castle short, usually followed by ...c5. White has more space, Black has a solid structure with no weaknesses."]],"vars":[{"name":"Advance Variation","summary":"White grabs space; Black gets the bishop out first and then hits d4 with ...c5, as in a French.","idea":["White pushes e5 and gains space, giving a French-like structure. The difference is that Black's light-squared bishop gets out to f5 before ...e6, so Black has no bad bishop. White therefore plays either the calm Short System (Nf3, Be2, Be3, castling), keeping a small space edge, or chases the bishop with an early g4. Black's plan is ...c5 against d4, with ...Nc6 and ...Qb6, exactly as in the French."],"at":4,"moves":[["e5","White gains space and stops ...Nf6."],["Bf5","The point of the Caro-Kann: the bishop comes out before ...e6 closes its diagonal."],["Nf3","The calm Short System: White develops and castles, aiming for a small, lasting space edge."],["e6","Black builds the chain and opens the f8 bishop."],["Be2","White prepares to castle."],["c5","As in the French, Black strikes at d4, the base of the chain."],["Be3","White defends d4, so that ...cxd4 Nxd4 brings the knight to d4 with an attack on the bishop on f5."],["Nd7","Black develops the knight to d7, where it supports c5 and hits e5; the other knight will come to e7."]],"vars":[{"name":"Sharp line: 4.Nc3 e6 5.g4","summary":"White hunts the bishop with g4 and h4.","idea":["Instead of quiet development, White uses the extra space to chase Black's bishop with the kingside pawns. The pawns on g4 and h4 also gain space, but they loosen White's position. Black counters in the centre with ...c5, and must take care that the bishop is not trapped."],"at":6,"moves":[["Nc3","White develops and gets ready for g4."],["e6","Black completes the chain."],["g4","The pawn hits the bishop on f5."],["Bg6","The bishop retreats, staying on its diagonal."],["Nge2","The knight is bound for f4, where it will hit the bishop again; c3 is already taken by the other knight."],["c5","Black counterattacks in the centre, the right reply to a wing attack."],["h4","White threatens h5, after which the bishop on g6 would be trapped: the h7 pawn blocks its retreat and g4 covers f5 and h5."],["h5","Black stops h5 by putting a pawn there first, and also hits g4. White continues 8.Nf4, attacking the bishop and the h5 pawn."]],"vars":[],"played":[86,65,65,65,65,46,42,30]}],"played":[4163,3054,1107,1112,1070,306,172,10]},{"name":"Panov–Botvinnik Attack","summary":"White plays c4 against d5 and gets an isolated d-pawn with active pieces.","idea":["After the exchange on d5 White attacks the pawn again with c4. The usual result is a position with an isolated pawn on d4 for White, much like a Queen's Gambit. White has active pieces, the outpost on e5 and chances of a kingside attack (Bd3, Re1, Qe2, sometimes d5); Black blockades on d5, trades pieces and aims at the d4 pawn in the endgame."],"at":4,"moves":[["exd5","White trades on d5."],["cxd5","Black recaptures with the c-pawn, keeping a pawn in the centre."],["c4","The Panov–Botvinnik: White attacks d5 again and is willing to accept an isolated pawn."],["Nf6","Black defends d5."],["Nc3","Another attacker on d5."],["e6","Black supports d5 and opens the f8 bishop; the game will look like a Queen's Gambit."],["Nf3","White develops and guards d4."],["Be7","Black prepares to castle."],["cxd5","White resolves the tension; after the recapture White has an isolated pawn on d4."],["Nxd5","The knight recaptures and blockades the square in front of the isolated pawn."],["Bd3","The bishop aims at h7, the base of White's kingside attack."],["Nc6","Black develops and hits d4."],["O-O","White castles and will continue with Re1 and Qe2."],["O-O","Black castles. The fight is about the isolated pawn: White wants activity and an attack, Black wants trades."]],"vars":[],"played":[1420,1419,359,419,416,97,90,30,24,20,27,16,35,32]},{"name":"Exchange Variation","summary":"A symmetrical structure where Black often plays a minority attack, the Queen's Gambit plan with colours reversed.","idea":["After 3.exd5 cxd5 White does not play c4 but builds a solid triangle with c3 and d4, and puts the bishops on d3 and f4. The structure is the Carlsbad of the Queen's Gambit Exchange with colours reversed: White has the kingside chances and the e5 outpost, Black has the queenside minority attack (...b5–b4) and the half-open c-file."],"at":4,"moves":[["exd5","White trades on d5."],["cxd5","Black recaptures with the c-pawn."],["Bd3","The bishop takes the b1–h7 diagonal and stops ...Bf5."],["Nc6","Black develops and hits d4."],["c3","White supports d4 with a pawn, building a solid chain."],["Nf6","Black develops the other knight."],["Bf4","The bishop develops outside the pawn chain, eyeing b8 and the e5 square."],["Bg4","Black puts the light-squared bishop outside the chain before playing ...e6."],["Qb3","The queen hits b7, which the bishop no longer guards, and adds pressure to d5."],["Qd7","The queen defends b7 along the seventh rank and supports d5. 7...Na5 is the other way."],["Nd2","The c3 pawn takes that square, so the queen's knight develops to d2; the other knight will go to f3."],["e6","Black completes the set-up and frees the f8 bishop for d6. Next comes ...Bd6 and, later, the minority attack with ...b5–b4."]],"vars":[],"played":[1420,1419,898,670,670,310,195,170,156,105,107,107]},{"name":"Karpov Variation: 4...Nd7","summary":"Black prepares ...Ngf6 so that a trade on f6 can be met by the knight, keeping the structure intact.","idea":["Instead of developing the bishop, Black plays ...Nd7 first so that ...Ngf6 can follow: if White trades on f6, Black recaptures with a knight and the pawn structure stays healthy. The game is slower and more solid than the Classical; White uses the time for an early Ng5 or a set-up with Bd3 and Qe2, and Black must be alert to sacrifices on e6 and f7."],"at":7,"moves":[["Nd7","Black prepares ...Ngf6, so that Nxf6+ can be met by ...Nxf6."],["Ng5","The knight jumps towards e6 and f7, a modern and aggressive try."],["Ngf6","Black develops; the knight on f6 also guards h7."],["Bd3","The bishop aims at Black's kingside."],["e6","Black opens the f8 bishop and takes the e6 square away from the knight on g5."],["N1f3","White develops the other knight, backing up the one on g5."],["Bd6","Black develops the bishop to its most active square."],["Qe2","The queen lines up on the e-file against the e6 pawn and the king behind it."],["h6","Now Black asks the knight on g5 to leave."],["Ne4","The knight returns to the centre and offers a trade."],["Nxe4","Black trades to ease the position."],["Qxe4","The queen recaptures on a central square. Black will play ...Nf6 or ...Qc7 and aim for ...c5, with a solid but slightly passive game."]],"vars":[],"played":[119,35,25,22,28,22,23,21,26,26,26,26]}],"played":[94897,10411,7698,7618,1082,1078,1071,520,478,478,325,324,274,195,174,174,180,180,179,157,127,115,127,104]},{"id":"scandinavian","name":"Scandinavian Defence","eco":"B01","side":"b","group":"semi-open","summary":"1...d5: Black challenges e4 at once and gets a clear, solid structure, at the cost of an early queen move.","idea":["Black hits e4 straight away with 1...d5. After 2.exd5 Qxd5 the queen comes out early and loses a tempo after Nc3, but in return Black knows exactly what kind of position is coming: pawns on c6 and e6, as in the Caro-Kann, with the light-squared bishop developed outside the chain to f5 or g4 before ...e6 closes it in. There are no weaknesses in Black's camp, and the centre pawn that White keeps on d4 is the only real asymmetry.","White has a lead in development and more space. The typical plans are Bd2, Qe2 and O-O-O, followed by the d4–d5 break against Black's king, or a kingside pawn advance with g4 chasing the bishop on f5; Ne5 is another standard idea. White must also watch for the tricks the queen on a5 allows, such as Nd5 uncovering an attack from the bishop on d2. Black aims to castle, bring the knight from b8 to d7, and free the position with ...c5 or ...e5, or with ...Nd5 trading pieces. If Black survives the opening, the endgame is often pleasant, because Black's structure is the healthier one.","Black can also play 2...Nf6, taking back on d5 with the knight instead of the queen, which leads to Grünfeld-like play against a broad White centre, or gambit the pawn for development in the Portuguese Variation with 3...Bg4."],"moves":[["e4","White takes the centre and opens lines for the queen and the king's bishop."],["d5","The Scandinavian: Black challenges e4 at once, before White can support it with d4 or Nc3."],["exd5","The principled reply: whatever recaptures on d5 can be hit, so White gains time."],["Qxd5","Black takes back with the queen at once. It is exposed in the centre, but it is hard to trap and the material is level."],["Nc3","Develops with tempo: the knight attacks the queen, so White gains a move."],["Qa5","The queen steps aside to a5, out of the way of White's pieces, and eyes the a5–e1 diagonal: once the d-pawn moves, the knight on c3 is pinned to the king."],["d4","White takes the centre with a pawn. The knight on c3 is now pinned, but Bd2 can break the pin later."],["Nf6","Develops the knight to its best square, covering d5 and e4, and gets ready for ...Bf5 or ...Bg4."],["Nf3","Develops, protects d4 and eyes e5, a square the knight may jump to later."],["c6","A key move: it gives the queen a retreat via c7 and takes b5 away from White's pieces, so Nb5 and Bb5+ are no longer possible."],["Bc4","The bishop takes the active a2–g8 diagonal, aimed at f7 and e6."],["Bf5","Black develops the light-squared bishop outside the pawn chain before playing ...e6, as in the Caro-Kann."],["Bd2","Breaks the pin on the knight and sets up a trick: whenever the knight leaves c3, the bishop on d2 attacks the queen on a5."],["e6","Opens the diagonal for the f8 bishop and completes a solid pawn chain on c6 and e6."],["Qe2","Clears d1 for long castling and protects the bishop on c4; the queen also lines up on the e-file against e6."],["Bb4","Develops with pressure on c3 and takes the sting out of Nd5: if the knight jumps, ...Bxd2+ removes the bishop that would hit the queen."],["O-O-O","White castles long. The rook on d1 stands behind the d-pawn, ready for d4–d5 while Black's king is still in the centre."],["Nbd7","Develops and covers e5 against Ne5; the knight can also go to b6 to hit the bishop on c4."],["a3","White asks the bishop to decide. It cannot drop back to a5, where the queen stands, so Black normally trades."],["Bxc3","Black gives up the bishop pair to remove the knight that supports d5 and e4."],["Bxc3","White recaptures with the bishop, which now attacks the queen on a5."],["Qc7","The queen retreats to c7, where it is safe and controls e5. Black will castle kingside and has a solid position; White has the bishop pair and hopes for d5 or Ne5."]],"vars":[{"name":"3...Qd6","summary":"The modern retreat, popular at the top level.","idea":["On d6 the queen is safe from the Bd2 and Nd5 tricks of the ...Qa5 lines, and it controls e5 and the b8–h2 diagonal. Black plays ...Nf6 and ...a6, then either ...Bg4 and ...Nc6 with queenside castling, or ...b5 and ...Bb7. White can hit the queen with Nb5 or Bf4 if Black is careless, which is why ...a6 (or ...c6) comes early."],"at":5,"moves":[["Qd6","The queen retreats to d6, where it controls e5 and the b8–h2 diagonal and cannot be caught by a discovered attack along the a5–e1 diagonal."],["d4","White takes the centre; the d4 pawn also takes e5 and c5 away from Black's pieces."],["Nf6","Develops to the natural square, covering d5 and e4."],["Nf3","Develops and supports d4; Nb5, hitting the queen, is now an idea."],["a6","Takes b5 away from the knight, so the queen is safe on d6, and prepares ...b5 or ...Bg4 with ...Nc6."]],"vars":[],"played":[188,174,156,135,29]},{"name":"The 8.Nd5 trick","summary":"White uses the bishop on d2 at once: Nd5 uncovers an attack on the queen.","idea":["Before Black has time for ...Bb4, White jumps into d5, uncovering an attack on the queen by the bishop on d2. The knight cannot be taken at once, because any capture on d5 leaves the queen to be taken on a5. Black retreats the queen and White trades knights. Black's position stays solid and the game is about equal, but it shows why the queen on a5 needs care."],"at":14,"moves":[["Nd5","The knight jumps into d5 and uncovers an attack on the queen by the bishop on d2."],["Qd8","Black must save the queen first; from d8 it guards the knight on f6."],["Nxf6+","White trades knights with check, removing one of the defenders of Black's kingside."],["Qxf6","The queen recaptures and Black's pawns stay intact. Black is solid; White has a little more space but no real targets."]],"vars":[],"played":[8,8,8,2]},{"name":"2...Nf6","summary":"Black takes back on d5 with the knight instead of the queen.","idea":["Black does not hurry to recapture and plays 2...Nf6, aiming to take back on d5 with the knight, which keeps the queen safe from Nc3. After 3.d4 Nxd5 4.c4 the knight is pushed to b6, and White has a broad centre that Black attacks from a distance with ...g6, ...Bg7, ...Nc6 and ...Bg4, much as in the Alekhine or the Grünfeld. Black can also gambit the pawn with 3...Bg4, the Portuguese Variation, aiming for rapid development instead."],"at":3,"moves":[["Nf6","Black attacks the d5 pawn with the knight, so that it can recapture without exposing the queen."],["d4","White takes the centre; holding the pawn with 3.c4 allows gambits such as 3...c6 or 3...e6."],["Nxd5","Black regains the pawn with a centralised knight."],["c4","White kicks the knight and builds a broad centre with pawns on c4 and d4."],["Nb6","The knight retreats to b6, out of reach of the pawns, where it keeps an eye on c4 and d5."],["Nf3","Develops and protects d4 against the coming fianchetto."],["g6","Black prepares ...Bg7, to strike at d4 from a distance, as in the Grünfeld."],["Nc3","Develops and covers d5 and e4."],["Bg7","The bishop bears down on d4. Black follows with ...O-O, ...Nc6 and ...Bg4, piling up on the d-pawn."]],"vars":[{"name":"Portuguese Variation","summary":"Black develops the bishop with an attack on the queen and gambits the d5 pawn.","idea":["Black develops the bishop to g4 before regaining the pawn, hitting the queen on d1 and provoking f3, which weakens White's kingside. After 4.f3 Bf5 5.Bb5+ Nbd7 6.c4, Black usually gives up the pawn with ...e6, getting quick development and pressure against White's loosened position."],"at":5,"moves":[["Bg4","Develops with an attack on the queen on d1; Black is in no hurry to win back d5."],["f3","White blocks the diagonal and kicks the bishop, at the cost of weakening the light squares around the king."],["Bf5","The bishop retreats to an active square, where it eyes c2 and b1."],["Bb5+","White checks, so that Black must block on d7, and keeps the extra pawn on d5 for now."],["Nbd7","Black blocks with the knight, which can later go to b6 to win back d5."],["c4","White holds the d5 pawn with c4. Black usually continues 6...e6, offering a pawn for rapid development and pressure against White's loosened king."]],"vars":[],"played":[26,10,6,1,1,4]}],"played":[166,92,63,37,22,21,18,12,12]}],"played":[94897,988,958,761,680,353,278,234,182,51,33,35,24,13,3,1,0,0,0,1,1,1]},{"id":"pirc","name":"Pirc Defence","eco":"B07–B09","side":"b","group":"semi-open","summary":"Black lets White build a big centre, fianchettoes the bishop on g7, then strikes with ...c5 or ...e5.","idea":["The Pirc is a hypermodern defence: Black does not occupy the centre with pawns but lets White build one, then attacks it. Black plays ...d6, ...Nf6, ...g6 and ...Bg7, castles, and waits for the right moment to hit d4 with ...c5 or ...e5. The bishop on g7 is Black's best piece, bearing down on the long diagonal towards d4 and the queenside.","White chooses how ambitious to be. The Austrian Attack (f4) builds the biggest possible centre and threatens e5 to drive the knight away; the 150 Attack (Be3, Qd2, Bh6) aims to trade off Black's fianchettoed bishop and attack the king with h4–h5; the Classical (Nf3, Be2, castling) keeps a solid space advantage.","Black is often a little cramped, but the position is full of counterplay. If White's centre advances too far it can be undermined; if it stands still, Black's pieces get active. When the centre closes after d5, Black usually plays on the queenside with ...b5, while White attacks on the kingside."],"moves":[["e4","Stakes a claim to the centre (d5 and f5) and opens lines for the queen and the king's bishop."],["d6","Prepares ...Nf6 and covers e5, so the knight cannot be kicked by e5 straight away."],["d4","White takes the full centre, which Black is willing to allow."],["Nf6","Black develops with an attack on e4."],["Nc3","White defends e4 with a piece."],["g6","Black prepares to fianchetto the bishop on g7, where it will press on d4 and the long diagonal."],["f4","The Austrian Attack: White builds the biggest centre possible and threatens e5 to drive the knight back."],["Bg7","Black completes the fianchetto."],["Nf3","White develops and supports both d4 and e5."],["O-O","Black castles first; 5...c5 strikes at the centre at once."],["Bd3","The bishop protects e4 and prepares castling; it also points at Black's kingside."],["Na6","The knight goes to a6, not c6, so the c-pawn stays free for ...c5. From a6 it can jump to b4 against the bishop on d3, or to c7."],["O-O","White castles."],["c5","Black hits d4, the base of White's centre."],["d5","White gains space and keeps the centre closed. The drawback is that d4 is no longer guarded, so Black's bishop on g7 has more scope later."],["Rb8","Black prepares ...b5 with the rook behind the pawn; the knight will come to c7 to support it as well. Black plays on the queenside, White on the kingside."]],"vars":[{"name":"Austrian Attack: 5...c5","summary":"Black strikes at the centre before castling and leads the game into sharp lines.","idea":["Black hits d4 at once, before White has completed development. After 6.dxc5 Qa5 Black pins the knight on c3 and regains the pawn, with good piece play; White often keeps more space. The sharp alternative 6.Bb5+ leads to a tactical melee in which White sacrifices a pawn to break open Black's king position."],"at":9,"moves":[["c5","Black hits the centre at once, counting on the pressure that the bishop on g7 will bring when the centre opens."],["dxc5","White takes the pawn, and Black must spend time winning it back."],["Qa5","The queen pins the knight on c3 to the king, so e4 is under threat, and gets ready to take on c5."],["Bd3","The bishop guards e4."],["Qxc5","Black regains the pawn; the queen on c5 also covers g1, so White cannot castle short yet."],["Qe2","The queen guards e4 again and makes room for Be3, which will hit Black's queen and block the diagonal."],["O-O","Black castles."],["Be3","The bishop hits the queen and closes the a7–g1 diagonal."],["Qa5","The queen returns to a5, pinning the knight on c3 again."],["O-O","White castles. White has more space; Black has a sound position with play against e4 and on the queenside."]],"vars":[{"name":"The sharp 6.Bb5+","summary":"White checks and then pushes e5–e6, breaking open the position around Black's king.","idea":["White first disrupts Black with a check, then pushes the e-pawn all the way to e6, sacrificing it to tear open the f7 square. Black's king ends up in the centre, but White has given up material. This is a theory-heavy line where both sides must know the moves."],"at":10,"moves":[["Bb5+","White checks first, to disrupt Black's development before pushing e5."],["Bd7","Black blocks the check."],["e5","White kicks the knight, which cannot retreat to d7 because the bishop is there."],["Ng4","The knight jumps forward, hitting e5 and e3, rather than going backwards."],["e6","A pawn sacrifice: the pawn attacks the bishop on d7 and the f7 pawn."],["Bxb5","Black takes the bishop on b5 before the pawn takes on d7."],["exf7+","The pawn captures on f7 with check, and Black's bishop on b5 is still hanging."],["Kd7","The main move: the king steps to d7 and is surprisingly hard to get at there. After 10.Nxb5 Qa5+ a very sharp position arises."]],"vars":[],"played":[27,27,22,22,20,1,1,1]}],"played":[39,8,8,4,4,4,3,3,3,3]},{"name":"150 Attack","summary":"White plays Be3, Qd2 and Bh6 to trade off Black's fianchettoed bishop, then attacks the king.","idea":["Named after the English club players graded around 150 who made it popular, this set-up is simple and dangerous. White plays Be3, Qd2, f3 and Bh6 to swap off the bishop on g7, then castles long and storms the kingside with g4 and h4. Black usually delays castling and gets counterplay on the queenside with ...c6, ...b5 and ...Bb7."],"at":6,"moves":[["Be3","The start of the 150 Attack: with Qd2 next, the bishop can go to h6 to trade off Black's fianchettoed bishop."],["Bg7","Black completes the fianchetto."],["Qd2","White prepares Bh6 to trade Black's best defender, and leaves room for long castling."],["c6","Black prepares ...b5 for queenside counterplay, where White's king is likely to go."],["f3","White supports e4 and prepares a pawn storm with g4 and h4."],["b5","Black gains queenside space and threatens ...b4 against the knight on c3."],["Nge2","With f3 taken by the pawn, the knight goes to e2, from where it can support c3 or go to g3."],["Nbd7","Black develops, preparing ...e5 or ...c5 against the centre."],["Bh6","The key idea: White offers to trade Black's fianchettoed bishop."],["Bxh6","Black takes, since White would take on g7 anyway."],["Qxh6","From h6 the queen covers f8, so Black cannot castle short for now."],["Bb7","Black develops and prepares ...b4 and ...c5 to open the long diagonal; Black's king often stays in the centre or goes to the queenside."]],"vars":[],"played":[162,46,60,30,4,10,0,0,0,0,0,0]},{"name":"Classical System: 4.Nf3","summary":"White develops quietly and castles, keeping a solid centre and a small space edge.","idea":["White does not overextend but simply develops with Nf3, Be2 and castling. Black pressures d4 with ...Bg4 and ...Nc6, then breaks with ...e5. After d5 the position often resembles a King's Indian: Black plays for ...f5 on the kingside, White for c4 and expansion on the queenside."],"at":6,"moves":[["Nf3","The Classical: White develops quietly and keeps the centre solid."],["Bg7","Black completes the fianchetto."],["Be2","White prepares to castle."],["O-O","Black castles."],["O-O","White castles too."],["Bg4","The bishop eyes the knight on f3, a defender of d4."],["Be3","White defends d4."],["Nc6","Black piles up on d4."],["Qd2","The queen guards d4 along the d-file and connects the rooks."],["e5","Black strikes in the centre."],["d5","White gains space and attacks the knight on c6."],["Ne7","The knight retreats; Black plans ...Nd7 and ...f5, as in a King's Indian."]],"vars":[],"played":[143,189,150,190,185,18,15,13,1,0,0,0]},{"name":"Modern Defence: 1...g6","summary":"Black fianchettoes first and keeps the knight on g8, for even more flexibility.","idea":["Black delays ...Nf6, so White's e4 pawn is not attacked and White cannot gain time by kicking the knight with e5. Black keeps options: ...d6 and ...a6 with ...b5, or ...c6 and ...d5. The idea is the same as the Pirc, with an even more flexible set-up and a strong bishop on g7."],"at":1,"moves":[["g6","Black prepares the fianchetto and leaves the knight on g8 for now."],["d4","White takes the full centre."],["Bg7","The bishop eyes d4 on the long diagonal."],["Nc3","White develops and guards e4."],["d6","Black covers e5 and opens the c8 bishop's diagonal."],["Be3","White sets up the same Be3 and Qd2 attack as in the 150 Attack."],["a6","Black prepares ...b5 for queenside space and counterplay."],["Qd2","White prepares long castling and Bh6."],["b5","Black gains queenside space and plans ...Bb7, ...Nd7 and ...c5."]],"vars":[],"played":[1563,1509,1711,995,628,446,323,111,95]}],"played":[94897,2067,1989,2116,1932,550,112,109,139,95,46,16,15,15,15,3]},{"id":"alekhine","name":"Alekhine's Defence","eco":"B02–B05","side":"b","group":"semi-open","summary":"1...Nf6 provokes White's pawns forward, then Black undermines the over-extended centre.","idea":["Black attacks e4 with the knight on move one, inviting White to chase it with e5, c4 and d4. This is a provocation: Alekhine's idea is that White's advanced pawns become targets. Black then strikes back with ...d6, ...Nc6, ...Bg4 or ...Bf5, aiming to undermine e5 and d4 before White can consolidate.","White chooses how far to advance. The Four Pawns Attack (c4, d4, e5 and f4) builds a huge centre that is either crushing or crumbling; the Exchange line gives up e5 for a quieter space edge; the Modern Variation (4.Nf3) supports e5 with pieces and avoids overextension, and is the most popular.","Typical themes: the e5 pawn is White's spearhead and Black's target; Black's knights often go to b6 and c6 and the bishop to g4 or f5 to remove defenders of the centre. If the centre closes with ...d5, the structure looks like a French, but with Black's light-squared bishop outside the chain."],"moves":[["e4","Stakes a claim to the centre (d5 and f5) and opens lines for the queen and the king's bishop."],["Nf6","Black attacks e4 at once, inviting the pawn to chase the knight."],["e5","White accepts the challenge and gains space with tempo."],["Nd5","The knight goes to a central square. It can be harassed there, but every pawn move White makes is one more target later."],["d4","White builds the centre and supports e5."],["d6","Black hits e5 at once, before White can consolidate it."],["Nf3","The Modern Variation: White supports e5 with a piece and does not overextend with more pawn moves."],["Bg4","The bishop pins the knight on f3, a key defender of d4 and e5, against the queen."],["Be2","White breaks the pin."],["e6","Black opens the f8 bishop and supports the knight on d5."],["O-O","White castles."],["Be7","A modest but solid development; Black is ready to castle."],["h3","White asks the bishop to decide: take on f3 or retreat."],["Bh5","The bishop keeps its eye on the knight on f3."],["c4","White gains space and kicks the knight."],["Nb6","The knight retreats to b6, from where it presses on c4."],["Nc3","White develops and covers d5 and e4."],["O-O","Black castles."],["Be3","White develops the last minor piece and protects d4."],["d5","Black closes the centre and attacks c4. The structure is like a French, but Black's light-squared bishop is outside the chain."],["c5","White pushes with tempo on the knight and gains space on the queenside."],["Bxf3","Black gives up the bishop first so that White's bishop on e2 is drawn away from guarding c4."],["Bxf3","Recapturing with the g-pawn would wreck White's kingside, so the bishop takes, and c4 is left unguarded."],["Nc4","The knight lands on c4, hitting the bishop on e3 and the b2 pawn. After 13.b3 Nxe3 14.fxe3 b6 Black chips away at White's queenside, with a solid game."]],"vars":[{"name":"Four Pawns Attack","summary":"White builds a massive centre with c4, d4, e5 and f4; Black must undermine it at once.","idea":["White chases the knight to b6 and puts four pawns in the centre. If the centre holds, Black is squeezed; if Black can attack it with ...dxe5, ...Nc6, ...Bf5 and ...e6, the pawns on d4 and e5 become targets and White's king is exposed. White's usual way to keep the initiative is the break d5, opening lines before Black's pressure grows."],"at":6,"moves":[["c4","White kicks the knight with tempo."],["Nb6","The knight retreats to b6, from where it presses on c4."],["f4","The Four Pawns Attack: White supports e5 with yet another pawn and builds a huge centre."],["dxe5","Black releases the tension, so that the f-pawn has to recapture and d4 is left with less support."],["fxe5","White recaptures and keeps the big centre."],["Nc6","Black develops with an attack on d4 and adds pressure to e5."],["Be3","White defends d4."],["Bf5","Black develops the bishop outside the pawn chain before playing ...e6."],["Nc3","White develops."],["e6","Black completes the set-up and opens the f8 bishop."],["Nf3","The knight defends d4 and e5."],["Be7","Black prepares to castle. White's critical try is 10.d5, breaking open the position before the pressure on d4 and e5 grows."]],"vars":[{"name":"Exchange Variation","summary":"White trades off e5 and keeps a quieter, lasting space edge with c4 and d4.","idea":["Instead of f4, White trades the e5 pawn. White keeps pawns on c4 and d4 and a space advantage; Black has a solid position with pressure on d4 from the bishop on g7 and the knight on c6. White supports c4 with b3 and the rook on c1 so that Black's knights never get to use c4; Black aims for ...e5 or ...d5 to free the game."],"at":8,"moves":[["exd6","White trades the e5 pawn, giving up the big centre for a quieter space edge."],["cxd6","Black recaptures towards the centre, keeping control of e5 and c5; 5...exd6 is the other way."],["Nc3","White develops."],["g6","Black prepares to fianchetto the bishop against d4."],["Be3","White defends d4 in advance."],["Bg7","The bishop presses on d4."],["Rc1","The rook goes to the c-file, where it protects the knight on c3 and supports c4."],["O-O","Black castles."],["b3","White shores up c4. White has a small but lasting space edge; Black plays for ...e5 or ...d5."]],"vars":[],"played":[129,80,67,66,47,49,41,41,34]}],"played":[203,203,126,83,83,41,41,42,43,44,37,26]},{"name":"Modern: 4...g6","summary":"Black fianchettoes the bishop against d4 and keeps the tension in the centre.","idea":["Black puts the bishop on g7, where it aims at d4 and, once the e5 pawn goes, the whole long diagonal. White develops with Bc4–b3, castles and keeps e5 supported; Black uses ...Nc6, ...a5 and sometimes ...dxe5 and ...Nd4 to undermine the centre."],"at":7,"moves":[["g6","Black prepares to fianchetto the bishop."],["Bc4","The bishop hits the knight on d5."],["Nb6","The knight retreats to b6 with an attack on the bishop."],["Bb3","The bishop stays on the a2–g8 diagonal, aimed at f7."],["Bg7","Black completes the fianchetto."],["Qe2","The queen guards e5 along the e-file."],["Nc6","Black develops with pressure on d4 and e5."],["O-O","White castles."],["O-O","Black castles."],["h3","White stops ...Bg4, which would remove the knight on f3, a key defender of e5 and d4."],["a5","Black threatens ...a4, which would drive the bishop from b3."],["a4","White halts the pawn, but leaves a hole on b4 for Black's knight."]],"vars":[],"played":[65,51,33,33,30,7,3,1,1,0,0,0]},{"name":"Modern: 4...dxe5","summary":"Black trades on e5 and builds a compact, Caro-Kann-like position.","idea":["Black takes on e5 at once and the knight recaptures. Black then supports the knight on d5 with ...c6, develops the bishop to f5 and challenges the knight on e5 with ...Nd7. The result is a very solid position with no weaknesses; White keeps a small space advantage from the d4 pawn."],"at":7,"moves":[["dxe5","Black trades in the centre."],["Nxe5","The knight recaptures and stands well on e5."],["c6","Black supports the knight on d5 and keeps the position compact; ...Bf5 and ...Nd7 come next."],["Be2","White prepares to castle."],["Bf5","Black develops the bishop outside the pawn chain."],["O-O","White castles."],["Nd7","Black challenges the strong knight on e5."],["Nf3","White avoids the trade, keeping more pieces on the board while having more space."],["e6","Black has a solid position with no weaknesses. White usually continues 9.c4, kicking the knight."]],"vars":[],"played":[140,139,114,61,50,47,47,37,37]}],"played":[94897,730,668,640,530,517,296,55,49,31,17,13,10,10,11,11,15,15,15,14,14,14,1,1]},{"id":"queens-gambit-declined","name":"Queen's Gambit Declined","eco":"D30–D69","side":"b","group":"closed","summary":"Black holds d5 with ...e6: a rock-solid classical defence, built on piece play and well-timed freeing breaks.","idea":["After 1.d4 d5 2.c4 White offers the c-pawn to pull Black's d-pawn away from the centre. With 2...e6 Black refuses and simply keeps a pawn on d5, backed up by the e-pawn. The price is that the bishop on c8 is shut in behind its own pawns; much of QGD strategy for Black is about solving that \"problem bishop\", either with ...b6 and ...Bb7 (or ...Be6), or by freeing the position with ...dxc4 followed by ...c5 or ...e5.","White develops naturally (Nc3, Bg5, e3, Nf3) and keeps up the pressure on d5, often aiming for a lasting edge in space or structure. Black castles early, trades a pair or two of minor pieces to ease the cramp (the knight jump ...Ne4 and the bishop trade on e7 are typical), and then strikes at White's centre with ...c5. That break frequently leaves Black with \"hanging pawns\" on c5 and d5, or an isolated d-pawn: active, but also a target.","When White exchanges on d5 early, the Carlsbad structure appears (White pawns on d4 and e3 against Black's on d5 and c6). Then White's classic plan is the minority attack: the a- and b-pawns advance (b4–b5) to create a weak pawn on c6 or d5, while Black seeks counterplay on the kingside or with a knight landing on e4."],"moves":[["d4","White takes the centre; unlike 1.e4, the pawn is already protected by the queen."],["d5","Black claims an equal share of the centre and stops White from following up with e4."],["c4","The Queen's Gambit. White attacks d5 from the side, offering the c-pawn to lure Black's centre pawn away."],["e6","Black declines and holds d5 with a pawn. Solid, but the bishop on c8 is now locked in behind e6."],["Nc3","Adds a second attacker on d5 and keeps an eye on e4."],["Nf6","Develops to the best square and defends d5 a second time."],["Bg5","Pins the knight to the queen, so it can no longer defend d5 with full force."],["Be7","Breaks the pin calmly and clears the way to castle."],["e3","Supports d4 and opens the diagonal for the bishop on f1. White builds the centre before committing the king's knight."],["O-O","Black's king is safe early: the QGD is about solidity first, counterplay later."],["Nf3","Develops towards the centre, guarding d4 and covering e5 so Black cannot easily free the game with ...e5."],["h6","Puts the question to the bishop. Black wants to know whether White will trade it or keep the pin, and the king gets a little air on h7."],["Bh4","White keeps the pin; giving up the bishop for the knight would hand Black the bishop pair."],["b6","The Tartakower Defence. Black prepares to develop the problem bishop (on b7 or e6) and to support the freeing break ...c5."],["cxd5","White releases the tension at once. The aim is to trade pieces and then target whatever pawns Black is left with in the centre and on the queenside."],["Nxd5","Black recaptures with the knight, offering trades that ease the cramp. Now the bishop on h4 attacks e7, which the queen defends."],["Bxe7","White trades bishops; after the knight jump to d5 there is nothing better for the bishop on h4."],["Qxe7","The queen recaptures and stands well on e7, watching the a3–f8 diagonal and the e-file."],["Nxd5","A second pair of minor pieces goes, and Black must recapture with a pawn."],["exd5","The pawn takes back, restoring a pawn on d5 and, crucially, opening the c8–h3 diagonal for the problem bishop."],["Rc1","The rook takes the open c-file, pointing at c7 and at the c5 square where Black wants to put a pawn."],["Be6","The bishop develops actively, protects d5 and backs up the coming ...c5."],["Qa4","The queen swings to the queenside, eyeing a7 and getting ready to hit c5 from a3 as soon as Black plays ...c5."],["c5","Black strikes at the centre and frees the position. After dxc5 bxc5 Black will have hanging pawns on c5 and d5: lively piece play in return for a possible target."]],"vars":[{"ref":"queens-gambit-accepted","at":3,"name":"Queen's Gambit Accepted","summary":"Black takes the pawn with 2...dxc4 and plays for quick development and ...c5."},{"ref":"slav","at":3,"name":"Slav Defence","summary":"Black holds d5 with 2...c6, keeping the c8 bishop's diagonal open."},{"name":"Tartakower: Fischer's plan","summary":"The famous treatment from Fischer–Spassky, game 6, 1972: pressure on the hanging pawns.","idea":["White piles up on c5, forces Black to accept hanging pawns on c5 and d5, and then sets about the light squares around them. Fischer won a model game with this plan in 1972: he traded the bishop on e6, which held the pawns together, and then broke with e4. Black's pawns are a strength while they control the centre and support active pieces, but once they are fixed or blockaded they become targets."],"at":24,"moves":[["Qa3","The queen attacks c5 along the a3–f8 diagonal, where it also lines up with Black's queen on e7 behind the pawn. Together with the rook on c1 and the pawn on d4 that is three attackers."],["Rc8","The rook adds a defender, so c5 is held by the rook, the queen and the pawn on b6."],["Bb5","The bishop takes away a6, c6 and d7, all the squares the knight on b8 wants, so Black still cannot finish developing."],["a6","Black kicks the bishop at once."],["dxc5","White ignores the attack on the bishop and takes, so Black must recapture and accept hanging pawns."],["bxc5","The hanging pawns on c5 and d5 control the centre, but neither has a neighbouring pawn to defend it."],["O-O","White castles and still leaves the bishop where it is: 16...axb5 17.Qxa8 would win the rook, because the knight on b8 blocks the c8 rook's defence."],["Ra7","The rook steps off a8 and is defended by the queen along the seventh rank, so ...axb5 is now a real threat."],["Be2","The bishop retreats, its job of delaying Black's development done."],["Nd7","At last the knight comes out, defending c5 and freeing the back rank."],["Nd4","The knight attacks the bishop on e6, the piece that guards the light squares around the hanging pawns. After Nxe6 fxe6 White can break with e4 and open the position against the pawns and Black's king."]],"vars":[],"played":[7,8,2,0,0,0,0,0,0,0,0]},{"name":"Exchange Variation and the minority attack","summary":"White fixes the Carlsbad structure and later attacks it with the queenside pawns.","idea":["By exchanging on d5 early, White gives Black's problem bishop an open diagonal but fixes the pawn structure: White has d4 and e3, Black has d5 and c6. White's classic plan is the minority attack: rook to b1, then b4 and b5, to swap off the c6 pawn and leave Black with a weak pawn on d5 or c6. Black regroups the knight from d7 to f8 and g6 or e6, gets the bishop to g4 or e6, and looks for kingside play or a knight landing on e4."],"at":6,"moves":[["cxd5","White exchanges now, before Black can choose a set-up, and fixes the pawn structure."],["exd5","Black recaptures with the pawn, keeping a pawn in the centre and opening the c8 bishop's diagonal."],["Bg5","The bishop pins the knight to the queen and keeps it from going to e4 too easily."],["Be7","Breaks the pin and prepares to castle."],["e3","Supports d4 and opens the f1 bishop's diagonal towards d3."],["c6","Completes the Carlsbad structure: d5 is supported by a pawn, and the queen can use the d8–a5 diagonal."],["Bd3","The bishop aims at h7 and covers f5, so Black's light-squared bishop cannot come to its best square without being exchanged."],["Nbd7","The knight develops, ready to regroup via f8 to g6 or e6."],["Qc2","The queen adds pressure on the b1–h7 diagonal and guards f5 again, keeping Black's bishop out."],["O-O","Black castles; the king's side is solid with pawns on f7, g7 and h7."],["Nf3","The knight develops to its natural square, covering e5 and keeping the option of Ne5."],["Re8","The rook goes to the e-file and frees f8 for the knight's regrouping."],["O-O","White castles short: the plan is now Rab1 followed by b4 and b5, the minority attack."],["Nf8","The knight heads for g6 or e6, and the c8 bishop can finally come out to g4 or e6. A slow, strategic battle follows."]],"vars":[{"name":"The central plan with Nge2","summary":"Instead of the minority attack, White prepares f3 and e4.","idea":["With the king's knight on e2 rather than f3, White's f-pawn is free to go to f3, supporting the central break e4. It is a more ambitious plan than the minority attack: if White achieves e4 under good conditions, the space and the extra central control tell. Black must keep enough control of e4 and be ready to counter in the centre or on the queenside."],"at":16,"moves":[["Nge2","The knight goes to e2 so that the f-pawn is not blocked. From e2 it can also come to g3 or f4."],["Re8","The usual regrouping: the rook goes to e8, freeing f8 for the knight and pressing along the e-file."],["O-O","White castles, keeping the option of f3 and e4."],["Nf8","The knight heads for e6 or g6 and opens the c8 bishop's path."],["f3","The point of Nge2: f3 takes e4 away from Black's pieces and prepares the e4 break, which would give White a mobile centre."]],"vars":[],"played":[37,53,59,69,27]}],"played":[3236,3013,2948,836,834,193,492,277,118,46,54,97,79,59]},{"name":"Lasker Defence","summary":"Black frees the position by trading two pairs of minor pieces at once.","idea":["Black's main difficulty in the QGD is lack of space, and Lasker's remedy is simple: trade pieces. The knight jump to e4 forces an exchange of bishops and then of knights, after which Black takes on c4 and has a solid, if slightly passive, position. The remaining task is to develop the c8 bishop, usually with ...b6 and ...Bb7, and free the game with ...c5 or ...e5. White keeps a small lead in development; Black is very hard to beat."],"at":13,"moves":[["Ne4","The knight jumps to e4, hitting the knight on c3 and uncovering the attack on e7, so the bishops will be traded."],["Bxe7","White trades; the bishop had nowhere better to go."],["Qxe7","The queen recaptures, guarding e4 and keeping the knight there for now."],["Rc1","The rook gets ready to recapture on c3, so that after ...Nxc3 White keeps the pawn structure intact."],["c6","Supports d5 solidly before Black exchanges on c3 and takes on c4."],["Be2","A modest developing move; White will have to spend a tempo recapturing on c4 anyway."],["Nxc3","The second pair of minor pieces comes off, easing Black's cramp."],["Rxc3","The rook recaptures and stands actively on the third rank."],["dxc4","Black gives up the d5 point to gain a tempo: the bishop on e2 has to move again to recapture."],["Bxc4","White wins the pawn back and has a free, comfortable game."],["Nd7","The knight develops and supports the freeing breaks ...e5 and ...c5."],["O-O","White castles. The c-file and a small lead in development are White's assets."],["b6","Black prepares ...Bb7 and ...c5, solving the last problem: the light-squared bishop."]],"vars":[],"played":[56,53,52,33,25,1,0,0,0,0,12,9,10]},{"name":"Tarrasch Defence","summary":"Black strikes at d4 at once and accepts an isolated d-pawn for free piece play.","idea":["Tarrasch's idea is the opposite of the passive defences: Black hits the centre immediately and is willing to end up with an isolated pawn on d5. In return the pieces get open lines and good squares (e4, the c- and e-files). White's best set-up is the fianchetto with g3 and Bg2, so the bishop presses on d5 from afar; White then blockades the pawn with a knight on d4 and tries to win it or exploit the weak squares around it. Black needs active play: if the pieces are traded off, the isolated pawn becomes a long-term weakness."],"at":5,"moves":[["c5","Black hits d4 straight away, accepting that an isolated d-pawn may follow."],["cxd5","White clarifies the centre, heading for the isolated pawn."],["exd5","Black recaptures with the e-pawn, opening the c8 bishop's diagonal."],["Nf3","Develops, covers e5 and adds a defender to d4."],["Nc6","More pressure on d4; the knight is ready to go to e5 or b4 when lines open."],["g3","The best set-up against the isolated pawn: the bishop will go to g2 and press on d5."],["Nf6","Develops and protects d5 again."],["Bg2","The bishop on the long diagonal aims at d5, the pawn Black must keep defending."],["Be7","A modest but safe square: Black castles quickly and keeps the king's side solid."],["O-O","White castles and is ready to resolve the centre."],["O-O","Black castles too."],["Bg5","The bishop attacks the knight on f6, one of d5's main defenders."],["cxd4","Black resolves the tension: the d5 pawn is now isolated, and the fight over it begins."],["Nxd4","The knight takes back and sits on d4, the ideal blockading square right in front of the isolated pawn. Play usually continues ...h6 and ...Re8, with active pieces for Black against the static weakness."]],"vars":[],"played":[501,394,265,265,199,96,98,215,67,64,120,33,4,4]},{"name":"Ragozin Defence","summary":"Black pins the knight with ...Bb4, mixing the QGD with Nimzo-Indian ideas.","idea":["After 4.Nf3 Black develops the bishop to b4 instead of e7, pinning the knight on c3 just as in the Nimzo-Indian. Black is ready to give up the bishop for that knight and in return gets quick development and pressure on White's centre. A common pattern is ...h6 to make White trade on f6, which hands Black the bishop pair, and then ...dxc4 with ...c5 to open the position for the bishops."],"at":6,"moves":[["Nf3","White develops the king's knight first, keeping the bishop's options open."],["Bb4","The Ragozin: the bishop pins the knight on c3 to the king, putting pressure on e4 and d5 indirectly."],["Bg5","White develops with a pin of its own, on the knight on f6."],["h6","Black asks the bishop to decide at once."],["Bxf6","White gives up the bishop pair to avoid ...g5 and to keep Black's structure fixed."],["Qxf6","The queen recaptures and stands actively on f6. Black has the two bishops."],["e3","Supports d4 and opens the way for the f1 bishop."],["O-O","Black castles, ready to open the centre."],["Rc1","The rook backs up the pinned knight on c3 and takes the c-file, which may open soon."],["dxc4","Black takes on c4 so that White's bishop has to spend a move recapturing."],["Bxc4","The bishop recaptures and aims at e6 and f7."],["c5","The thematic break: Black opens the centre, where the bishop pair and the queen on f6 will feel at home."]],"vars":[],"played":[671,2115,721,552,522,520,307,280,241,144,144,141]}],"played":[69153,19081,14220,7494,3955,2766,584,376,308,139,111,155,102,170,44,40,37,35,29,29,16,15,7,7]},{"id":"queens-gambit-accepted","name":"Queen's Gambit Accepted","eco":"D20–D29","side":"b","group":"closed","summary":"Black takes on c4, gives the pawn back, and uses the time for fast development and the ...c5 break.","idea":["With 2...dxc4 Black gives up the centre for a while, but not to keep the pawn: White always wins it back. The point is time. While White spends a move recapturing on c4, Black develops quickly with ...Nf6, ...e6 and ...c5, and the bishop on c8 is not shut in as in the Queen's Gambit Declined.","The key move is ...c5, hitting White's d4 pawn. In the main lines the centre is often liquidated and White is left with an isolated d-pawn on d4. White then plays for activity: pieces on good squares, pressure on the kingside, and the d4–d5 break. Black blockades on d5, trades pieces and aims for an endgame where the isolated pawn is weak. Black also often gains queenside space with ...a6 and ...b5, which is why White frequently answers with a4.","White can also try to punish the early capture with 3.e4, taking the whole centre at once. Black must then hit back immediately, with ...e5 or ...Nf6, before the centre rolls forward."],"moves":[["d4","White takes the centre; the pawn is protected by the queen."],["d5","Black claims an equal share of the centre."],["c4","The Queen's Gambit: White offers the c-pawn to deflect the d5 pawn."],["dxc4","Black accepts. Not to keep the pawn, but to gain time: White must spend moves getting it back, and Black's c8 bishop stays free."],["Nf3","The knight controls e5, stopping the freeing ...e5, and gets ready for e3 and Bxc4."],["Nf6","Develops and controls e4, so White cannot easily build a full centre with e4."],["e3","Opens the f1 bishop's diagonal, so it can recapture on c4 next."],["e6","Black opens the way for the f8 bishop and prepares to castle; the bishop on c8 can still come out later via b7."],["Bxc4","White wins the pawn back. The bishop on c4 eyes e6 and the a2–g8 diagonal."],["c5","The heart of the QGA: Black strikes at d4 and challenges White's last central pawn."],["O-O","White castles, keeping the tension; taking on c5 would trade off the centre and give Black easy play."],["a6","Prepares ...b5, gaining queenside space with tempo on the bishop and making room for ...Bb7."],["a4","Stops ...b5 for good, at the cost of giving up control of the b4 square."],["Nc6","Develops with more pressure on d4. The knight can use the b4 square that 7.a4 left behind."],["Qe2","The queen protects the bishop on c4 and frees d1 for the rook, getting ready for a central fight."],["cxd4","Black resolves the tension. After the recapture White will have an isolated d-pawn."],["Rd1","Before recapturing, the rook takes the d-file. It attacks d4, faces Black's queen, and after exd4 it will stand behind White's pawn to support its advance."],["Be7","Black develops calmly and prepares to castle; there is no point in trying to hold the pawn on d4."],["exd4","White recaptures and has the isolated pawn on d4: more space and active pieces, but a long-term weakness."],["O-O","Black castles. The plan is clear: blockade d5, trade pieces, and attack d4."],["Nc3","The knight develops, supports the d4–d5 break and eyes the b5 and e4 squares."],["Nd5","The classic blockade: the knight on d5 sits right in front of the isolated pawn and cannot be driven away by a pawn. A typical isolated-pawn middlegame follows."]],"vars":[{"name":"Central Variation","summary":"White grabs the whole centre at once, and Black must strike back immediately.","idea":["With 3.e4 White uses the moment Black's d-pawn has left the centre to occupy it completely. Black cannot allow the e- and d-pawns to settle, so the best answers hit them at once: 3...e5 opens the position and fights for d4, while 3...Nf6 provokes e5 and then attacks the advanced pawn. White has a lot of space and quick development; Black gets open lines and targets."],"at":4,"moves":[["e4","White takes the full centre, using the fact that Black's d-pawn has left it."],["e5","Black strikes back at once. If 4.dxe5 Qxd1+ 5.Kxd1 White's king is displaced and the queens are off."],["Nf3","White defends d4 and attacks e5 at the same time."],["exd4","Black takes on d4 and the centre is broken up."],["Bxc4","White first wins back the c4 pawn, and the bishop now aims at f7."],["Nc6","The knight defends the extra pawn on d4."],["O-O","White castles and plays for development; the d4 pawn can be won back later or kept as a nuisance."],["Be6","Black offers to trade off White's best attacking piece, the bishop on c4."],["Bxe6","White trades, doubling Black's e-pawns."],["fxe6","The recapture opens the f-file for Black's rook, and the e6 pawn covers d5 and f5."],["Qb3","The queen hits both weak points: the pawn on e6 and the pawn on b7."],["Qd7","Black protects e6 and lets b7 go. After 9.Qxb7 Rb8 10.Qa6 Nf6 Black has active pieces and the d4 pawn for the material."]],"vars":[{"name":"3...Nf6: attacking the e-pawn","summary":"Black provokes e5 and then targets the overextended centre.","idea":["Instead of meeting e4 with a pawn, Black attacks it with the knight. After e5 the knight jumps to d5 and b6, gaining time on White's bishop. White has a lot of space, but the advanced pawn on e5 and the pawn on d4 can become targets for ...Nc6, ...Bg4 and ...e6 with ...c5 or ...f6."],"at":5,"moves":[["Nf6","The knight attacks e4 at once, before White can support it with Nc3 or f3."],["e5","White gains space with tempo on the knight."],["Nd5","The knight goes to the strong d5 square in the middle of the board."],["Bxc4","White wins back the pawn and attacks the knight."],["Nb6","The knight retreats with tempo, hitting the bishop on c4."],["Bd3","The bishop drops back to aim at h7. White has space; Black will attack d4 and e5 with ...Nc6 and ...Bg4."]],"vars":[],"played":[138,130,130,130,68,24]}],"played":[416,136,132,48,47,32,31,30,11,11,11,10]},{"name":"Classical Main Line with 7.Qe2","summary":"White allows ...b5 and prepares a central break with Rd1 and e4 or d5.","idea":["Instead of stopping ...b5 with a4, White lets Black expand on the queenside. Black gets space and a fine diagonal for the bishop on b7, but falls a little behind in development. White puts the rook on d1 opposite Black's queen and prepares central breaks (e4 or d5), which can be very dangerous while Black's king is still in the centre."],"at":12,"moves":[["Qe2","The queen defends the bishop and makes room for the rook on d1."],["b5","Black gains queenside space with tempo on the bishop."],["Bb3","The bishop keeps its place on the a2–g8 diagonal, eyeing e6."],["Bb7","The bishop goes to the long diagonal, aiming at f3, g2 and the e4 square."],["Rd1","The rook faces Black's queen on the d-file, preparing the central break d5."],["Nbd7","The knight develops behind the pawns; on c6 it would block the bishop on b7."],["Nc3","The last piece comes out, supporting both e4 and d5. Black must watch for sacrificial breaks in the centre."]],"vars":[],"played":[38,26,5,6,5,5,0]},{"name":"7.dxc5: the queenless middlegame","summary":"White trades queens and plays for a small, safe edge in the endgame.","idea":["White trades on c5 and offers the queen exchange. The pawn structure becomes symmetrical, and White hopes that the extra tempo and slightly better development will give a long-lasting edge. Black's king is fine in the centre without queens, and with accurate play Black equalises; but it is a position where only White can win."],"at":12,"moves":[["dxc5","White gives up the centre pawn to trade queens."],["Qxd1","Black accepts the queen trade, which removes all attacking chances against the king."],["Rxd1","The rook recaptures and takes the open d-file."],["Bxc5","Black regains the pawn. The king will stay on e8 or e7, close to the centre for the endgame."]],"vars":[],"played":[180,40,40,40]}],"played":[69153,19081,14220,1795,1024,868,1093,849,900,714,712,458,36,38,18,16,16,15,15,15,17,3]},{"id":"slav","name":"Slav Defence","eco":"D10–D19","side":"b","group":"closed","summary":"Black supports d5 with ...c6, keeping the light-squared bishop free to come out to f5.","idea":["The Slav solves the main problem of the Queen's Gambit Declined in a simple way: Black protects d5 with the c-pawn instead of the e-pawn, so the bishop on c8 can come out to f5 or g4 before ...e6 closes its diagonal. The result is a solid structure (pawns on c6, d5 and e6) with all of Black's pieces active.","In the main line Black takes on c4 and threatens to hold the pawn with ...b5. White stops that with a4, which costs some control of the b4 square, and Black uses it at once for the bishop. White then wins back the pawn and plays for e4, building a big centre; Black puts pressure on that centre with the bishop on f5 or g6, the pin ...Bb4 and the knights, and aims for breaks with ...c5 or ...e5.","White can avoid all this with the Exchange Variation (3.cxd5), which gives a symmetrical, fairly quiet position, or with a sharp attempt to punish the bishop on f5 directly, such as 6.Ne5 with f3 and e4."],"moves":[["d4","White takes the centre; the pawn is protected by the queen."],["d5","Black claims an equal share of the centre."],["c4","The Queen's Gambit: White attacks d5 from the side."],["c6","The Slav. Black supports d5 with the c-pawn, so the bishop on c8 keeps its diagonal open."],["Nf3","Develops and covers e5, so Black cannot play ...e5 easily."],["Nf6","Develops and defends d5 again."],["Nc3","Adds pressure on d5 and prepares e4. Now Black chooses between ...dxc4 (the main line), ...e6 (the Semi-Slav) and ...a6."],["dxc4","Black takes now: with c6 played, the pawn can be held with ...b5 if White plays slowly."],["a4","Stops ...b5 for good. The cost is the b4 square, which White's pawns can no longer control."],["Bf5","The point of the Slav: the bishop comes out before ...e6 and covers e4, making White's e4 harder to achieve."],["e3","White opens the f1 bishop's diagonal so it can recapture on c4."],["e6","Black opens the f8 bishop and builds the solid pawn chain c6–e6 with the c8 bishop already outside it."],["Bxc4","White regains the pawn."],["Bb4","The bishop uses the b4 hole that a4 left behind and pins the knight on c3 to the king, making e4 harder."],["O-O","White castles, ending the pin, and prepares e4."],["Nbd7","Develops, covers e5 and supports later breaks with ...e5 or ...c5."],["Qe2","Prepares e4: once the e-pawn advances, the queen will support it from behind."],["O-O","Black castles, completing development."],["e4","White takes the centre and gains time on the bishop on f5."],["Bg6","The bishop retreats but stays on the b1–h7 diagonal, still eyeing e4."],["Bd3","Defends e4 a second time and blunts the bishop on g6."],["Bh5","Black pins the knight on f3 to the queen on e2, taking a defender away from d4 and e5."],["e5","White gains space and kicks the knight from f6."],["Nd5","The knight lands on a superb square that no pawn can attack: White's c-pawn is gone and the e-pawn has moved past it. A typical continuation is 13.Nxd5 cxd5 14.Qe3, unpinning, with a complex middlegame: White's kingside space against Black's solid structure."]],"vars":[{"ref":"semi-slav","at":7,"name":"Semi-Slav Defence","summary":"Black plays 4...e6, combining the Slav with the Queen's Gambit Declined."},{"name":"Exchange Variation","summary":"White exchanges on d5 for a symmetrical, quiet position with a small lead in development.","idea":["With 3.cxd5 cxd5 the structure becomes symmetrical and the c-file opens. White hopes the extra tempo will count, often by putting pressure on b7 and d5 with Qb3 or by occupying the c-file first. Black simply copies White's set-up, develops the c8 bishop before ...e6, and is quite safe; the position is level with correct play, but Black must not be careless."],"at":4,"moves":[["cxd5","White exchanges at once, making the position symmetrical and opening the c-file."],["cxd5","Black recaptures; the structure is now identical on both sides."],["Nc3","Develops with pressure on d5."],["Nf6","Defends d5 and develops."],["Bf4","The bishop comes out before e3, so it is not shut in."],["Nc6","Develops and puts pressure on d4."],["e3","Supports d4 and opens the f1 bishop."],["Bf5","Black copies White, developing the bishop outside the pawn chain before ...e6."],["Nf3","Develops the last minor piece towards the centre."],["e6","Opens the f8 bishop and protects d5 again."],["Qb3","The queen attacks b7, which lost its defender when the bishop left c8, and adds pressure on d5."],["Bb4","The bishop pins the knight on c3 and blocks the b-file, so b7 is no longer attacked. On b4 it is protected by the knight on c6. The game is roughly level."]],"vars":[],"played":[767,767,323,272,288,304,299,165,67,261,52,50]},{"name":"6.Ne5: the Krause Attack","summary":"White aims at the bishop on f5 with f3 and e4, and Black answers with a famous piece sacrifice.","idea":["Instead of e3, White plays Ne5, ready to win back c4 with the knight and to drive the bishop on f5 away with f3 and e4. Black's sharpest answer is to sacrifice the bishop on e4 for pawns and an attack on White's king, which is stuck in the centre. The line is heavily analysed: Black ends up with three pawns for the piece and White's king exposed, a fair but double-edged balance."],"at":10,"moves":[["Ne5","The knight eyes c4, where it can win back the pawn, and prepares f3 and e4."],["e6","Black opens the f8 bishop, aiming for ...Bb4."],["f3","White prepares e4 to take the centre and hit the bishop on f5."],["Bb4","The bishop pins the knight on c3 to the king, so the knight's support of e4 is not reliable."],["e4","White pushes anyway, inviting the piece sacrifice."],["Bxe4","The bishop takes e4, giving itself up for pawns and an attack on the king."],["fxe4","White accepts the piece."],["Nxe4","The knight hits the pinned knight on c3, and ...Qh4+ is threatened now that f2 is empty."],["Bd2","White breaks the pin, but the bishop now blocks the queen's defence of d4."],["Qxd4","Black takes a third pawn and threatens ...Qf2 mate, with the knight on e4 supporting the queen."],["Nxe4","White removes the knight that supports the mating threat."],["Qxe4+","The queen recaptures with check, keeping White's king in the centre."],["Qe2","White blocks. After 12...Bxd2+ 13.Kxd2 Qd5+ 14.Kc2 Na6 White will soon take back on c4, leaving Black three pawns for the piece against White's exposed king."]],"vars":[],"played":[343,61,52,42,16,15,14,14,14,14,14,14,14]},{"name":"Chebanenko Slav","summary":"A flexible modern move: Black prepares ...b5 before deciding where the bishop goes.","idea":["With 4...a6 Black keeps all options open. The move prepares ...b5, which gains queenside space and can win the c4 pawn or provoke c5. Black keeps the c8 bishop flexible, often developing it to g4 or f5 only after seeing White's set-up. White usually answers with e3 and b3 to keep the c4 pawn supported, or with c5 to gain space; either way the game is strategic and rich."],"at":7,"moves":[["a6","A useful waiting move that prepares ...b5 and keeps the choice of where to put the c8 bishop."],["e3","White supports d4 and prepares Bd3 or Be2 in a solid set-up."],["b5","Black gains queenside space and threatens to take on c4 and hold the pawn."],["b3","White supports c4 with a pawn, so Black cannot win it."],["Bg4","The bishop comes out before ...e6, pinning the knight on f3 to the queen."]],"vars":[],"played":[286,91,64,45,40]}],"played":[69153,19081,14220,4653,3245,3329,1853,834,722,574,181,179,177,168,167,33,33,10,18,15,18,11,9,9]},{"id":"semi-slav","name":"Semi-Slav Defence","eco":"D43–D49","side":"b","group":"closed","summary":"Black plays both ...c6 and ...e6: a solid shell that can explode into some of the sharpest lines in chess.","idea":["The Semi-Slav combines the Slav (...c6) with the Queen's Gambit Declined (...e6). The pawn on d5 is supported twice, so Black's centre is extremely solid, but the bishop on c8 is shut in. Black's idea is to release it dynamically: take on c4 at the right moment, gain space with ...b5, put the bishop on b7, and then break with ...c5, opening the long diagonal.","In the Meran (5.e3 Nbd7 6.Bd3) Black takes on c4 when White's bishop has already moved, so recapturing costs White a tempo, and Black follows up with ...b5, ...Bb7, ...a6 and ...c5. White answers with e4, and a sharp central fight follows. With 5.Bg5 White invites the Botvinnik and Moscow Variations: in the Botvinnik Black grabs c4 and holds it with ...b5, leading to a wild position after a knight sacrifice on g5, while in the Moscow Black asks the bishop to decide at once with ...h6.","Both sides need to know a lot of theory here, but the strategic ideas are clear: White wants a big centre and attacking chances; Black wants a queenside pawn majority, the long diagonal for the bishop on b7, and pressure against White's centre."],"moves":[["d4","White takes the centre; the pawn is protected by the queen."],["d5","Black claims an equal share of the centre."],["c4","The Queen's Gambit: White attacks d5 from the side."],["c6","Black supports d5 with the c-pawn, as in the Slav."],["Nf3","Develops and covers e5."],["Nf6","Develops and defends d5."],["Nc3","Adds pressure on d5 and prepares e4."],["e6","The Semi-Slav: d5 is now supported twice. Black gives up the bishop's early development to f5 in return for an unbreakable centre and the option of ...dxc4 and ...b5."],["e3","A solid choice: White supports d4 and opens the f1 bishop, avoiding the sharp lines after 5.Bg5."],["Nbd7","The knight develops behind the pawns, supporting ...e5 or ...c5 later."],["Bd3","The bishop goes to its most active square, aiming at h7. Now Black can take on c4 and make it move again."],["dxc4","Black takes because White's bishop has already moved: recapturing costs White a tempo."],["Bxc4","White wins the pawn back."],["b5","The Meran: Black gains queenside space with tempo on the bishop and prepares ...Bb7."],["Bd3","The bishop goes back to the b1–h7 diagonal, aiming at Black's kingside and supporting e4."],["Bb7","The bishop finally has a good diagonal. It is still blocked by c6, but after ...c5 it will point straight at White's king."],["O-O","White castles, ready for the central break e4."],["a6","Prepares ...c5: with a6 played, the b5 pawn stays protected once the c6 pawn advances."],["e4","White strikes in the centre while Black's king is still on e8."],["c5","The thematic counter-blow: Black hits d4 and opens the long diagonal for the bishop on b7."],["d5","White pushes past, blocking the bishop's diagonal and threatening to open lines with dxe6 while Black's king is still in the centre."],["Qc7","Black keeps the tension: the queen steps off the d-file, watches e5 and prepares ...c4 and ...Bd6."],["dxe6","White opens the position, leaving Black with a pawn on e6 that can become a target."],["fxe6","Black recaptures towards the centre. The pawns on c5 and e6, the half-open f-file and the queenside majority give Black counterplay; White aims at e6 and the light squares."]],"vars":[{"name":"Classical Meran: 8...a6","summary":"The original Meran: Black plays ...a6 and ...c5 at once, and wild complications follow.","idea":["Before developing the bishop, Black prepares ...c5 with ...a6. White answers with e4 and e5, kicking the knight from f6, and both sides go for each other: Black opens the centre with ...cxd4, White sacrifices a knight on b5 to win back material on f6. The resulting position is open and unbalanced, with a passed d-pawn for Black and an exposed black king."],"at":15,"moves":[["a6","Black prepares ...c5 immediately, keeping b5 protected."],["e4","White strikes in the centre at once."],["c5","Black hits d4 straight back."],["e5","White gains space and attacks the knight on f6."],["cxd4","Black ignores the threat to the knight and attacks the knight on c3 with the pawn."],["Nxb5","The knight escapes by taking b5, and if Black captures it White will win back the piece on f6."],["axb5","Black takes the knight."],["exf6","White takes the knight on f6 and the material is roughly level again."],["gxf6","Black recaptures, opening the g-file. Black has a passed d-pawn and open lines; White has the safer king and targets on Black's scattered pawns."]],"vars":[],"played":[36,24,25,13,13,13,10,10,8]},{"name":"Anti-Meran: 6.Qc2","summary":"White avoids the Meran and prepares e4 with the queen.","idea":["With 6.Qc2 White develops the queen first and keeps the f1 bishop at home, so that taking on c4 does not gain Black a tempo yet. The queen supports e4. Black usually develops the bishop actively on d6, castles, and then takes on c4 once White's bishop has moved, following up with ...b5, ...Bb7 and a freeing break."],"at":10,"moves":[["Qc2","The queen supports e4 and White keeps the f1 bishop at home for now."],["Bd6","The bishop takes its most active square, supporting a later ...e5."],["Bd3","White develops, aiming at h7 together with the queen."],["O-O","Black castles; the knight on f6 and the bishop on d6 keep the king's side well covered."],["O-O","White castles too."],["dxc4","Now that the bishop has moved, Black takes on c4 and gains a tempo."],["Bxc4","White recaptures."],["b5","Black gains space with tempo, as in the Meran."],["Be2","The bishop retreats to a safe square."],["Bb7","The bishop gets the long diagonal. Black follows with ...a6 and ...c5, or ...e5, to free the game."]],"vars":[],"played":[727,633,243,182,181,153,153,121,78,70]},{"name":"Botvinnik Variation","summary":"Black grabs c4 and holds it with ...b5, leading to one of the sharpest lines in chess.","idea":["After 5.Bg5 Black takes on c4 and defends the pawn with ...b5. White builds a big centre with e4 and e5, and after ...h6 and ...g5 sacrifices the knight on g5 to keep the pin and win back the material on f6. The position is chaotic: White has a pawn wedge on f6 and attacking chances; Black has the queenside pawns, the long diagonal for the bishop, and often castles long. Deep preparation is needed on both sides."],"at":8,"moves":[["Bg5","The bishop pins the knight to the queen, inviting the sharpest lines of the Semi-Slav."],["dxc4","The Botvinnik: Black grabs the pawn and plans to hold it with ...b5."],["e4","White builds a big centre, using the time Black spent on the pawn."],["b5","Black defends c4 with a pawn."],["e5","White attacks the pinned knight on f6."],["h6","Black counterattacks the bishop instead of retreating the knight."],["Bh4","White keeps the pin."],["g5","Black breaks the pin by force, hitting the bishop again."],["Nxg5","A sacrifice: the knight takes g5, and if Black takes it, the bishop recaptures and renews the pin."],["hxg5","Black accepts the knight."],["Bxg5","The bishop restores the pin on f6, and the knight there is lost."],["Nbd7","Black develops and guards e5 and f6; the knight on f6 cannot be saved, but the pawn that takes it can be attacked."],["exf6","White wins back the piece. The pawn on f6 is a thorn deep in Black's position."],["Bb7","The bishop takes the long diagonal, and Black prepares ...Qb6, ...c5 and often long castling."]],"vars":[{"name":"Moscow Variation","summary":"Black asks the bishop to decide at once, avoiding the Botvinnik complications.","idea":["With 5...h6 Black forces White to choose. If White trades on f6, Black gets the bishop pair and a very solid position, at the cost of a small lag in development. If White keeps the bishop with Bh4, Black takes on c4 and holds it with ...g5 and ...b5, in the sharp Anti-Moscow Gambit."],"at":9,"moves":[["h6","Black puts the question to the bishop before taking on c4."],["Bxf6","White gives up the bishop pair for a lead in development."],["Qxf6","The queen recaptures. Black has the two bishops and a solid position."],["e3","White supports d4 and opens the f1 bishop."],["Nd7","The knight develops, supporting the later breaks ...e5 and ...c5."],["Bd3","The bishop develops; now ...dxc4 will cost White another move."],["dxc4","Black takes because the bishop has already moved."],["Bxc4","White recaptures."],["g6","Black prepares to put the bishop on g7, where together with the queen it presses on d4 and the long diagonal."],["O-O","White castles."],["Bg7","The bishop is on the long diagonal. Black will castle and prepare ...e5 or ...c5 to make the bishops count."]],"vars":[{"name":"Anti-Moscow Gambit","summary":"White keeps the bishop and gives up the c4 pawn for central space and attacking chances.","idea":["White keeps the pin with Bh4, allowing Black to take on c4 and hold the pawn with ...g5 and ...b5. In return White gets a big centre with e4, a bishop on g3 aiming at Black's queenside, and levers such as Ne5 and a4 against Black's loosened pawns. A sharp, modern line."],"at":10,"moves":[["Bh4","White keeps the pin and offers the c4 pawn."],["dxc4","Black takes the pawn."],["e4","White takes the centre in gambit style."],["g5","Black breaks the pin by force."],["Bg3","The bishop drops back to the h2–b8 diagonal, where it aims at e5 and the queenside."],["b5","Black holds on to the extra pawn on c4."],["Be2","White develops and gets ready to castle."],["Bb7","The bishop goes to the long diagonal behind the c6 pawn."],["O-O","White castles; the centre and the lead in development are the compensation for the pawn."],["Nbd7","Black develops; White can now play Ne5 and a4 to attack Black's loosened pawn chains."]],"vars":[],"played":[172,106,106,102,102,103,83,60,26,23]}],"played":[415,243,242,190,102,44,26,26,22,26,30]}],"played":[904,137,115,115,109,109,109,113,107,107,107,56,24,23]}],"played":[69153,19081,14220,4653,3245,3329,1853,1040,983,1310,241,217,217,216,179,63,40,36,27,26,23,15,7,7]},{"id":"london","name":"London System","eco":"D02, A46–A48","side":"w","group":"closed","summary":"Bishop to f4 early, then a solid pyramid with e3, c3 and d4: a reliable set-up against almost anything.","idea":["The London is a system rather than a set of forcing lines: White plays d4, Bf4, e3, c3, Nf3, Nbd2, Bd3 and castles, more or less regardless of what Black does. The key idea is to bring the dark-squared bishop out to f4 before playing e3, so it is not shut in behind the pawns as in many other queen's pawn openings.","White's pawn triangle c3–d4–e3 is very hard to break. From there White has a choice of plans: a knight on e5 supported by f4 or the queen for a kingside attack, the central break e4 (prepared by Nbd2 and Bd3), or a queenside expansion. The bishop on f4 often retreats to g3 when Black offers to trade it with ...Bd6, and if Black takes on g3 the h-file opens for White's rook.","Black's most testing set-ups hit d4 early with ...c5, often combined with ...Qb6 against the b2 pawn, which lost its defender when the bishop left c1. Against a King's Indian set-up with ...g6, White keeps the same structure and uses h3 to give the bishop a retreat on h2."],"moves":[["d4","White takes the centre; the pawn is protected by the queen."],["d5","Black claims an equal share of the centre."],["Bf4","The London bishop: it comes out before e3, so it will not be shut in behind the pawns."],["Nf6","Black develops and controls e4."],["e3","Supports d4 and opens the f1 bishop, starting the pawn triangle c3–d4–e3."],["c5","Black strikes at d4 at once, the most testing approach against the London."],["c3","White supports d4 with a pawn. The pyramid c3–d4–e3 is very hard to break."],["Nc6","More pressure on d4, and the knight can later go to b4 or e5 if lines open."],["Nd2","The pawn on c3 takes the knight's usual square, so it develops to d2, where it supports a later e4 and leaves f3 for the other knight."],["e6","Black opens the f8 bishop and supports d5, preferring solidity."],["Ngf3","The king's knight develops, covering e5 and defending d4."],["Bd6","Black offers to trade off the London bishop, White's best minor piece."],["Bg3","White keeps the bishop. If Black takes on g3, hxg3 opens the h-file for White's rook."],["O-O","Black castles, ready to play in the centre."],["Bd3","The bishop takes its best square, aiming at h7."],["b6","Black prepares ...Bb7 to develop the light-squared bishop, which is blocked by e6."],["Ne5","The knight jumps to the outpost on e5, supported by the pawn on d4 and the bishop on g3. It eyes f7 and d7 and prepares a kingside attack with f4 or Qf3."],["Bb7","Black completes development. Typical plans are ...Ne7 heading for f5, or ...Bxe5 followed by ...Nd7 to challenge the knight, while White continues with f4 or Qf3 and castling."]],"vars":[{"name":"The ...Qb6 attack on b2","summary":"Black hits b2, the pawn the London bishop left without a defender.","idea":["When the bishop leaves c1, the b2 pawn loses its defender. Black attacks it with ...Qb6, and White usually answers with Qb3. If Black then gains space with ...c4, the queen retreats to c2 and, after ...Bf5, to c1, where it still protects b2. Black has queenside space and a good bishop on f5; White will try to undermine the pawn on c4 with b3 or e4."],"at":9,"moves":[["Qb6","The queen attacks b2, which no longer has a defender since the bishop left c1."],["Qb3","White meets the attack by offering a queen trade; after ...Qxb3 axb3 White would get a half-open a-file."],["c4","Black gains queenside space with tempo on the queen."],["Qc2","The queen retreats but still defends b2."],["Bf5","Black develops with another tempo on the queen."],["Qc1","The queen steps out of the bishop's line and still covers b2."],["e6","Black opens the f8 bishop and supports d5."],["Ngf3","White develops; plans include Be2 and castling, then b3 or e4 to undermine Black's pawn on c4."]],"vars":[],"played":[19,19,14,13,0,0,0,0]},{"name":"London against a King's Indian set-up","summary":"Against ...g6 and ...Bg7, White keeps the same structure and gives the bishop a retreat on h2.","idea":["If Black chooses ...Nf6, ...g6, ...Bg7 and ...d6, White still plays the London set-up. Black's plans are ...c5 or ...e5, and ...Nh5 to chase the bishop on f4, so White plays h3 to give the bishop a safe retreat on h2. White keeps a solid centre and a comfortable game; Black gets a flexible King's Indian-style position with play on the dark squares."],"at":1,"moves":[["Nf6","Black keeps options open: ...d5, or a King's Indian set-up."],["Bf4","White plays the London bishop move anyway."],["g6","Black prepares to fianchetto the bishop on g7, aiming at d4 and the long diagonal."],["e3","White builds the pyramid and opens the f1 bishop."],["Bg7","The bishop goes to the long diagonal."],["Nf3","The knight develops and blunts the bishop on g7."],["O-O","Black castles."],["Be2","A modest square: the bishop is safe and does not get hit by ...e5–e4 later."],["d6","Black prepares ...e5 or ...c5 and controls e5."],["h3","Gives the bishop a retreat on h2, so ...Nh5 or ...e5 will not trap or trade it."],["c5","Black hits d4, the usual counter against the London."],["c3","White supports d4 with a pawn, keeping the triangle."],["Nc6","More pressure on d4."],["O-O","White castles. Black will choose between ...Qb6, ...b6 with ...Bb7, or ...Nd7 and ...e5; White keeps a solid, flexible position."]],"vars":[],"played":[44164,1085,229,40,40,32,109,70,47,43,33,18,2,1]},{"name":"Jobava London","summary":"An aggressive version: Nc3 and Bf4, with Nb5 ideas against c7.","idea":["White develops the queen's knight to c3 before the bishop to f4. The knight blocks the c-pawn, so this is not about the solid pyramid; instead White aims for quick piece play, Nb5 against c7, and sometimes e4 or long castling with a kingside pawn storm. It is sharper and less solid than the main London."],"at":2,"moves":[["Nc3","The knight develops first, giving up the c3 pyramid in favour of piece activity."],["Nf6","Black develops and controls e4."],["Bf4","The bishop comes out, and now the bishop and knight together can aim at c7."],["e6","Black opens the f8 bishop. It allows Nb5, but Black is ready to meet it."],["Nb5","The knight hits c7 together with the bishop on f4, threatening Nxc7+ with a fork."],["Na6","Black defends c7 with the knight. Next comes ...c6 to drive the knight away, with a playable position for both sides."]],"vars":[],"played":[341,263,845,216,163,128]}],"played":[69153,19081,708,381,724,402,148,137,147,38,64,149,144,129,113,65,8,7]},{"id":"kings-indian","name":"King's Indian Defence","eco":"E60–E99","side":"b","group":"indian","summary":"Black lets White build a big centre, then strikes back with ...e5 and races to attack White's king.","idea":["Black does not contest the centre at once. The king's bishop goes to g7, Black castles, and only then hits back with ...e5 (or ...c5). White usually answers with d5, closing the centre: White's pawn chain d5–e4 points at the queenside, Black's chain d6–e5 points at the kingside, and that tells each side where to play.","In the main lines it becomes a race. White breaks with c4–c5 and goes for the c-file and c7, often with a knight on d3 or c4 and a rook on c1. Black plays ...f5 and ...f4, then pushes ...g5–g4 and brings knights and the queen over to mate White's king. Black's bishop on g7 can look passive behind its own pawns, but it is a vital defender, and once the position opens it comes back to life.","If White does not close the centre, Black presses on d4 with ...Nc6, ...exd4 and ...Re8 against e4. The King's Indian suits players who accept a cramped position in return for real winning chances; Fischer and Kasparov made it famous."],"moves":[["d4","Takes a share of the centre and controls e5 and c5. Unlike a pawn on e4, the d4 pawn is already protected by the queen."],["Nf6","Develops and stops 2.e4. Black keeps the choice between many set-ups."],["c4","Grabs more space and adds control of d5, so that a later ...d5 can be met by cxd5."],["g6","The King's Indian set-up: the bishop will go to g7, where it bears down on d4 and the long diagonal from a safe distance."],["Nc3","Develops and supports e4, so White can build a full pawn centre next move."],["Bg7","The bishop takes the long diagonal. Black lets White have the centre; striking with ...d5 here would be the Grünfeld."],["e4","White accepts the invitation and occupies the centre with three pawns on c4, d4 and e4."],["d6","Stops e5, which would drive the knight from f6, and prepares ...e5 to hit back at d4."],["Nf3","The Classical Variation: the knight supports d4, watches e5 and lets White castle quickly."],["O-O","Black puts the king behind the fianchetto before opening the centre."],["Be2","A solid square: the bishop clears the way to castle and backs up the knight on f3, so a later ...Bxf3 can be met by Bxf3 without damage."],["e5","The key strike against d4. If White takes, 7.dxe5 dxe5 8.Qxd8 Rxd8 trades queens with an equal endgame, so White normally keeps the tension."],["O-O","White castles and lets Black decide. 7...exd4 8.Nxd4 would give White a comfortable space advantage, so Black keeps the pawn on e5."],["Nc6","A third attacker on d4, with the e5 pawn and the g7 bishop. White can no longer keep the tension and must choose."],["d5","White closes the centre with a gain of time on the knight. Now the pawn chains are fixed and both sides know which wing to play on."],["Ne7","The knight retreats towards the kingside, where it will support ...f5 and later join the attack from g6."],["Ne1","The Mar del Plata Variation. The knight heads for d3, where it backs up the c5 break, and it frees the f-pawn so that f3 can shore up e4."],["Nd7","The f6 knight steps aside to clear the way for ...f5, Black's thematic break; on d7 it also watches c5."],["Nd3","From d3 the knight supports c4–c5 and keeps an eye on f4, a square Black wants for the attack."],["f5","The standard break: Black hits e4 and gains space on the kingside, where the attack will come."],["Bd2","The bishop connects the rooks, so a rook can come to c1 for the c5 break. On d2 it is also safe from the coming ...f4, which would hit it on e3."],["Nf6","The knight returns to f6, where it adds pressure on e4 and covers g4, the square Black's g-pawn is heading for."],["f3","Shores up e4 for good, so Black cannot win anything in the centre and White can get on with c5."],["f4","Black locks the kingside and the race begins: Black plays ...g5, ...Ng6, ...h5 and ...g4 against White's king, while White pushes c5 and invades down the c-file."]],"vars":[{"name":"Bayonet Attack","summary":"White skips Ne1 and expands on the queenside at once with 9.b4.","idea":["White saves the time of the knight manoeuvre and gains queenside space immediately, preparing c5 and a quick attack on c7 and d6. Black usually answers with ...Nh5, clearing the f-pawn for ...f5 while the knight eyes f4. White then answers with Re1, Bf1 and sometimes Ng5, keeping the e4 square firm. It has been one of White's most dangerous tries against the King's Indian since Kramnik took it up in the 1990s."],"at":16,"moves":[["b4","White gains space on the queenside and prepares c5 straight away, without spending time on Ne1."],["Nh5","Black clears the way for ...f5 by moving the knight to h5, where it also eyes the f4 square."],["Re1","Frees f1 for the bishop, so that ...Nf4 can be met by Bf1, and the rook supports e4."],["f5","The usual break, hitting e4 and opening the f-file for Black's rook."],["Ng5","With the knight gone from f3, the bishop on e2 now attacks the knight on h5. On g5 the knight also eyes e6 and fights for e4."],["Nf6","The knight goes back to f6, out of the bishop's reach, where it guards e4 and g4. White carries on with c5 on the queenside and Black with play on the kingside."]],"vars":[],"played":[159,35,24,15,3,2]},{"name":"Sämisch Variation","summary":"White protects e4 with 5.f3 and often castles long and storms the kingside.","idea":["With 5.f3 White makes e4 rock-solid and prepares Be3 and Qd2, aiming at Bh6 to trade off Black's fianchettoed bishop, and often a pawn storm with g4 and h4 after castling long. The drawback is that the knight cannot go to f3, and the e1–h4 diagonal is weakened. Black has two main answers: the classical ...e5, often followed by ...Nh5 and ...f5, and the pawn sacrifice ...c5, which opens the long diagonal for the g7 bishop."],"at":8,"moves":[["f3","The f-pawn protects e4 for good and prepares Be3, Qd2 and a kingside pawn storm."],["O-O","Black castles anyway; the king is safe enough behind the fianchetto for now."],["Be3","Covers d4 and prepares Qd2, so that Bh6 can trade off Black's key bishop on g7."],["e5","The classical answer: Black hits d4 before White completes the set-up."],["d5","White closes the centre and gains space, so the kingside plans can go ahead."],["Nh5","With no knight on f3, White cannot easily stop ...f5. The knight eyes f4, and with the f-pawn on f3 the queen can check on h4."],["Qd2","Develops, connects towards long castling and keeps Bh6 in reserve."],["f5","The thematic break: Black hits e4 and opens the f-file."],["O-O-O","White castles long, taking the king away from Black's pawns, and the rook backs up d5."],["Nd7","The other knight heads for c5 or f6, adding pressure on e4. Both sides now attack on opposite wings."]],"vars":[{"name":"The ...c5 pawn sacrifice","summary":"Black gives a pawn to open the long diagonal and the d-file.","idea":["Instead of ...e5, Black strikes at d4 from the side. If White takes twice and trades queens, Black is a pawn down in an endgame, but has a lead in development, the open d-file and the g7 bishop raking down the long diagonal at b2 and c3. Practice has shown the compensation is fully adequate, which is why many White players avoid the endgame with 7.Nge2 or 7.d5."],"at":11,"moves":[["c5","Black hits d4 from the side. If White takes, the long diagonal opens for the bishop on g7."],["dxc5","White accepts the pawn. 7.d5 and 7.Nge2 lead to Benoni-type positions instead."],["dxc5","Black recaptures, opening the d-file and making the pawn on c5 a target."],["Qxd8","White trades queens, hoping the extra pawn will count in the endgame."],["Rxd8","The rook lands on the open d-file at once."],["Bxc5","White wins the pawn."],["Nc6","Black develops with ideas of ...Nd7 to gain time on the bishop and ...Be6 to hit c4. Pressure on the d-file and the long diagonal is good compensation for the pawn."]],"vars":[],"played":[77,11,11,11,11,11,11]}],"played":[342,365,210,56,45,28,27,14,12,2]},{"name":"Four Pawns Attack","summary":"White builds the biggest possible centre with four pawns and threatens e5.","idea":["White puts pawns on c4, d4, e4 and f4 and threatens to push e5, driving the knight away. The danger for White is overextension: the centre is huge but White is behind in development and the king is still in the centre. Black hits back at once with ...c5, and after d5 opens the e-file with ...e6 and ...exd5, so that a rook on e8 hits e4. The play is sharp and tactical."],"at":8,"moves":[["f4","White builds the biggest centre possible and threatens e5, kicking the knight from f6."],["O-O","Black castles first and waits to strike at the overextended centre."],["Nf3","Develops and supports the e5 push."],["c5","The best way to fight a big centre: hit it from the side at once, before White finishes developing."],["d5","White gains space and keeps the centre closed."],["e6","Black attacks d5 to open the e-file while White's king is still on e1."],["Be2","Develops and prepares to castle."],["exd5","Black opens the e-file."],["cxd5","White recaptures with the c-pawn, keeping e4 in place and the e5 push in reserve."],["Re8","The rook aims at e4 and, behind it, the bishop on e2 and the king on e1."],["e5","The sharpest move: White pushes on, gaining space and attacking the knight."],["dxe5","Black takes. After the recapture White's d5 pawn is passed, but the pawn on e5 needs looking after."],["fxe5","White recaptures; the pawn on e5 cramps Black but may become a target."],["Ng4","The knight jumps forward and attacks e5. After 12.Bg5 Qb6 the fight is wild, with chances for both sides."]],"vars":[],"played":[70,52,56,40,38,45,33,32,32,11,9,9,9,9]},{"name":"Fianchetto Variation","summary":"White fianchettoes the king's bishop: a quiet, positional system.","idea":["White plays Nf3, g3 and Bg2, making the king very safe and pointing the bishop at d5 and the queenside. This takes the sting out of Black's usual kingside attack, because the f-pawn can no longer roll forward against a weakened king. Black usually aims for ...e5 with ...Nbd7 and ...c6, or ...Nc6 and ...a6 (the Panno), and the game becomes a manoeuvring fight for the centre."],"at":4,"moves":[["Nf3","White develops the knight first and plans g3 and Bg2."],["Bg7","Black continues with the King's Indian set-up."],["g3","Prepares Bg2: White's king will be very safe behind this bishop."],["O-O","Black castles."],["Bg2","The bishop aims along the long diagonal at d5, c6 and b7."],["d6","Prepares ...e5 and stops White from pushing d5 and e5 freely."],["O-O","White castles."],["Nbd7","The knight supports ...e5 and leaves the c-pawn free to go to c6."],["Nc3","Develops and prepares e4 to take the centre."],["e5","The standard central strike."],["e4","White claims the centre; the structure is like the Classical, but White's bishop is on g2."],["c6","Black covers d5 and makes room for ...Qb6 to press on d4 and b2. Black keeps the option of ...exd4 and ...Re8 against e4."]],"vars":[],"played":[573,1263,693,490,487,548,369,203,182,476,380,82]},{"ref":"grunfeld","at":5,"name":"Grünfeld Defence","summary":"Black hits the centre at once with 3...d5 instead of letting White build it."}],"played":[69153,44164,32832,7703,5834,3909,3630,3415,1169,1663,1641,1446,944,335,306,306,95,68,42,42,4,4,7,7]},{"id":"nimzo-indian","name":"Nimzo-Indian Defence","eco":"E20–E59","side":"b","group":"indian","summary":"Black pins the c3 knight with 3...Bb4 to stop e4, ready to double White's pawns.","idea":["Nimzowitsch's idea is to fight for e4 with pieces rather than pawns. The bishop on b4 pins the knight on c3, the piece that supports e4, and Black is happy to give up the bishop for the knight, especially if it doubles White's c-pawns. Black keeps the pawn structure flexible: ...d5, ...c5, ...b6 with ...Bb7, or ...d6 and ...e5 all fit.","The trade-off is the central theme. White usually gets the bishop pair and sometimes a big centre; Black gets a lead in development and targets, above all the doubled c-pawns and the weak c4 square. If the position closes, Black's knights are excellent; if it opens, White's bishops come to life. White can avoid the doubled pawns with 4.Qc2, play solidly with 4.e3, or force the issue with 4.a3.","It is one of the most respected defences in chess, played by every world champion from Capablanca to Carlsen. Black gets a sound position with real counter-chances."],"moves":[["d4","Takes a share of the centre and controls e5 and c5."],["Nf6","Develops and stops 2.e4."],["c4","Gains space and adds control of d5."],["e6","Opens the way for the f8 bishop and keeps both ...d5 and ...Bb4 possible."],["Nc3","Prepares e4: the knight on c3 is the piece that supports White's central push."],["Bb4","The Nimzo-Indian: the bishop pins the knight to the king, so e4 is off for now. Black is ready to take on c3 and double White's pawns."],["e3","The Rubinstein Variation: solid. It frees the f1 bishop, and White plans Bd3, Nf3 and castling before aiming for e4."],["O-O","Black castles and keeps options open: ...d5, ...c5 and ...b6 are all possible."],["Bd3","The bishop takes its best diagonal, aiming at h7 and covering e4."],["d5","Black grabs central space and takes control of e4 with a pawn."],["Nf3","Natural development, preparing to castle."],["c5","Black strikes at d4. The structure is like a Queen's Gambit, with Black's bishop already active on b4."],["O-O","White finishes the kingside development."],["Nc6","More pressure on d4, now hit by the c5 pawn and the knight."],["a3","White asks the bishop to decide: White gets the bishop pair at the cost of doubled c-pawns."],["Bxc3","Black gives up the bishop and damages White's structure, in return for quick development."],["bxc3","White recaptures towards the centre; the c3 pawn supports d4 and a later e4."],["dxc4","Black releases the tension: White's bishop has to recapture, and Black gets ready for ...e5."],["Bxc4","White regains the pawn. White has the two bishops and a central pawn majority."],["Qc7","The queen covers e5, preparing ...e5 to fight for the centre and open lines for Black's pieces."],["Bd3","The bishop returns to cover e4, supporting a later e4 push."],["e5","Black strikes. Now ...e4 would fork the bishop on d3 and the knight on f3, so White must react, usually with 12.Qc2. The fight is White's bishops against Black's pressure on c3 and d4."]],"vars":[{"name":"Hübner Variation","summary":"Black takes on c3 early and closes the centre so the knights outplay the bishops.","idea":["Black hits d4 at once and, after Bd3, Nc6 and Nf3, gives up the bishop for the knight before White has played a3. Then Black builds a dark-square wall with ...d6 and ...e5. White's doubled c-pawns are fixed, the centre is closed, and Black's knights find good squares, while White's bishops are blunted by their own pawns. Fischer used it to beat Spassky in their 1972 match."],"at":7,"moves":[["c5","Black hits d4 at once and keeps the option of castling later."],["Bd3","White develops the bishop to its best square."],["Nc6","Adds pressure on d4."],["Nf3","Develops and protects d4 again."],["Bxc3+","The Hübner idea: Black gives up the bishop before a3, doubling White's pawns without losing a move."],["bxc3","White must recapture with the pawn."],["d6","Black prepares ...e5 to build a wall of pawns on the dark squares."],["e4","White grabs space in the centre."],["e5","With pawns on c5, d6 and e5 Black fixes the doubled c-pawns, and the closed centre suits Black's knights."],["d5","White closes the centre and attacks the knight."],["Ne7","The knight heads for g6. White's bishops are hemmed in by their own pawns; White will try to open lines with f4."]],"vars":[],"played":[241,98,43,11,11,11,11,7,7,7,7]},{"name":"Classical Variation","summary":"The queen covers c3, so White can avoid doubled pawns.","idea":["With 4.Qc2 White plans to recapture on c3 with the queen, keeping a healthy structure and the bishop pair. The queen also watches e4. The price is time: the queen moves twice, and Black gets a lead in development. Black usually castles, takes on c3 after a3 and plays ...b6 and ...Bb7 to fight for the light squares, or strikes at once with ...d5 or ...c5."],"at":6,"moves":[["Qc2","The queen protects c3, so after ...Bxc3 White recaptures with the queen and avoids doubled pawns. It also covers e4."],["O-O","Black castles and keeps options open."],["a3","Forces the bishop to take or retreat."],["Bxc3+","Black takes, gaining time; White's queen moves a second time."],["Qxc3","White has the bishop pair and a sound structure, but has spent moves with the queen."],["b6","Black fianchettoes to fight for the light squares, above all e4."],["Bg5","Develops and pins the knight against the queen on d8."],["Bb7","The bishop takes the long diagonal, aiming at e4 and g2."],["f3","Takes e4 away from Black's knight and bishop and prepares e4 to build the centre."],["h6","Asks the bishop whether it wants to keep the pin."],["Bh4","White keeps the pin."],["d5","Black hits the centre before e4 arrives, fighting for e4 and striking at c4."]],"vars":[],"played":[1626,594,277,277,277,90,77,62,19,12,12,13]},{"name":"Sämisch Variation","summary":"White forces the trade at once, takes the bishop pair and accepts doubled c-pawns.","idea":["White spends a move to make Black take on c3, getting the two bishops and a pawn mass to push with f3 and e4. The doubled c-pawns, especially c4, are the long-term weakness. Black fixes them with ...c5, hits c4 with ...b6, ...Ba6 and ...Na5 or ...Nc6–a5, and uses ...Ne8 and ...f5 to stop White's pawns rolling forward. Whoever wins this race between centre and weaknesses wins the game."],"at":6,"moves":[["a3","White spends a move to force the trade, taking the bishop pair at once."],["Bxc3+","Black takes, as planned."],["bxc3","White has doubled c-pawns but more central pawns and two bishops."],["c5","Black fixes the doubled pawns: with a pawn on c5 the c4 pawn cannot advance and can be attacked."],["e3","Solid: White prepares Bd3 and Ne2, keeping the f-pawn free for f3 and e4."],["Nc6","Develops and hits d4; the knight may later go to a5 to attack c4."],["Bd3","The bishop aims at the kingside."],["O-O","Black castles."],["Ne2","On e2 the knight leaves the f-pawn free to support e4."],["b6","Prepares ...Ba6, piling up on the weak c4 pawn."],["e4","White builds the centre and threatens e5, kicking the knight, or Bg5 pinning it."],["Ne8","Capablanca's idea: the knight sidesteps both e5 and Bg5, and Black can meet f4 with ...f5 to halt the pawns. Next comes ...Ba6 against c4."]],"vars":[],"played":[320,321,321,120,46,29,28,6,42,36,31,30]},{"ref":"queens-indian","at":4,"name":"Queen's Indian Defence","summary":"White avoids the pin with 3.Nf3, and Black fianchettoes with 3...b6."}],"played":[69153,44164,32832,22625,9144,7356,3996,3158,1907,1404,321,107,111,26,17,15,15,13,13,25,2,4]},{"id":"queens-indian","name":"Queen's Indian Defence","eco":"E12–E19","side":"b","group":"indian","summary":"Black fianchettoes the queen's bishop with 3...b6 to control e4 and d5.","idea":["When White avoids the Nimzo-Indian with 3.Nf3, Black fights for the same light squares, e4 and d5, with the bishop on b7 or a6. Black keeps the pawns on e6 and d7 for now and develops quietly; the idea is to stop White from ever playing e4 and getting a free centre.","In the main line White fianchettoes too, and Black harasses the c4 pawn with ...Ba6. Black then builds a solid wall with ...c6 and ...d5 and frees the game with ...c5 at the right moment. White aims for e4, or for pressure along the long diagonal and the c-file. The Queen's Indian is one of the most solid defences in chess: it rarely loses, and it gives a patient player a sound, balanced game."],"moves":[["d4","Takes a share of the centre and controls e5 and c5."],["Nf6","Develops and stops 2.e4."],["c4","Gains space and adds control of d5."],["e6","Opens the way for the f8 bishop and prepares ...d5 or ...Bb4."],["Nf3","White develops and sidesteps the Nimzo-Indian: there is no knight on c3 to pin."],["b6","The Queen's Indian: the bishop will fianchetto to fight for e4 and d5, the squares White needs for a free game."],["g3","White fianchettoes too, so a bishop on g2 will oppose Black's on the long diagonal."],["Ba6","Nimzowitsch's move: the bishop hits c4 at once, so White must spend a move defending it."],["b3","The main way to defend c4. It slightly weakens the long diagonal and the c3 square."],["Bb4+","A useful check: it lures White's bishop to d2, the square White's queen's knight wants."],["Bd2","White blocks with the bishop."],["Be7","The bishop goes back, its job done: White's bishop is in the knight's way on d2 and will have to move again."],["Bg2","White completes the fianchetto."],["c6","Prepares ...d5 and gives the bishop on a6 more support; together they form a solid barrier on the light squares."],["Bc3","The bishop moves to the long diagonal, where it supports d4, and clears d2 for the knight."],["d5","Black claims the centre and blunts the bishop on g2."],["Ne5","The knight takes up a strong post on e5, where it eyes c6 and frees the long diagonal for the g2 bishop."],["Nfd7","Black challenges the knight at once, so it cannot settle on e5."],["Nxd7","White trades."],["Nxd7","Black recaptures and the knight is developed."],["Nd2","White develops the last minor piece; from d2 the knight supports e4 and c4."],["O-O","Black castles."],["O-O","White castles."],["Rc8","Black prepares ...c5, freeing the position and challenging the bishop on c3. White, meanwhile, aims for e4 to open the centre."]],"vars":[{"name":"Classical: 4...Bb7","summary":"The traditional square: the bishop goes straight to the long diagonal.","idea":["Black puts the bishop on b7 to control e4 directly and to oppose White's g2 bishop. After both sides castle, White wants e4 with Nc3 and Qc2; Black occupies e4 with the knight and trades on c3 to ease the position, then frees the game with ...c5 or ...f5. It is very solid, though White keeps a small space advantage."],"at":7,"moves":[["Bb7","The bishop goes to the long diagonal at once, controlling e4."],["Bg2","White opposes the bishop on the same diagonal."],["Be7","Black prepares to castle, keeping the f-pawn free for a later ...f5."],["O-O","White castles."],["O-O","Black castles."],["Nc3","White develops and prepares Qc2 and e4."],["Ne4","Black occupies e4 before White can push there and offers to trade on c3."],["Qc2","White challenges the knight, ready to recapture on c3 with the queen."],["Nxc3","Black trades, easing the position."],["Qxc3","White keeps a little more space, but Black has no weaknesses."],["c5","Black challenges d4, the standard way to free the game; ...f5 to hold e4 is the other main idea."]],"vars":[],"played":[699,746,451,403,482,214,206,56,53,50,14]},{"name":"Petrosian Variation","summary":"White stops ...Bb4 so that Nc3 and e4 can follow without a pin.","idea":["Petrosian's 4.a3 looks slow but has a clear point: with b4 covered, White can play Nc3 without fearing a Nimzo-style pin, and so fight for e4 and d5. Kasparov used it to great effect. Black usually plays ...Bb7 and ...d5; after cxd5 and Qc2, White builds a big centre with e4, and the game is about White's central pawns against Black's pressure on d4 and the long diagonal."],"at":6,"moves":[["a3","Takes b4 away from Black's bishop, so the knight can go to c3 without being pinned."],["Bb7","Black controls e4 and d5 from the long diagonal."],["Nc3","Now the knight supports e4 and d5 freely."],["d5","Black stakes out the centre before White can play e4 or d5."],["cxd5","White exchanges, opening the c-file."],["Nxd5","Black recaptures with the knight, keeping the bishop's diagonal open."],["Qc2","The queen covers e4 and c3, preparing e4."],["Nxc3","Black trades knights, so that e4 does not come with a gain of time on the knight."],["bxc3","White recaptures towards the centre and now has the pawns for a big centre."],["Be7","Black develops and prepares to castle."],["e4","White builds the classical pawn centre."],["O-O","Black castles."],["Bd3","The bishop supports e4 and aims at the kingside."],["c5","Black strikes at d4. White plans a kingside attack behind the central pawns; Black presses on d4 and e4 with pieces."]],"vars":[],"played":[472,357,306,253,160,138,67,34,34,13,13,30,29,29]},{"ref":"nimzo-indian","at":4,"name":"Nimzo-Indian Defence","summary":"If White plays 3.Nc3 instead, Black pins it with 3...Bb4."},{"ref":"catalan","at":4,"name":"Catalan Opening","summary":"White fianchettoes at once with 3.g3, and Black answers ...d5."}],"played":[69153,44164,32832,22625,11371,2118,1511,677,375,284,283,276,133,43,17,17,4,2,1,1,1,1,1,1]},{"id":"grunfeld","name":"Grünfeld Defence","eco":"D70–D99","side":"b","group":"indian","summary":"Black hits the centre with 3...d5, lets White build it, then attacks it with pieces and ...c5.","idea":["The Grünfeld is the hypermodern idea in its purest form. Black plays ...d5, and in the Exchange Variation lets White take on d5 and build a big pawn centre with e4. That centre is then the target: the bishop on g7 hits d4 and c3 down the long diagonal, ...c5 attacks d4 from the side, and ...Nc6, ...Bg4 and ...Qa5 add pressure.","White's plans are to keep the centre intact and push d5 when the moment is right, gaining space and cutting Black's position in two, or to attack the king with f4–f5. Black's long-term trump is the queenside pawn majority: if the centre is traded off, the a- and b-pawns can run. Games are sharp and theoretical; Kasparov and Svidler are among its great exponents."],"moves":[["d4","Takes a share of the centre and controls e5 and c5."],["Nf6","Develops and stops 2.e4."],["c4","Gains space and adds control of d5."],["g6","Prepares ...Bg7, where the bishop will bear down on d4."],["Nc3","Develops and prepares e4."],["d5","The Grünfeld: Black strikes in the centre at once, before White can play e4."],["cxd5","The Exchange Variation: White takes and will gain time on the knight."],["Nxd5","Black recaptures; the knight is exposed, but that is part of the plan."],["e4","White hits the knight and takes the whole centre."],["Nxc3","Black trades knights. The recapture puts a pawn on c3, right on the bishop's diagonal."],["bxc3","White has a big centre: c3, d4 and e4."],["Bg7","The bishop takes the long diagonal, aiming at d4 and c3. This is the heart of Black's counterplay."],["Bc4","The Classical Exchange: the bishop goes to its most active square, eyeing f7."],["c5","The key lever: Black hits d4 from the side."],["Ne2","From e2 the knight protects d4 and c3, and leaves the f-pawn free to advance to f3 or f4."],["Nc6","A third attacker on d4, together with the c5 pawn and the g7 bishop."],["Be3","Defends d4 again."],["O-O","Black castles."],["O-O","White castles."],["Bg4","Black pins the knight on e2, a defender of d4, against the queen, and provokes f3, which weakens the a7–g1 diagonal."],["f3","White hits the bishop, and the f-pawn props up e4."],["Na5","The knight attacks the bishop on c4 and eyes the c4 square. After 12.Bd3 cxd4 13.cxd4 Be6 the fight is White's mobile centre against Black's queenside majority; 12.Bxf7+ is the sharp Seville Variation."]],"vars":[{"name":"Modern Exchange: 7.Nf3","summary":"The knight goes to f3 to support d4, and White often gives the a-pawn for activity.","idea":["Instead of Bc4 and Ne2, White develops the knight to its natural square, where it supports d4 and e5. After ...c5, White often plays Rb1, getting the rook off the long diagonal and hitting b7, and is willing to give the a2 pawn for a lead in development and a strong centre. A quieter option is Be3 with an early queen trade, where White's centre and active king face Black's queenside majority."],"at":12,"moves":[["Nf3","The knight supports d4 and e5 from its natural square."],["c5","Black hits d4 straight away."],["Rb1","The rook leaves the long diagonal, where it stood behind c3, and attacks b7 down the half-open b-file."],["O-O","Black castles; b7 is protected by the bishop on c8."],["Be2","White develops and prepares to castle."],["cxd4","Black releases the tension and opens the c-file."],["cxd4","White recaptures and keeps the pawn duo on d4 and e4."],["Qa5+","A check that prepares to grab the a2 pawn."],["Bd2","White blocks and gives up the a-pawn for time."],["Qxa2","Black takes the pawn and will have a passed a-pawn in the long run."],["O-O","White has a lead in development and a strong centre, with ideas of d5 and Bb4 hitting e7. Black hopes to survive the pressure and win with the extra pawn."]],"vars":[{"name":"The 8.Be3 endgame","summary":"White protects d4 and steers for a queenless middlegame.","idea":["White keeps the a-pawn safe and covers d4 with the bishop. After ...Qa5 and Qd2, the queens come off and the game turns into an endgame where White's king is well placed in the centre and the d- and e-pawns are strong, while Black has active pieces and the queenside majority. It is a subtle line where understanding matters more than memory."],"at":14,"moves":[["Be3","The bishop supports d4 and keeps the rook on a1 for now."],["Qa5","The queen attacks c3, which is also hit by the bishop on g7 and has no pawn to protect it."],["Qd2","White protects c3 with the queen."],["Nc6","Black adds pressure on d4."],["Rc1","The rook protects c3 a second time and gets out of the line of the g7 bishop."],["cxd4","Black opens the c-file."],["cxd4","White recaptures; now the queens face each other on a5 and d2."],["Qxd2+","Black trades queens, removing any attack on the king."],["Kxd2","The king recaptures and is well placed in the centre for an endgame."],["O-O","Black castles. White's strong centre and active king face Black's pressure on d4 and the queenside majority; 13.d5 is the usual try."]],"vars":[],"played":[140,119,82,40,5,4,4,4,4,4]}],"played":[428,556,97,95,92,51,51,49,41,41,40]},{"name":"Russian System","summary":"White develops, then hits d5 with 5.Qb3 and takes the centre with e4.","idea":["White delays cxd5 and instead plays Nf3 and Qb3, attacking d5. Black gives up the centre with ...dxc4, the queen recaptures, and White plays e4 with a classical pawn centre. Black then hits back with pieces. The main systems are Smyslov's ...Bg4 and ...Nfd7–b6, which pressures d4 and gains time on the queen, and the Hungarian ...a6 and ...b5, which grabs queenside space with gain of time."],"at":6,"moves":[["Nf3","White develops before deciding on the centre."],["Bg7","Black completes the fianchetto."],["Qb3","The Russian System: the queen attacks d5 and forces Black to decide."],["dxc4","Black gives up the centre for time: the queen will be hit again later."],["Qxc4","White regains the pawn and is ready for e4."],["O-O","Black castles, inviting White to take the centre."],["e4","White builds the classical pawn centre on d4 and e4."],["Bg4","Smyslov's move: the bishop attacks the knight on f3, a defender of d4."],["Be3","White protects d4 again."],["Nfd7","The knight steps aside, opening the bishop on g7 against d4, and heads for b6 to hit the queen."],["Qb3","The queen steps out of the knight's way and attacks b7, now unprotected."],["Nb6","The knight blocks the b-file, protecting b7, and eyes c4 and d5."],["Rd1","The rook protects d4 and prepares d5."],["Nc6","Black now hits d4 with the knight on c6 and the bishop on g7, while the bishop on g4 attacks its defender on f3. White usually answers 11.d5 Ne5 with a tense fight."]],"vars":[{"name":"Hungarian Variation","summary":"Black gains queenside space with ...a6 and ...b5, hitting the queen.","idea":["Instead of developing the bishop, Black uses the exposed queen on c4 as a target: ...a6 and ...b5 gain space and time, and ...c5 and ...Bb7 then attack White's centre from the queenside and along the long diagonal. Black is happy to give up the c-pawn temporarily for quick piece play against e4."],"at":13,"moves":[["a6","Prepares ...b5, gaining time on the queen."],["Be2","White develops calmly."],["b5","The pawn hits the queen and gains space."],["Qb3","The queen retreats, keeping an eye on d5."],["c5","Black strikes at d4 with the queenside pawns."],["dxc5","White takes the pawn."],["Bb7","The bishop hits e4. Black has quick play against the centre and will try to win back the c5 pawn."]],"vars":[],"played":[60,31,31,30,22,22,4]}],"played":[560,568,176,166,166,121,117,9,6,6,2,2,4,2]},{"name":"The 4.Bf4 system","summary":"White develops the bishop outside the pawn chain and keeps a solid centre.","idea":["White avoids the big theoretical lines: the bishop goes to f4, aiming at c7, and e3 keeps d4 solid. Black's sharpest answer is ...c5, giving up a pawn for a moment; after ...Qa5 the knight on c3 is pinned and Black wins the pawn back with active play."],"at":6,"moves":[["Bf4","The bishop develops outside the pawn chain, aiming at c7."],["Bg7","Black completes the fianchetto."],["e3","Supports d4 and opens the way for the f1 bishop."],["c5","Black hits d4 at once, ready to give a pawn for activity."],["dxc5","White takes the pawn."],["Qa5","The queen pins the knight on c3 to the king and threatens ...Ne4, piling up on it."],["Rc1","White protects the pinned knight."],["dxc4","Black removes the c4 pawn, opening the position."],["Bxc4","White recaptures with the bishop."],["O-O","Black castles."],["Nf3","White develops."],["Qxc5","Black regains the pawn and hits the unprotected bishop on c4. The game is level."]],"vars":[],"played":[84,82,78,29,28,27,21,9,9,8,3,8]},{"ref":"kings-indian","at":5,"name":"King's Indian Defence","summary":"Black plays 3...Bg7 and lets White build the centre with e4."}],"played":[69153,44164,32832,7703,5834,1964,1165,1165,951,950,950,936,271,246,248,154,151,141,132,70,70,28]},{"id":"catalan","name":"Catalan Opening","eco":"E01–E09","side":"w","group":"indian","summary":"Queen's Gambit plus a fianchetto: White's bishop on g2 presses on the queenside.","idea":["The Catalan combines the Queen's Gambit with g3 and Bg2. The bishop on g2 aims down the long diagonal at d5, c6, b7 and a8, so White's pressure is mostly on Black's queenside. White is often happy to give up the c4 pawn for a while: Black finds it hard to hold the pawn and develop the c8 bishop at the same time.","In the Open Catalan Black takes on c4 and tries to keep it with ...a6 and ...b5, or to use the time to free the game with ...c5. White wins the pawn back and presses on the c-file and the long diagonal, against c6, c7 and the light squares. In the Closed Catalan Black keeps the pawn on d5 and builds a solid wall with ...c6 and ...b6, and White aims for e4. Either way White gets long-lasting, low-risk pressure; it has been a favourite of Kramnik, Carlsen and Ding."],"moves":[["d4","Takes a share of the centre and controls e5 and c5."],["Nf6","Develops and stops 2.e4."],["c4","Gains space and adds control of d5."],["e6","Opens the way for the f8 bishop and prepares ...d5."],["g3","The Catalan: White will fianchetto the king's bishop to aim it at d5 and the queenside."],["d5","Black takes the centre in Queen's Gambit style."],["Bg2","The Catalan bishop takes the long diagonal, pressing on d5 and, beyond it, b7."],["Be7","Solid development: Black prepares to castle and keeps ...dxc4 in reserve."],["Nf3","Develops, covering d4 and e5."],["O-O","Black castles."],["O-O","White castles and leaves c4 unprotected; White expects to win it back."],["dxc4","The Open Catalan: Black grabs the pawn, opening the long diagonal, and hopes to keep it with ...a6 and ...b5."],["Qc2","The queen attacks c4 and covers e4."],["a6","Prepares ...b5 to hold c4 or at least gain time on the queen."],["Qxc4","White takes back at once."],["b5","Black gains time on the queen and makes room for ...Bb7."],["Qc2","The queen drops back to c2, watching the c-file and e4."],["Bb7","The bishop takes the long diagonal, opposing White's bishop on g2."],["Bf4","The bishop develops actively, hitting c7 and covering b8 and e5, so Black's queenside is harder to untangle."],["Nd5","Black hits the bishop on f4 and opens the b7 bishop's diagonal towards g2."],["Nc3","White develops and challenges the knight."],["Nxf4","Black takes the bishop and gains the bishop pair."],["gxf4","White's pawns are doubled, but White controls e5, gets a half-open g-file and keeps pressure on the c-file and long diagonal against Black's queenside."]],"vars":[{"name":"Open Catalan: 8.a4","summary":"White stops ...b5 before taking back on c4.","idea":["Instead of taking on c4 at once, White plays a4 to rule out ...b5, so that the pawn can be recaptured at leisure. Black uses the time to bring the light-squared bishop to c6 via d7, where it opposes the Catalan bishop on the long diagonal. The a4 push weakens b4, but makes it hard for Black to expand on the queenside."],"at":14,"moves":[["a4","Stops ...b5, so White can win back c4 in comfort."],["Bd7","The bishop heads for c6, where it will oppose White's bishop on the long diagonal."],["Qxc4","White regains the pawn."],["Bc6","The bishop blocks the long diagonal, opposing the Catalan bishop, and eyes the a4 pawn."],["Bg5","White develops and puts pressure on the knight on f6, a key defender of d5 and e4."]],"vars":[],"played":[723,595,478,480,300]},{"name":"Closed Catalan","summary":"Black keeps the pawn on d5 and builds a solid wall with ...c6 and ...b6.","idea":["Black declines to take on c4 and sets up a solid Queen's Gambit Declined structure with ...c6, ...b6 and ...Bb7. White gets a space advantage and plays for e4, often with Qc2, Nbd2 and b3 and Bb2. Black waits for the right moment to free the game with ...c5 or ...e5. It is very solid, but Black must be patient."],"at":11,"moves":[["Nbd7","Black keeps the pawn on d5 and prepares ...c6."],["Qc2","The queen covers c4 and e4, preparing to push e4."],["c6","Supports d5 and blunts the bishop on g2."],["Nbd2","The knight supports e4 and can recapture on c4 if needed."],["b6","Prepares ...Bb7, the only good square for the c8 bishop."],["e4","White strikes in the centre."],["Bb7","Black develops the bishop."],["b3","Protects c4 and prepares Bb2."],["Rc8","The rook goes to the c-file, preparing ...c5."],["Bb2","The bishop takes the long diagonal."],["Qc7","Black is ready for ...c5 or ...dxe4 to free the position. White keeps more space."]],"vars":[],"played":[119,94,54,63,69,68,12,2,1,1,1]},{"name":"Early 4...dxc4","summary":"Black takes on c4 before White can castle.","idea":["Black takes the pawn at once and uses the moves White needs to win it back. After 5.Nf3 the two main answers are 5...Bb4+, trading off White's dark-squared bishop and holding c4 with ...a5, ...c6 and ...b5, and 5...c5, opening the centre at once."],"at":7,"moves":[["dxc4","Black takes the pawn before White has castled."],["Nf3","White develops, preparing to win the pawn back."],["Bb4+","The check disrupts White's development: something must block."],["Bd2","White blocks with the bishop."],["a5","The pawn supports the bishop and gains queenside space."],["Qc2","The queen attacks c4."],["Bxd2+","Black trades bishops."],["Qxd2","White recaptures with the queen, keeping the knight free to go to c3 or a3."],["c6","Prepares ...b5 to hold the c4 pawn."],["a4","White gets ready to break up Black's pawns after ...b5."],["b5","Black defends c4."],["axb5","White takes."],["cxb5","Black recaptures, keeping the chain b5–c4."],["Qg5","A double attack on g7 and b5. The main line is 11...O-O 12.Qxb5 Ba6, where Black gives back the pawn for active pieces."]],"vars":[{"name":"The 5...c5 queen trade","summary":"Black opens the centre and gives the queen for rook, bishop and pawn.","idea":["Black hits d4 at once. After 7.Qa4, which pins the knight on c6 and threatens to win back c4, the main line leads to a forced sequence where Black gives the queen for a rook, a bishop and a pawn. Black's structure is solid and the bishop on c6 is strong, so the material imbalance is roughly balanced."],"at":9,"moves":[["c5","Black hits d4 at once."],["O-O","White castles first."],["Nc6","Black adds pressure on d4."],["Qa4","The queen pins the knight on c6 against the king and threatens to take on c4."],["cxd4","Black takes on d4."],["Nxd4","White recaptures, and the knight attacks the pinned knight on c6."],["Qxd4","Black takes the knight, accepting the check that follows."],["Bxc6+","The bishop checks, taking the knight with tempo."],["Bd7","Black blocks the check."],["Rd1","The rook attacks the queen."],["Qxd1+","Black gives the queen for the rook."],["Qxd1","White recaptures."],["Bxc6","Black has rook, bishop and pawn for the queen, a solid position and a strong bishop on the long diagonal."]],"vars":[],"played":[304,300,299,151,11,11,10,10,10,10,4,4,4]}],"played":[291,224,256,225,183,103,63,49,51,49,38,35,37,37]}],"played":[69153,44164,32832,22625,2194,1438,1057,368,366,2361,1731,1560,1196,790,56,206,206,206,41,7,4,3,3]},{"id":"benoni","name":"Modern Benoni","eco":"A60–A79","side":"b","group":"indian","summary":"An unbalanced pawn structure: Black gives White the centre for queenside play and active pieces.","idea":["After 2...c5 3.d5 e6 and the exchange on d5, the pawn structure is lopsided. White has a central majority, the d- and e-pawns, and will try to push e4–e5 to break through. Black has a queenside majority, the a-, b- and c-pawns, and wants to advance it with ...a6 and ...b5. Black's d6 pawn is backward, and White's knights often aim at it from c4 and e4.","Black's bishop on g7 is the key piece, raking down the long diagonal, and the rook on e8 pressures e4. Black accepts a slightly loose position for dynamic counterplay. White aims to stop ...b5 with a4 and then strike with e5 or f4–f5; Black aims to get ...b5 in anyway, or to use the e5 square for a knight. It is a fighting choice for players who want to win with Black; Tal and Kasparov played it."],"moves":[["d4","Takes a share of the centre and controls e5 and c5."],["Nf6","Develops and stops 2.e4."],["c4","Gains space and adds control of d5."],["c5","Black strikes at d4 from the side, challenging White to take, defend or push past."],["d5","White pushes past, gaining space; the pawn cramps Black but can become a target."],["e6","Black undermines d5 at once."],["Nc3","Supports d5."],["exd5","Black opens the e-file and creates the Benoni structure."],["cxd5","White now has a central majority, the d- and e-pawns; Black has the queenside majority."],["d6","Stops d6, which would cramp Black badly, and holds e5."],["e4","White builds the centre, with e5 as the long-term breakthrough."],["g6","The bishop goes to g7, where it is far more active than on e7: it controls e5 and rakes the long diagonal towards b2."],["Nf3","Develops and covers e5."],["Bg7","Black completes the fianchetto."],["Be2","The Classical Variation: solid development, preparing to castle."],["O-O","Black castles."],["O-O","White castles."],["Re8","The rook presses on e4, which makes the e5 push harder and ties White down."],["Nd2","The knight heads for c4 to press on d6, and the f-pawn is now free to support e4 with f3."],["Na6","The knight heads for c7, where it supports ...b5."],["f3","Secures e4 for good."],["Nc7","From c7 the knight supports ...b5 and hits d5."],["a4","White stops ...b5, Black's key queenside push, at least for now."],["b6","Black prepares ...Ba6, ready to challenge White's knight when it lands on c4, and keeps ...a6 and ...Rb8 in reserve to force ...b5 later."]],"vars":[{"name":"Taimanov Attack","summary":"White builds a big centre with f4 and checks on b5 to disrupt Black.","idea":["White plays f4 and, after ...Bg7, the check Bb5+ stops Black from developing normally. If Black blocks with the bishop or the b8 knight, White pushes e5 with great effect; the best answer is ...Nfd7, which keeps an eye on e5. White then threatens e5 and a kingside attack. It is considered one of the most dangerous lines against the Benoni."],"at":12,"moves":[["f4","White adds the f-pawn to the centre and prepares e5."],["Bg7","Black completes the fianchetto."],["Bb5+","The point: the check disrupts Black's development. Blocking with the bishop or the b8 knight allows a strong e5."],["Nfd7","The best block: the knight keeps watch over e5 and can go to c5 or b6."],["a4","Makes sure that ...a6 and ...b5 cannot drive the bishop away and gain queenside space with tempo."],["O-O","Black castles."],["Nf3","Develops and supports e5."],["Na6","The knight heads for b4, a square weakened by a4."],["O-O","White castles."],["Nb4","The knight lands on its outpost, eyeing d5 and c2. White will try e5 or f5; Black hopes to use b4 and the queenside."]],"vars":[],"played":[104,99,97,95,71,39,38,33,33,29]},{"name":"Modern Main Line: 8.h3","summary":"White stops ...Bg4 and develops the bishop on d3; Black answers with the ...b5 pawn sacrifice.","idea":["In the Benoni, Black would like to trade the light-squared bishop for the knight on f3 with ...Bg4, easing the cramp. With h3 White rules this out, then plays Bd3 and castles. Black's most energetic answer is to sacrifice the b-pawn at once with ...b5, using the moment before White castles to win back e4 with tactics on the e-file."],"at":14,"moves":[["h3","Takes g4 away from Black's bishop, so ...Bg4 and ...Bxf3 is off."],["O-O","Black castles."],["Bd3","The bishop protects e4 and aims at the kingside."],["b5","A pawn sacrifice: Black uses the moment before White has castled."],["Nxb5","White takes the pawn with the knight."],["Re8","The rook hits e4 with the king still on e1 behind it."],["O-O","White castles out of the pin."],["Nxe4","Black regains the pawn: Bxe4 is met by ...Rxe4. Material is level and Black has active play."]],"vars":[],"played":[23,88,49,34,26,19,19,19]},{"name":"Fianchetto Variation","summary":"White develops the bishop on g2, a quieter, positional line.","idea":["White develops with Nf3 and g3 and puts the bishop on g2, where it supports e4 and d5. It is less ambitious than e4 and f4 lines, but positionally sound. Black plays ...a6 and ...Nbd7, aiming for ...b5 and ...Re8, while White tries to stop the queenside majority with a4 and bring a knight to c4."],"at":10,"moves":[["Nf3","White develops and leaves e4 for later."],["g6","Black prepares the fianchetto."],["g3","White fianchettoes as well."],["Bg7","The bishop takes the long diagonal."],["Bg2","The bishop supports d5 and e4 from g2."],["O-O","Black castles."],["O-O","White castles."],["a6","Prepares ...b5, Black's queenside expansion."],["a4","Stops ...b5."],["Nbd7","The knight heads for e5 or c5 and keeps ...Rb8 and ...b5 in mind."]],"vars":[],"played":[167,456,38,68,69,292,299,37,37,15]},{"ref":"benko-gambit","at":5,"name":"Benko Gambit","summary":"Black gives the b-pawn with 3...b5 to open queenside files."}],"played":[69153,44164,32832,1234,1139,360,346,396,396,383,211,214,32,64,25,32,17,14,14,29,19,14,14,23]},{"id":"benko-gambit","name":"Benko Gambit","eco":"A57–A59","side":"b","group":"indian","summary":"Black gives a queenside pawn for lasting pressure down the a- and b-files.","idea":["Black sacrifices the b-pawn to open the a- and b-files. After White takes twice, the bishop recaptures on a6 and the rooks, queen and the bishop on g7 all bear down on White's queenside, on a2 and b2. The compensation is long-term rather than tactical: Black does not have to attack the king; even in the endgame the pressure often wins the pawn back.","White is a pawn up and has a big centre, and aims to consolidate, keep the queenside safe and push e4–e5 at the right moment. If White plays e4, Black trades the light-squared bishops with ...Bxf1, and White must castle by hand with g3 and Kg2. Typical Black moves are ...Qa5, ...Rfb8, ...Nbd7–b6 and ...Ne8–c7–b5."],"moves":[["d4","Takes a share of the centre and controls e5 and c5."],["Nf6","Develops and stops 2.e4."],["c4","Gains space and adds control of d5."],["c5","Black strikes at d4 from the side."],["d5","White pushes past, gaining space."],["b5","The Benko Gambit: Black offers the b-pawn to open the queenside files."],["cxb5","White accepts."],["a6","Black offers to open the a-file too: if White takes, the bishop recaptures and develops with tempo."],["bxa6","White accepts again."],["Bxa6","The bishop lands on a6, covering f1 and ready to trade off White's light-squared bishop."],["Nc3","Develops, protecting d5 and preparing e4."],["d6","Supports c5 and opens the way for the queen's pieces; ...g6 and ...Bg7 come next."],["e4","White builds the centre, but allows ...Bxf1, which costs White the right to castle."],["Bxf1","Black trades the light-squared bishops."],["Kxf1","The king recaptures and can no longer castle."],["g6","Black prepares to fianchetto."],["g3","White prepares to castle by hand with Kg2."],["Bg7","The bishop on the long diagonal joins the pressure on the queenside."],["Kg2","White's king is safe on g2: castling by hand is complete."],["O-O","Black castles."],["Nf3","White develops the last minor piece."],["Nbd7","The knight heads for b6 or e5. Black follows with ...Qa5, ...Rfb8 and ...Ra7, piling up on a2 and b2; White aims for e5 or a safe queenside with Qc2 and Rb1."]],"vars":[{"name":"Zaitsev Variation","summary":"White declines the second pawn and plays e4 at once.","idea":["White does not take on a6, and instead plays for quick development and e4. Black regains the pawn with ...axb5, and after e4 the b-pawn kicks the knight, which jumps to b5. Material is level; White has active pieces, Black has a healthy queenside pawn mass and a lead on the queenside files."],"at":8,"moves":[["Nc3","White declines the second pawn and develops quickly."],["axb5","Black regains the pawn."],["e4","White threatens e5 and Nxb5."],["b4","The pawn kicks the knight and stops it from taking on b5."],["Nb5","The knight jumps forward rather than retreat, eyeing d6 and c7."],["d6","Black takes d6 away from the knight and covers e5. Material is level and the position is sharp."]],"vars":[],"played":[1,3,1,1,1,1]},{"name":"Fianchetto Variation","summary":"White fianchettoes and keeps the right to castle.","idea":["Instead of e4, White plays Nf3, g3 and Bg2, so that ...Bxf1 never happens and White castles normally. The centre is less ambitious, but White is very solid. Black carries on with the usual plan: ...g6, ...Bg7, castling, ...Nbd7, ...Qa5 or ...Qb6 and ...Rfb8, pressing on the queenside."],"at":12,"moves":[["Nf3","White develops and plans the fianchetto, keeping the right to castle."],["g6","Black prepares the fianchetto as well."],["g3","White will put the bishop on g2."],["Bg7","The bishop takes the long diagonal."],["Bg2","The bishop protects the king and supports d5 and a later e4."],["O-O","Black castles."],["O-O","White castles normally, which is the point of this line."],["Nbd7","The knight heads for b6 or e5. Black continues with ...Qa5 or ...Qb6 and ...Rfb8 against White's queenside."]],"vars":[],"played":[5,4,1,1,3,1,4,6]},{"ref":"benoni","at":5,"name":"Modern Benoni","summary":"Black plays 3...e6 instead, for the Modern Benoni structure."}],"played":[69153,44164,32832,1234,1139,476,388,387,209,35,33,13,7,7,7,7,18,18,18,17,17,31]},{"id":"dutch","name":"Dutch Defence","eco":"A80–A99","side":"b","group":"indian","summary":"Black fights for e4 with the f-pawn: an aggressive, unbalancing answer to 1.d4.","idea":["With 1...f5 Black takes control of e4 at once and stakes out kingside space, aiming for a fighting game rather than symmetry. The price is a slight loosening of Black's king, especially on the e8–h5 diagonal, and so White usually fianchettoes the king's bishop to fight for e4 and the long diagonal.","Black chooses between three main set-ups. In the Leningrad, Black fianchettoes with ...g6 and ...Bg7, plays ...d6 and aims for ...e5: a King's Indian with the f-pawn already on f5, with Black pushing on the kingside and White expanding on the queenside. In the Stonewall, Black puts pawns on c6, d5, e6 and f5 and grabs e4 for a knight, at the cost of a hole on e5 and a bad light-squared bishop. The Classical uses ...e6, ...Be7 and ...d6, with the queen going to e8 and then h5 or g6.","White's plans are to break with e4, to exploit the holes on e5 or e6, or to gain space on the queenside with b4 and c5. Sharp anti-Dutch tries such as the Staunton Gambit, 2.e4, try to punish Black before the set-up is complete."],"moves":[["d4","White occupies the centre and controls e5 and c5."],["f5","The Dutch: Black controls e4 from the start and keeps the game unbalanced."],["c4","White gains queenside space and controls d5, as against most defences to 1.d4."],["Nf6","Black develops and adds a second guard to e4."],["g3","White prepares to fianchetto; the bishop on g2 will contest e4 and the long diagonal."],["g6","The Leningrad: Black prepares ...Bg7, a King's Indian set-up with the f-pawn already on f5."],["Bg2","The bishop takes the long diagonal, where it contests e4 and d5."],["Bg7","Black's bishop takes the matching long diagonal, guarding the king and later supporting ...e5."],["Nf3","White develops and covers e5, making Black's ...e5 break harder."],["O-O","Black castles; the king is safe behind the fianchetto even though the f-pawn has advanced."],["O-O","White castles too."],["d6","Black controls e5 and prepares the break ...e5, the main way to fight for the centre."],["Nc3","White develops, adds control of e4 and d5, and gets ready for e4 one day."],["Qe8","The Leningrad main line. The queen leaves the d-file and backs up the ...e5 break; from e8 it can also join the kingside via f7."],["d5","White gains space and takes c6 and e6 away from Black's pieces; if Black plays ...e5, dxe6 en passant follows."],["a5","Black stops b4 and prepares ...Na6 and ...Nc5, where the knight cannot easily be driven away by a pawn."],["Nd4","The knight centralises, eyes e6, b5 and the f5 pawn, and opens the long diagonal for the bishop on g2."],["Na6","The knight heads for c5 or b4, outposts made safe by ...a5. Black's play will come from ...c6 or ...e5 and from the kingside."]],"vars":[{"name":"Stonewall Dutch","summary":"Black builds a wall of pawns on c6, d5, e6 and f5 and grabs the e4 square.","idea":["Black sets up the pawns on light squares, makes e4 a permanent outpost for a knight and keeps the option of a kingside attack with ...Qe8–h5, ...g5 or a rook lift via f6. The price is the hole on e5 and the light-squared bishop on c8, which is shut in behind its own pawns. White's standard plan is to trade off Black's good dark-squared bishop with b3 and Ba3 (or with Bf4), then aim a knight at e5 and look for play on the queenside."],"at":5,"moves":[["e6","Black opens the diagonal of the f8 bishop and keeps both ...d5 and ...d6 in reserve."],["Bg2","The bishop takes the long diagonal, aiming at e4 and d5."],["d5","The Stonewall begins: together with f5, the d5 pawn takes e4 firmly under control and stops White playing e4 for a long time."],["Nf3","White develops and keeps an eye on e5, the hole in Black's position."],["c6","The last stone in the wall: c6 supports d5, so that cxd5 can be met by ...cxd5 or ...exd5."],["O-O","White castles; there is no hurry, since the central structure is fixed."],["Bd6","The bishop takes its best diagonal, where it covers e5 and points at h2."],["b3","White prepares Ba3 to exchange the d6 bishop, Black's best minor piece, and supports c4."],["Qe7","The queen backs up the bishop on the f8–a3 diagonal, so that Ba3 can be met by an exchange of bishops or by recapturing on d6 with the queen."],["Ba3","White offers the trade of dark-squared bishops. Without that bishop, Black's e5 hole and dark squares are harder to cover."],["Bxa3","Black accepts the trade; the knight that recaptures will be on the edge of the board for a while."],["Nxa3","The knight recaptures and will come back into play via c2."],["O-O","Black castles. Black will play ...Nbd7, ...Ne4 and often ...b6 and ...Bb7 to solve the problem of the c8 bishop, while White aims to take over e5 and the dark squares."]],"vars":[{"name":"Classical Dutch (Ilyin-Zhenevsky)","summary":"Black keeps the d-pawn flexible with ...d6 and brings the queen to the kingside via e8.","idea":["Black develops with ...Be7 and ...d6, so that e5 is covered and ...e5 becomes a possible break. The queen goes to e8 and then h5 or g6 to support a kingside attack. White's main plan is to play e4, often prepared by Re1 or Qc2, which opens the centre while Black's queen is far from the queenside."],"at":7,"moves":[["Be7","A modest square: the bishop guards the king and leaves the d-pawn free to go to d6."],["Nf3","White develops and keeps watch on e5."],["O-O","Black castles, getting the king off the e8–h5 diagonal."],["O-O","White castles."],["d6","The Classical set-up: d6 covers e5 and prepares ...e5 to fight for the centre."],["Nc3","White develops and prepares e4 to break open the centre."],["Qe8","The Ilyin-Zhenevsky manoeuvre: the queen heads for h5 or g6 to support a kingside attack, and it also backs up ...e5."]],"vars":[],"played":[45,33,37,34,49,50,23]}],"played":[20,116,54,29,27,38,42,37,34,0,0,0,0]},{"name":"Staunton Gambit","summary":"White gives a pawn to open the centre before Black's set-up is ready.","idea":["White strikes at e4 immediately. After 2...fxe4 White hopes to win the pawn back on e4, or to get rapid development and open lines against Black's king, which is loosened by the missing f-pawn. The key idea is Bg5 to remove the knight on f6, the defender of e4. Black must combine development with care for the king, and counterattacking d4 with ...Nc6 is one of the most testing replies."],"at":2,"moves":[["e4","The Staunton Gambit: White offers the e-pawn to open lines against Black's king."],["fxe4","Black takes. The pawn on e4 will be the focus of the fight."],["Nc3","White develops and attacks e4."],["Nf6","Black defends e4 with a developing move."],["Bg5","White threatens Bxf6 to remove the defender of e4, followed by Nxe4 with a strong centre."],["Nc6","Black counterattacks d4 instead of defending e4 passively."],["d5","White gains space and drives the knight away."],["Ne5","The knight jumps to a central square, where it covers f3, d3 and c4."],["Qd4","The queen attacks the knight on e5 and the pawn on e4 at once."],["Nf7","The knight retreats with a gain of time against the bishop on g5. After Bxf6 exf6 and Nxe4 White usually wins the pawn back, with the d5 pawn cramping Black."]],"vars":[],"played":[31,31,31,29,27,5,5,5,1,1]},{"name":"Leningrad: 7...Nc6","summary":"Black develops the knight to c6 and, after d5, sends it to a5 to attack c4.","idea":["Instead of preparing ...e5 with the queen, Black develops a knight and puts pressure on d4. White usually gains space with d5, and the knight goes to a5, where it attacks the c4 pawn and supports queenside play with ...c5, ...a6, ...Rb8 and ...b5. White must look after c4 and will try to show that the knight on a5 is offside."],"at":13,"moves":[["Nc6","Black develops and hits d4, which is protected by the knight on f3 and the queen."],["d5","White gains space with tempo, driving the knight from c6."],["Na5","From the edge of the board the knight attacks c4 and supports queenside play."],["Qd3","White protects c4 with the queen."],["c5","Black gains space. If White takes en passant with dxc6, Black recaptures with the knight and has active pieces; otherwise ...a6, ...Rb8 and ...b5 follow."]],"vars":[],"played":[54,48,8,3,2]}],"played":[69153,976,200,210,68,42,41,63,30,75,62,157,194,42,17,3,1,1]},{"id":"english","name":"English Opening","eco":"A10–A39","side":"w","group":"flank","summary":"White starts with the c-pawn, controlling d5 from the flank: flexible, positional and full of transpositions.","idea":["1.c4 controls d5 without committing the centre pawns, keeping options for a slow positional game. White usually fianchettoes the king's bishop on g2, where it works with the c-pawn against d5 and along the long diagonal, and decides later between d3, d4 or e4.","Against 1...e5 White is playing a Sicilian with colours reversed and an extra tempo. In the Four Knights main line Black takes the centre with ...d5, and after cxd5 Nxd5 the position is a Dragon reversed: White's bishop on g2 presses down the long diagonal, and White aims for queenside expansion with a3, b4 and b5 to attack the knight on c6 and the e5 pawn behind it. Black has a broad centre and plays for piece activity and a kingside initiative.","Black has many other set-ups: copying White with 1...c5 (the Symmetrical English), the Hedgehog with ...b6 and ...e6, or transposing to d4 openings with ...Nf6, ...e6 and ...d5. The English rewards understanding of pawn structures more than memorised lines."],"moves":[["c4","The English: the c-pawn controls d5 from the flank and keeps White's centre pawns flexible."],["e5","Black takes the centre at once: a Sicilian with colours reversed."],["Nc3","The knight adds a second guard on d5 and covers e4, the central squares Black would like to use."],["Nf6","Black develops and prepares ...d5 or ...Bb4, fighting for the same squares."],["Nf3","White develops with a threat on e5, forcing Black to defend it."],["Nc6","Black defends e5 with a developing move: this is the Four Knights English."],["g3","White prepares Bg2, the bishop that works on the long diagonal in most English lines."],["d5","Black seizes the centre, accepting a Dragon set-up with colours reversed."],["cxd5","White trades a wing pawn for a centre pawn, as Black does in the Sicilian."],["Nxd5","The knight recaptures and stands well in the centre, but White's pieces are aimed at it."],["Bg2","White completes the fianchetto. The bishop is blocked by the f3 knight for now, but the long diagonal opens as soon as the knight moves."],["Nb6","Black avoids the exchange Nxd5 and steps back to b6, where the knight covers c4 and d5."],["O-O","White castles; the king is safe behind the fianchetto."],["Be7","Black develops quietly and prepares to castle, keeping a solid centre."],["d3","White opens the c1 bishop and covers c4 and e4, keeping Black's knights out."],["O-O","Black castles. Both sides have finished the first stage of development."],["a3","White prepares b4, the main queenside plan in this structure."],["Be6","Black develops the last minor piece, covering d5 and c4."],["b4","The queenside expansion: b5 is threatened, driving the knight from c6 so that the e5 pawn loses its defender."]],"vars":[{"name":"Four Knights: 4...Bb4","summary":"Black develops the bishop to b4 to exchange it for the c3 knight and fight for e4.","idea":["Black is ready to give up the bishop for the knight on c3, a key defender of d5 and e4, and to push ...e4 to gain space and drive White's knight from f3. White usually castles, allows the exchange and gets the bishop pair and a half-open b-file in return for doubled c-pawns. The fight is about the e4 pawn, which White tries to undermine with d3 or f3."],"at":7,"moves":[["Bb4","The bishop eyes the c3 knight, ready to trade it so that Black can gain space with ...e4."],["Bg2","White completes the fianchetto."],["O-O","Black castles first; ...e4 is coming."],["O-O","White castles too."],["e4","Black gains space and drives the knight from f3."],["Ng5","The knight attacks e4, joining the knight on c3 and the bishop on g2, whose diagonal is now open."],["Bxc3","Black removes one of the attackers."],["bxc3","White recaptures towards the centre, gaining the bishop pair and the half-open b-file."],["Re8","The rook defends e4 a second time, so it holds for now."],["f3","White hits e4 again to open the f-file. Black's main replies are 9...exf3, and the pawn sacrifice 9...e3, which keeps the f-file closed and leaves a thorn in White's position."]],"vars":[],"played":[132,70,56,39,23,16,16,16,18,11]},{"name":"Symmetrical English","summary":"Black copies White's first move and fights for d4 the way White fights for d5.","idea":["In the Symmetrical English both sides control the centre from the flanks. In the main line with double fianchettos the play is subtle: White usually breaks the symmetry with d4 to open the long diagonal and the d-file, using the extra tempo, while Black waits for the right moment to strike back with ...d6 or ...d5. White keeps a small but lasting initiative, and Black has a very solid position."],"at":1,"moves":[["c5","Black copies White and controls d4 from the flank."],["Nf3","White develops and prepares d4 to break the symmetry."],["Nf6","Black develops and covers d5 and e4."],["Nc3","The knight adds control of d5 and e4."],["Nc6","Black keeps copying, adding pressure on d4."],["g3","White prepares the fianchetto, the bishop's best diagonal in English structures."],["g6","Black does the same: the fully symmetrical set-up."],["Bg2","The bishop goes to the long diagonal, which will open once the knight on f3 moves."],["Bg7","Black's bishop mirrors it."],["O-O","White castles."],["O-O","Black castles."],["d4","White breaks the symmetry and opens the centre while a move ahead."],["cxd4","Black exchanges, opening the c-file."],["Nxd4","The knight recaptures and opens the long diagonal, so the bishop on g2 now aims at c6 and b7. The main line goes 8...Nxd4 9.Qxd4 d6, with a slight edge for White."]],"vars":[{"name":"The Hedgehog","summary":"Black sets up pawns on a6, b6, d6 and e6 and waits, coiled and ready to strike back.","idea":["Black lets White take space in the centre, then sets up a compact position with pawns on the sixth rank and bishops on b7 and e7. It looks passive, but every black piece is ready for the freeing breaks ...b5 and ...d5, and White, who has more space, must be careful not to overextend. It is a long, strategic fight."],"at":5,"moves":[["e6","Black keeps the centre flexible, ready for ...d5, or for ...b6 and ...Bb7."],["g3","White fianchettoes, the usual English plan."],["b6","Black prepares to fianchetto on b7, opposing White's bishop on the long diagonal."],["Bg2","The bishop takes the long diagonal."],["Bb7","Black's bishop faces White's and controls e4."],["O-O","White castles."],["Be7","Black prepares to castle and keeps the bishop flexible."],["d4","White opens the centre to make use of the extra space."],["cxd4","Black exchanges a wing pawn for a centre pawn."],["Qxd4","The queen recaptures, keeping the knight on f3 and taking up a central post; there is no black knight on c6 to harass it."],["d6","The Hedgehog: Black will add ...a6, ...Nbd7 and ...Qc7, and wait for the right moment for ...b5 or ...d5."]],"vars":[],"played":[233,164,95,93,93,106,167,95,90,87,47]}],"played":[1584,775,593,861,483,278,91,82,68,47,51,68,47,47]},{"name":"Flohr–Mikenas Attack","summary":"Against 1...Nf6 and ...e6 White plays e4 at once, leading to a sharp, open fight.","idea":["After 1...Nf6 2.Nc3 e6 White could transpose to the Queen's Gambit or the Nimzo-Indian with d4, but 3.e4 tries for more by taking the centre directly. If Black hits back with ...d5, White chases the knight with e5 and the game becomes tactical. In the main line White ends up with doubled c-pawns but a strong centre and free development."],"at":1,"moves":[["Nf6","Black develops and keeps options open: the game may still become a Nimzo-Indian, Queen's Indian or King's Indian."],["Nc3","White develops and supports e4."],["e6","Black prepares ...d5 or ...Bb4."],["e4","The Flohr–Mikenas Attack: White takes the centre at once, before ...d5."],["d5","Black strikes back at e4."],["e5","White gains space and attacks the knight."],["d4","The counter: Black attacks the knight on c3 in return."],["exf6","White takes the knight."],["dxc3","Black takes back a piece."],["bxc3","White recaptures towards the centre; Black will now win back the f6 pawn."],["Qxf6","Black regains the pawn. Material is level, and Black's queen is active."],["d4","White builds a centre with pawns on c3 and d4 and frees the c1 bishop. Black will challenge it with ...c5 or ...e5."]],"vars":[],"played":[3335,1927,372,300,189,89,84,84,84,79,78,30]}],"played":[14806,3458,1728,849,1177,1083,377,186,186,186,184,84,160,181,47,57,30,21,10]},{"id":"reti","name":"Réti Opening","eco":"A04–A09","side":"w","group":"flank","summary":"White develops the knight and hits d5 from the flank with c4: a hypermodern opening full of transpositions.","idea":["The Réti is the hypermodern opening par excellence: White does not occupy the centre with pawns but controls it from a distance, with the knight on f3, the c-pawn hitting d5 and bishops fianchettoed on g2 and often b2. Black's central pawns become targets rather than a secure base.","Against 1...d5 2.c4 Black must decide how to handle the attack on d5: support it with ...e6 or ...c6, advance with ...d4 to gain space, or take on c4. In the main line with ...e6, White double-fianchettoes and keeps the tension, and the game often resembles a Queen's Gambit or an English in which White has extra options. Typical plans are a timely cxd5 to leave Black with isolated or hanging pawns, followed by d4, or a set-up with d3 and e4."],"moves":[["Nf3","White develops and controls e5 and d4 without committing the centre pawns."],["d5","Black takes the centre with the d-pawn."],["c4","The Réti: White attacks d5 from the flank, inviting Black to defend it, push past it or take on c4."],["e6","Black supports d5 solidly, as in the Queen's Gambit Declined."],["g3","White prepares the fianchetto; the bishop on g2 will aim at the centre along the long diagonal."],["Nf6","Black develops, adds a guard to d5 and controls e4."],["Bg2","The bishop takes the long diagonal."],["Be7","Black develops modestly, preparing to castle."],["O-O","White castles."],["O-O","Black castles."],["b3","The second fianchetto: b3 supports c4, so ...dxc4 can be met by bxc4, and prepares Bb2."],["c5","Black takes more space and fights for d4, using the c-pawn just as White does."],["Bb2","The bishop controls the long diagonal from the queenside, aiming at d4, e5 and the knight on f6."],["Nc6","Black develops and adds control of d4 and e5."],["e3","White covers d4, so Black's pawns cannot easily advance there, and opens e2 for the queen."],["b6","Black prepares ...Bb7. White will play Nc3, cxd5 and d4 to pressure Black's centre, while Black aims for ...Bb7 and possibly ...d4 to gain space."]],"vars":[{"name":"Réti Advance: 2...d4","summary":"Black gains space with ...d4, a reversed Benoni-type position.","idea":["Black pushes past the c4 pawn and grabs space in the centre, cramping White's queen's knight. White attacks the d4 pawn with e3, or plays g3 and b4 to undermine it from the flank. In the line below White opens the centre with e3 and exd4, trades knights and then gains time on Black's centralised queen."],"at":3,"moves":[["d4","Black gains space, taking c3 and e3 away from White's pieces."],["e3","White hits the advanced pawn at once."],["Nc6","Black supports d4 with a developing move."],["exd4","White trades, opening the e-file."],["Nxd4","Black recaptures with the knight, which stands well in the centre."],["Nxd4","White exchanges knights, so that Black has to recapture with the queen."],["Qxd4","The queen is centralised, but it can be attacked with gain of time."],["Nc3","White develops and threatens Nb5, which would attack the queen and c7. Next come d3 and Be3, gaining more time on the queen."]],"vars":[],"played":[303,45,31,15,15,14,14,12]},{"name":"Réti Accepted: 2...dxc4","summary":"Black takes on c4 and White wins the pawn back, often reaching a Queen's Gambit Accepted.","idea":["Black gives up the centre to gain time. White regains the pawn easily, and with e3, Bxc4 and d4 the game transposes to the main line of the Queen's Gambit Accepted. Black gets free development; White has an easy game with a slight space advantage."],"at":3,"moves":[["dxc4","Black takes the pawn, giving up the centre for free development."],["e3","White opens the bishop's diagonal to win back the c4 pawn."],["Nf6","Black develops rather than trying to hold the pawn."],["Bxc4","White regains the pawn with a well-placed bishop."],["e6","Black opens the f8 bishop and prepares to castle."],["O-O","White castles."],["c5","Black claims d4 with the c-pawn, the standard freeing move in this structure."],["d4","White takes the centre: the position is now a main line of the Queen's Gambit Accepted."],["a6","Black prepares ...b5 to gain time on the bishop and fianchetto on b7. White plays for the centre and e4, Black for quick queenside development."]],"vars":[],"played":[31,17,14,44,43,28,13,4,458]},{"name":"Slav set-up: 2...c6","summary":"Black supports d5 with ...c6 and develops the light-squared bishop to f5 before ...e6.","idea":["Black builds the Slav triangle c6–d5–e6, but brings the bishop out to f5 first so that it is not shut in. White fianchettoes and plays b3 and Bb2, keeping the tension; later White can play d3, Nbd2 and e4, or d4, to fight for the centre. It is one of the most solid ways for Black to meet the Réti."],"at":3,"moves":[["c6","Black supports d5 with the c-pawn, keeping the c8 bishop's path open."],["g3","White prepares the fianchetto."],["Nf6","Black develops and controls e4."],["Bg2","The bishop takes the long diagonal."],["Bf5","Black develops the bishop outside the pawn chain before playing ...e6."],["O-O","White castles."],["e6","Black completes the triangle c6–d5–e6 and opens the f8 bishop."],["b3","White supports c4 and prepares Bb2: the double fianchetto."],["Nbd7","Black develops the knight where it can support ...e5 or ...Ne4 later."],["Bb2","The bishop on b2 controls e5 and the long diagonal."],["h6","A useful prophylactic move: if White plays Nh4 to hunt the f5 bishop, it can retreat to h7 and stay on its diagonal."]],"vars":[],"played":[190,234,163,226,83,23,66,2,3,3,1]}],"played":[21523,9809,1024,500,651,444,1271,1162,914,1353,692,215,53,35,20,24]},{"id":"kings-indian-attack","name":"King's Indian Attack","eco":"A07–A08, C00","side":"w","group":"flank","summary":"White sets up a King's Indian with colours reversed (Nf3, g3, Bg2, d3, e4) and attacks on the kingside.","idea":["The King's Indian Attack is a system rather than a sequence of moves: White plays Nf3, g3, Bg2, O-O, d3, Nbd2 and e4 against almost anything. It is a King's Indian Defence with colours reversed and an extra tempo, and it lets White avoid a great deal of opening theory.","It is at its best against set-ups with ...e6 and ...d5, such as the French or a Sicilian with ...e6. White pushes e5 to gain space and cramp Black's kingside, then brings the pieces over with Re1, Nf1–h2–g4, h4–h5 and Bf4, aiming for a direct attack on the king. Black plays on the other wing with ...c5, ...b5, ...b4 and ...a5–a4, trying to open lines before White's attack lands. It is a race.","If Black stops the e5 push, for example with ...Bd6 and ...Nge7, or with a ...g6 fianchetto and ...d6, White changes plans: Nh4 and f4, or c3 and d4, or exd5 to open the position."],"moves":[["e4","White starts with the king's pawn; the King's Indian Attack set-up comes next."],["e6","The French Defence: Black prepares ...d5."],["d3","The King's Indian Attack: instead of d4, White supports e4 with the d-pawn and plans Nd2, Ngf3, g3 and Bg2."],["d5","Black takes the centre as in the French."],["Nd2","The knight protects e4, so White need not exchange on d5. On d2 it leaves the c-pawn free, and later it can go to f1 and on to h2 or e3."],["Nf6","Black develops and adds pressure on e4."],["Ngf3","White develops the other knight, which covers e5 and supports the later e5 push."],["c5","Black grabs queenside space: that is the side where Black will play."],["g3","White prepares Bg2, the bishop of the King's Indian set-up."],["Nc6","Black develops and controls d4 and e5."],["Bg2","The bishop goes to g2, where it guards the king and later supports play in the centre."],["Be7","Black develops modestly and prepares to castle."],["O-O","White castles."],["O-O","Black castles. This is the main position of the King's Indian Attack against a French set-up."],["Re1","The rook backs up the e-pawn, preparing e5."],["b5","Black begins the queenside expansion: ...b4 and ...a5–a4 will follow."],["e5","White gains space and drives the f6 knight away from the defence of Black's king."],["Nd7","The knight retreats; from d7 it hits e5, and with ...Qc7 Black can add more pressure on that pawn."],["Nf1","The knight heads for h2 and g4, or for e3, to join the kingside attack."],["a5","Black continues on the queenside, preparing ...a4 and ...b4."],["h4","White gains kingside space and rules out ...g5, so a bishop on f4 cannot be driven away; h5 and N1h2–g4 will follow."],["b4","Black gains more space; ...a4 and ...a3 will try to open lines on the queenside. Both sides are racing."]],"vars":[{"name":"Against the Sicilian","summary":"The same set-up against 1...c5, here with Black fianchettoing the king's bishop.","idea":["Against the Sicilian the King's Indian Attack avoids the open lines that follow 2.Nf3 and 3.d4. After 2...e6 3.d3, if Black plays ...d5 and ...Nf6 the game transposes to the French line, but Black can also fianchetto with ...g6, ...Bg7 and ...Nge7, a set-up in which White's e5 push is not available. White then usually prepares c3 and d4 to fight for the centre, leading to a closed, manoeuvring game."],"at":1,"moves":[["c5","The Sicilian: Black fights for d4 from the flank."],["Nf3","White develops; the d3 set-up comes next."],["e6","Black prepares ...d5, or keeps the centre flexible."],["d3","The King's Indian Attack: White supports e4 with a pawn and plans g3 and Bg2."],["Nc6","Black develops and controls d4."],["g3","White prepares the fianchetto."],["g6","Black fianchettoes too, aiming the bishop at d4 and along the long diagonal."],["Bg2","The bishop takes its diagonal."],["Bg7","Black's bishop now presses on d4 and on the b2 pawn."],["O-O","White castles."],["Nge7","The knight develops behind the pawns, where e5 cannot hit it, and keeps the f-pawn free to advance."],["Re1","The rook supports the centre, ready for e5 or for c3 and d4."],["d6","Black covers e5 for good. White will play c3 and d4; Black castles and plays ...e5 or ...b5."]],"vars":[],"played":[37714,32686,7632,207,190,180,47,36,42,37,33,16,5]},{"name":"Black stops e5: ...Bd6 and ...Nge7","summary":"Black puts the bishop on d6 and the knight on e7 so that White's e-pawn cannot advance.","idea":["The e5 plan does not work if Black covers the square in advance. With ...Bd6 and ...Nge7 Black controls e5 and keeps the f-pawn free for ...f6 or ...f5. White switches plans: Nh4 and f4 to fight for e5 again, or Re1 with c3 and exd5 to open the position."],"at":5,"moves":[["c5","Black grabs queenside space before deciding where the kingside pieces go."],["Ngf3","White develops the knight."],["Nc6","Black develops and controls d4 and e5."],["g3","White prepares the fianchetto."],["Bd6","The bishop covers e5, so White's usual e5 push would just lose the pawn."],["Bg2","The bishop takes the long diagonal."],["Nge7","The knight develops without blocking the f-pawn, and it cannot be hit by e5."],["O-O","White castles."],["O-O","Black castles. White's plans are Nh4 and f4, or Re1, c3 and exd5 to open lines."]],"vars":[],"played":[48,35,46,46,29,29,28,29,28]},{"name":"The 1.Nf3 move order","summary":"White starts with 1.Nf3 and reaches the same set-up, though Black has more ways to avoid it.","idea":["The King's Indian Attack can be reached from 1.Nf3 as well as from 1.e4. Against 1...d5 White plays g3, Bg2, O-O, d3 and Nbd2 and only then e4, and if Black sets up with ...c5, ...Nc6, ...e6 and ...Nf6 the main line arises. The 1.Nf3 order avoids the Sicilian and the French, but lets Black choose other set-ups, such as ...Bg4 or ...Bf5 before ...e6."],"at":0,"moves":[["Nf3","White develops and keeps every set-up available."],["d5","Black takes the centre."],["g3","White commits to the King's Indian Attack set-up."],["c5","Black grabs space on the queenside."],["Bg2","The bishop takes the long diagonal."],["Nc6","Black develops and controls d4 and e5."],["O-O","White castles early, a typical feature of this system."],["e6","Black chooses a solid French-style structure."],["d3","White prepares e4."],["Nf6","Black develops."],["Nbd2","The knight will support e4."],["Be7","Black prepares to castle."],["e4","White finally plays e4, attacking d5."],["O-O","Black castles, and the position is exactly the main line after 7...O-O."]],"vars":[],"played":[21523,9809,5040,427,416,217,40,1,2,2,70,57,87,107]}],"played":[94897,8906,314,261,187,112,91,18,27,19,51,75,84,107,183,82,57,54,57,31,27,9]},{"id":"birds","name":"Bird's Opening","eco":"A02–A03","side":"w","group":"flank","summary":"White opens with 1.f4, controlling e5: a Dutch Defence with colours reversed.","idea":["1.f4 grabs e5 and kingside space, the same idea as the Dutch Defence but with an extra tempo. White usually continues with Nf3, e3 and a queenside fianchetto with b3 and Bb2, so the bishop and the f-pawn together control e5. The king's bishop goes to e2 or d3, and the plan is a kingside attack: the queen can go to e1 and then h4, and a knight can jump into e5.","Black's main approaches are a set-up with ...d5, ...Nf6 and ...g6, often followed by ...c5 and ...d4 to shut out the b2 bishop, or an immediate challenge with 1...e5, From's Gambit, a sharp pawn sacrifice aimed at White's weakened king. The downside of 1.f4 is exactly that loosened king position, above all the e1–h4 diagonal, which Black will try to exploit."],"moves":[["f4","Bird's Opening: the f-pawn controls e5 and gains kingside space."],["d5","Black takes the centre, as White does against the Dutch."],["Nf3","White develops, adds control of e5 and covers h4, guarding the weakened e1–h4 diagonal."],["Nf6","Black develops and controls e4."],["e3","White supports f4 and d4 and frees the f1 bishop."],["g6","Black prepares to fianchetto, so the bishop on g7 will oppose White's queenside bishop on the long diagonal."],["b3","White prepares Bb2 to control e5 and the long diagonal."],["Bg7","The bishop takes the long diagonal and guards the king."],["Bb2","The bishop controls d4 and e5 along the long diagonal."],["O-O","Black castles."],["Be2","A modest but flexible square: the bishop prepares castling and can later go to b5 or f3."],["c5","Black gains queenside space and prepares ...Nc6 and ...d4 to block White's bishop on b2."],["O-O","White castles."],["Nc6","Black develops; the ...d4 push is now well supported."],["Qe1","The typical Bird manoeuvre: the queen heads for h4 or g3 to support a kingside attack."]],"vars":[{"name":"From's Gambit","summary":"Black gives a pawn to open lines against White's weakened king.","idea":["After 2.fxe5 d6 3.exd6 Bxd6 Black is a pawn down but has rapid development and a bishop aimed at h2 and g3, where White's king is weak. The plan is ...g5–g4 to drive away the f3 knight, the main defender, and then ...Qh4+. White must defend accurately, and the sharpest lines need real knowledge. White can also avoid the gambit by answering 1...e5 with 2.e4, which transposes to the King's Gambit."],"at":1,"moves":[["e5","From's Gambit: Black offers the e-pawn to open lines towards White's king."],["fxe5","White accepts."],["d6","Black offers a second pawn to open the diagonal of the f8 bishop."],["exd6","White takes again."],["Bxd6","The bishop recaptures and aims at g3 and h2. Black threatens ...Qh4+ and then mate."],["Nf3","The only good defence: the knight covers h4, so ...Qh4+ is not possible."],["g5","Black threatens ...g4 to drive away the knight, after which ...Qh4+ would be deadly."],["d4","White grabs the centre and prepares to meet ...g4 with Ne5 or Ng5; 5.g3 is the other main move."],["g4","Black kicks the knight. After 6.Ne5 or 6.Ng5 the play is very sharp, and both sides must know the theory."]],"vars":[{"name":"The trap: 4.Nc3?","summary":"A natural developing move that loses at once to a queen check.","idea":["The whole point of From's Gambit in one line: if White develops carelessly, the open e1–h4 diagonal and the weak g3 square allow mate in three. Every Bird player must know to play 4.Nf3."],"at":6,"moves":[["Nc3","A natural developing move, but it does nothing to cover h4."],["Qh4+","The queen checks along the open diagonal."],["g3","The only move to block the check."],["Qxg3+","A queen sacrifice: the g3 pawn is taken with check."],["hxg3","White must take: the king has no squares and nothing can block on f2."],["Bxg3#","Checkmate: the bishop takes on g3 and White's king has no escape."]],"vars":[],"played":[0,0,0,0,0,0]}],"played":[12,10,4,3,3,3,3,0,0]},{"name":"Leningrad set-up: 3.g3","summary":"White fianchettoes the king's bishop instead: a Leningrad Dutch with colours reversed.","idea":["White plays g3, Bg2, O-O and d3, then prepares e4 with Qe1 or Nc3, just as Black does in the Leningrad Dutch. With an extra tempo White gets active play in the centre and on the kingside; Black often answers with ...c5, ...Nc6 and ...d4 to gain space."],"at":4,"moves":[["g3","White prepares to fianchetto the king's bishop."],["g6","Black does the same."],["Bg2","The bishop completes the fianchetto and guards the king."],["Bg7","Black's bishop mirrors it."],["O-O","White castles."],["O-O","Black castles."],["d3","White prepares e4, the main break in this structure."],["c5","Black gains space and fights for d4."],["Qe1","The queen prepares e4, which it will support along the e-file, and can later swing to h4."],["Nc6","Black develops and controls d4 and e5. After e4, Black chooses between ...dxe4 and ...d4."]],"vars":[],"played":[23,14,14,17,28,22,23,15,5,3]},{"name":"Stonewall set-up: 4.d4","summary":"White builds a Stonewall with pawns on d4, e3 and f4 and aims a knight at e5.","idea":["With d4 White sets up a Stonewall Dutch with colours reversed: a knight goes to e5, supported by the d4 and f4 pawns, and the bishop on d3 aims at Black's king. The drawbacks are the hole on e4 and the bishop on c1, shut in behind the pawns. Black usually plays ...c5, ...Nc6 and ...Bf5 or ...Ne4 to use the light squares."],"at":6,"moves":[["d4","The Stonewall: d4 joins e3 and f4, and together they control e5."],["Bg7","Black completes the fianchetto."],["Bd3","The bishop takes its most active square, aiming at the kingside."],["O-O","Black castles."],["O-O","White castles."],["c5","Black challenges d4 from the flank."],["c3","White completes the pawn chain, supporting d4. Nbd2, Ne5 and often Qe1–h4 come next."]],"vars":[],"played":[0,0,0,0,0,0,0]}],"played":[566,146,99,39,13,5,2,2,2,3,3,3,3,0,0]}];
